\begin{lemma}\label{lem:glm-orientation}
    The action of $\GL_{s}(\ZZ)[m]$ on $\PD_s$ is orientation preserving if and only if either i) $m\geq 3$ or ii) $m=1,2$ and $s$ is odd. Further, $\QQ_{\mathrm{or}}$ 
    is the determinantal representation of the action of $\GL_{s}(\ZZ)[m]$ on $\PD_s \subset \RR^{(s+1)s/2}$, which is trivial if this action is orientation preserving. 
\end{lemma}
\begin{proof}
    It is shown in \cite[Lemma~7.2]{elbaz-vincent-gangl-soule-perfect} that if $A\in \GL_{s}(\RR)$ and $\det(A)>0$ then the action of $A$ on $\PD_s$ is orientation preserving. If $m\geq3$ then every element of $\GL_s(\ZZ)[m]$ has determinant 1, and so acts in an orientation preserving way. 

    On the other hand, \cite[Lemma~7.2]{elbaz-vincent-gangl-soule-perfect} show that the action of $\GL_{s}(\RR)$ (and hence $\GL_{s}(\ZZ)=\GL_{s}(\ZZ)[1]$) on $\PD_s$ is orientation preserving if and only if $s$ is odd. Thus, all that remains is the case $m=2$. Immediate from the mentioned results, when $s$ is odd the action of $\GL_{s}(\ZZ)[2]$ on $\PD_s$ is orientation preserving. When $m=2$ and $s$ is even, consider the $s\times s$ diagonal matrix $\epsilon=\mathrm{diag}(-1,1,1,\ldots,1)$. As $m=2$ we know that $\epsilon\in \GL_{s}(\ZZ)[2]$, and a computation -- done in \cite[Lemma~7.2]{elbaz-vincent-gangl-soule-perfect} -- verifies the action of $\epsilon$ on $\PD_s$ is orientation reversing if and only if $s$ is even.

    The last claim follows in a similar fashion from \cite[Lemma~7.2]{elbaz-vincent-gangl-soule-perfect} where it is shown that the orientation local system of $\GL_{s}(\RR)$ is given by the determinantal representation via $\GL_s(\RR) \to \GL_{(s+1)s/2}(\RR)$.
\end{proof}

Moreover, we are able to fully compute $W_0 H^*_c(\cA_{g}[m];\QQ)$ in the degrees in which Proposition~\ref{prop:Ag-GL} holds. Following the notation in \cite{brown-bordifications}, let
\[
\Omega_{\mathrm{can}}^{\bullet}\coloneqq \bigwedge \QQ\left\langle \omega_{5},\omega_{9},\cdots,\omega_{4j+1},\cdots \right\rangle
\]
be the $\ZZ$-graded exterior algebra with one generator $\omega_{4j+1}$ in degree $4j+1$ for each integer $j\geq1$. For an integer $k\in \ZZ$ we write $\Omega^k_{\mathrm{can}}$ for the degree $k$ piece of $\Omega_{\mathrm{can}}^{\bullet}$.

\begin{proposition}\label{prop:agm-middle-comps}
Let $m\geq1$ and $g\geq2$ be integers. If $0\leq k\leq g-2$, then
    \[
    \Gr^W_{2d} H^{d+k} 
    \left(\cA_{g}[m];\RR\right)\cong  \RR_{\mathrm{or}}^{\GL_g(\ZZ)[m]} \otimes \left(\Omega^k_{\mathrm{can}}\right)^{\oplus \pi_{g,g,m}}.
   \]
    Further, if $m\geq3$ or $g$ is odd then $\RR_{\mathrm{or}}^{\GL_{g}(\ZZ)[m]}\cong \RR$. 
\end{proposition}

\begin{proof}
    By Proposition~\ref{prop:Ag-GL} for $k$ in the stated range
    \[
    \Gr^W_{2d} H^{d+k} 
    \left(\cA_{g}[m];\QQ\right)\cong  H^{k}\left(\GL_{g}(\ZZ)[m];\QQ_{\mathrm{or}}\right)^{\oplus \pi_{g,g,m}},
   \]
   and so it is enough to compute $H^{k}\left(\GL_{g}(\ZZ)[m];\QQ_{\mathrm{or}}\right)$. Work of Borel \cite[Theorem 7.5]{borel-stable} with improvements by \cite[Example 1.10]{liSun19} shows that for any congruence subgroup $\Gamma$ of $\GL_{g}(\QQ)$, with $g\geq2$, 
\begin{equation}\label{eq:stable-result}
H^k\left(\Gamma; F\right) \cong F^{\Gamma}\otimes H^k_{\text{ct}}\left(^{\circ}GL_{\infty}(\R); \QQ\right) \cong F^{\Gamma} \otimes \left(\Omega^k_{\mathrm{can}}\right)^{\oplus \pi_{g,\Gamma}} \quad \quad \text{for $0\leq k \leq g-2$,}
\end{equation}
and any irreducible finite dimension representation $F$ of $\GL_{n}(\RR)$, where $\pi_{g,\Gamma}$ is the number of $\Gamma$-orbits of $g$-dimensional isotropic subspaces. Note the bound in \eqref{eq:stable-result} is optimal \cite[Section 5.3]{kuperMillerPatzt22}. Applying this result when $n=g$, $\Gamma=\GL_{g}(\ZZ)[m] \subset \GL_{g}(\ZZ)$, and $F = \RR_{\mathrm{or}}$ gives the claimed result. 
\end{proof}


\begin{manualtheorem}{\ref{mainthm-agm-spsec}}
    Let $m\geq1$ and $g\geq2$ be integers. If $0\leq k\leq g-2$ then
    \[
    \Gr^W_{2d} H^{d+k} \left(\cA_{g}[m]; \RR \right)\cong  \begin{cases}
        \left(\Omega^k_{\mathrm{can}}\right)^{\oplus \pi_{g,g,m}} \otimes_\QQ \RR & \text{ if $m\geq 3$ or $m=1,2$ and $g$ is odd} \\
        0 & \text{ else}.
    \end{cases}
    \]
\end{manualtheorem}
\begin{proof}
Since $\QQ_{\mathrm{or}}$ is 1-dimensional $\QQ_{\mathrm{or}}^{\GL_g(\ZZ)[m]}$ isomorphic to $\QQ$ when the action of $\GL_{g}(\ZZ)[m]$ on $\PD_g$ is orientation preserving and zero otherwise. The claim now follows immediately from Proposition~\ref{prop:agm-middle-comps} together with the characterization of when the action of $\GL_{g}(\ZZ)[m]$ on $\PD_g$ is orientation preserving given in Lemma~\ref{lem:glm-orientation}.
\end{proof}

\begin{remark}\label{rem: green boxes}
    In fact, Theorem~\ref{mainthm-agm-spsec} also holds for an arbitrary congruence subgroup $\Gamma \subseteq \Sp_{2g}(\Q)$. If we let $\pi_{g,\Gamma}$ denote the number of $\Gamma$-orbits of $g$-dimensional isotropic subspaces, then by the same argument
    \[
     \Gr^W_{2d} H^{d+k} \left(\Gamma \backslash \cH_g; \RR \right)\cong  \begin{cases}
        \left(\Omega^k_{\mathrm{can}}\right)^{\oplus \pi_{g,\Gamma}} \otimes_\QQ \RR & \text{ if $\Gamma$ is orientation preserving} \\
        0 & \text{ else}.
         \end{cases}
    \]
    A similar statement can be proven in full generality, for $(\mathbb{G},D)$ a connected Shimura datum and any $\Gamma \subset G\cap\GG(\QQ)$.  Let $\pi$ denote the number of $\Gamma$-orbits of rational boundary components of rank equal to the real rank of $G$.  Then by an argument as above, we have
    \begin{equation}\label{eq: green boxes} \Gr^W_{2d} H^{d+k} (\Gamma\backslash D;\QQ) \cong H^k (\overline{\Gamma}_{F_0}, \QQ_{\mathrm{or}})^{\oplus \pi},\end{equation}
    for all indices $0\le k\le \dim(C(F_0)) - \dim(C(F_1)) - 1$. Here $\QQ_{\mathrm{or}}$ denotes the action of $\ov{\Gamma}_{F_0}$ on the orientations of $C(F_{0})$.
\end{remark}

