\begin{proposition}
\label{prop:a2m}
    The weight-zero compactly supported cohomology of $\cA_2[m]$ for $m>2$ is
    \begin{align*}
         W_0 H^2_c(\cA_2[m];\QQ) \cong \Q^{1+ \pi_{2,2,m}(c_{2,m} -c_{3,m})},\ \ \ 
     W_0 H^3_c(\cA_2[m];\QQ) \cong \Q^{\pi_{2,2,m}},
    \end{align*}
    and is 0 otherwise. Furthermore, $\pi_{2,2,m} = \frac{m^4}{2}\prod_{p \mid m} (1 - p^{-4})$.
\end{proposition}

\begin{proof}
By Proposition~\ref{prop:boundary-orbits-count}, the number of $\Gamma[m]$-orbits of $i$-dimensional isotropic subspaces of $V$ is
$$\frac{\phi(m)}{2} \cdot |\{ (2-i)\text{-dimensional isotropic subspaces of } (\Z/m\Z)^4\}| .$$
So,
the chain complex $C_*(\Sigma_\mathcal{W})$ 
is:
\[
\begin{tikzcd}[row sep = .3em, column sep = 2.75em]
    0 \arrow[r] & \mathop{\Q^{\pi_{2,2,m} \cdot c_{3,m}}} \arrow[r, "\partial_3"] & \mathop{\Q^{\pi_{2,2,m} \cdot c_{2,m}}} \arrow[r] & \mathop{\Q^{\pi_{2,2,m}}} \arrow[r] & \mathop{\Q} \arrow[r] & 0, \\
    & C_3 & C_2 & C_1 & C_0
\end{tikzcd}
\]
where $C_i$ is spanned by orbits of cones with $i$ rays. This chain complex is exact at $C_{0}$ and $C_1$ by the same argument as in the case $m = 2$, together with the fact that there is a path between any two rays in $\PDrt_2/\GL_2(\Z)[m]$ through $2$-dimensional cones.


We now compute $H_3(C_*(\Sigma_{\mathcal{W}})) = \ker (\partial_3)$. Since $A_2^{\on{trop}}[m]$ consists of copies of $\PDrt_2/\GL_2(\Z)[m]$ glued along common rays, we can compute $\ker(\partial_3)$ in each $\PDrt_2/\GL_2(\Z)[m]$ individually. Note that this boundary map $\partial_3$ coincides with the boundary map on our link $L$ thought of as a simplicial complex via its triangulation coming from the perfect cones. Since $L$ is an orientable surface, we have $H_3(L;\Q)\cong \Q$, so $\ker(\partial_3) \cong \Q$ in each copy of $\PDrt_2/\GL_2(\Z)[m]$, so $H_3(C_\bullet) \cong \Q^{\pi_{2,2,m}}$.


Finally, we have 
$$\sum_{i=0}^3 (-1)^{i} \cdot \dim H_i(C_\bullet) = \sum_{i=0}^3 (-1)^{i} \cdot \dim C_i \;\; \Rightarrow \;\; H_2(C_\bullet) \cong \Q^{1+ \pi_{2,2,m}(c_{2,m} -c_{3,m})}.$$

The result follows by~\eqref{eq:comparison for Agm}.
\end{proof}





\begin{remark}
    In \cite[Propositions 5.3 and 5.5]{Oda1990MixedHS}, Oda and Schwermer study the weight filtrations on $H^3(\cA_2[m]; \Q)$ and $H^4(\cA_2[m]; \Q)$. They give expressions for $\dim \Gr_{6}^W H^4(\cA_2[m]; \Q)$ and    $\dim \Gr_{6}^W H^3(\cA_2[m]; \Q)$ in line (2) of each proposition. Our result completes this calculation and gives $\dim \Gr_{6}^W H^4(\cA_2[m]; \Q) \cong \Q^{1+ \frac{m^7}{24} \cdot \prod_{p \mid m} (1 - p^{-4})(1 - p^{-2})}$ and $\dim \Gr_{6}^W H^3(\cA_2[m]; \Q) \cong \Q^{\frac{m^4}{2} \prod_{p \mid m} (1 - p^{-4})}$.
\end{remark}

\begin{corollary}
    \label{cor:link-of-A2tropm}
    For $m\geq3$, as a topological space, the link of $A_2^{\trop}[m]$ is homeomorphic to 
    $\pi_{2,2,m}$
 orientable surfaces of genus 
 $ 1-\frac{1}{2}(c_{1,m} - c_{2,m} + c_{3,m})$
        glued together at 
        $\pi_{2,2,m}$
        points as follows. Each surface corresponds to a $\Gamma[m]$ orbit of a 2-dimensional isotropic subspace of $\mathbb{Z}^{2g}$, and each point corresponds to a $\Gamma[m]$ orbit of a 1-dimensional isotropic subspace of $\mathbb{Z}^{2g}$, and these are glued together by containment.
\end{corollary}

\begin{remark}
    For $m\ge 2$, the space $A_2^{\trop}[m]$  (constructed as a geometric realization of the perfect cone admissible collection) is an honest cone complex and not merely a generalized cone complex. 
     That is, no cone is glued to itself in the geometric realization via a nontrivial automorphism.
\end{remark}


\subsection{Tropical modular interpretation}\label{subsection-tropical-modular-interpretation}


We now give an interpretation of $\Agtropm$ as a tropical moduli space. Namely, we define a principally polarized tropical abelian variety (pptav) with level structure, and show that the points of $\Agtropm$ are in bijection with isomorphism classes of pptav's of dimension $g$ with level $m$ structure.  The definition when $m=1$ agrees with \cite[Definition 4.1.1]{bmv}, as verified below.

Throughout this section, let the \emph{standard} symplectic form on $\ZZ^{2g}$ refer to the alternating $\ZZ$-bilinear form $S \col \ZZ^{2g}\times \ZZ^{2g} \to \ZZ$ given by the matrix: 
\begin{equation*}\mattwo{0}{1_g}{-1_g}{0}.\end{equation*}
If $\Lambda$ is a free abelian group of rank $2g$ and $J\col \Lambda\times\Lambda\to \ZZ$ is a symplectic form (i.e.\ an alternating non-degenerate $\ZZ$-bilinear form), we say that an isomorphism of $\ZZ$-modules $\psi\col \Lambda \to \ZZ^{2g}$ (i.e., a choice of $\Z$-basis for $\Lambda$) takes $J$ to the standard symplectic form on $\ZZ^{2g}$ if the diagram 
\[
\begin{tikzcd}[row sep = 3em, column sep = 3em]
    \Lambda \times \Lambda \arrow[r,"J"] \arrow[d,swap, "\psi\times\psi"]& \ZZ \arrow[d,equal]\\
    \ZZ^{2g} \times \ZZ^{2g} \arrow[r,"S"] & \ZZ
\end{tikzcd}
\]
commutes.
In fact, such a choice of $\Z$-basis for $\Lambda$ exists if and only if $\det(J) = 1$. 

We likewise refer to the standard symplectic form on $(\ZZ/m\ZZ)^{2g}$ and an isomorphism of free $(\ZZ/m\ZZ)$-modules taking an alternating $(\ZZ/m\ZZ)$-bilinear form to the standard symplectic form. Further, note that if $\Lambda$ is a free abelian group of rank $2g$ and $J\col \Lambda\times\Lambda\to \ZZ$ is an alternating $\ZZ$-bilinear form, there is an induced alternating $(\ZZ/m\ZZ)$-bilinear form on $(\Lambda/m\Lambda)$. Abusing notation slightly, we call this form $J$ as well. 


\begin{definition}\label{def-pptav}
A {\em principally polarized tropical abelian variety (pptav)} of dimension $g$ with level $m$ structure is a quadruple $(\Lambda,J,i,Q)$, where:
\enumnow{\item $\Lambda$ is a free abelian group of rank $2g$;
\item $J\col \Lambda\times\Lambda\to \ZZ$ is a symplectic form on $\Lambda$ having determinant $1$;
\item $i\col \Lambda/m\Lambda\xra{\cong} (\ZZ/m\ZZ)^{2g}$ is an isomorphism taking $J$ to the standard symplectic form on $(\ZZ/m\ZZ)^{2g}$;
\item $Q\col \Lambda_\RR\times\Lambda_\RR\to\RR$ is a positive semidefinite form on $\Lambda_\RR$ with kernel $W^\perp$, for $W$ a $\Lambda$-rational subspace of $\Lambda_\RR$ that is isotropic with respect to $J$.
}
\end{definition}


If $(\Lambda,J,i,Q)$ and $(\Lambda',J',i',Q')$ are pptav's of dimension $g$ with level $m$ structure, an \emph{isomorphism} between them is an isomorphism of $\ZZ$-modules $\Lambda\to \Lambda'$ taking $J$ to $J'$, $i$ to $i'$, and $Q$ to $Q'$. 
We denote the \emph{isomorphism class} of $(\Lambda,J,i,Q)$ by $[\Lambda,J,i,Q]$. Let $S_{g,m}$ denote the set of isomorphism classes of pptav's of dimension $g$ with level $m$ structure.















\begin{lemma}\label{lem:fix-trop-mod}
    Let $\Lambda = \Z^{2g}$ and $J$ be the standard symplectic form on $\Lambda$. Then there is a surjection of sets:
    \[
\begin{tikzcd}[column sep = 4.5em, row sep = .5em]
    \displaystyle \bigsqcup_{\substack{W\subset \Lambda_{\QQ}\\ \text{J-isotropic}}} \PD(W^\vee_\R) \arrow[r, two heads, "\Phi"] & S_{g,m}.
\end{tikzcd}
\]
\end{lemma}

\begin{proof}
    Throughout the proof, $i: \Lambda/m\Lambda \to (\Z/m\Z)^{2g}$ will denote the identity isomorphism. 

    Let us first define $\Phi$. For any isotropic subspace $W\subset \Lambda_\Q$, recall that $J$ induces an isomorphism $W_\R^\vee \cong \Lambda_\R/W_\R^\perp$ (see Subsection~\ref{subsub:type-C}). 
    By precomposing with the quotient map $\Lambda_\R \twoheadrightarrow \Lambda_\R/W_\R^\perp$, a form $T \in \PD(W_\R^\vee) \cong \PD(\Lambda_\R/W_\R^\perp)$ therefore induces a positive semidefinite form on $\Lambda_\R$ with kernel $W_\R^\perp$; let us denote this positive semidefinite form by $Q_T$.
    We define $\Phi$ to send 
    $T$ to the isomorphism class of the pptav $(\Lambda, J, i, Q_T)$.

    To prove surjectivity, we first show that (the isomorphism class of) any pptav of the form $(\Lambda, J, i, Q)$ is in the image of $\Phi$. Indeed, given any positive semidefinite form $Q$ on $\Lambda_\R$ with kernel $W_\R^\perp$ for some isotropic subspace $W \subset \Lambda_\Q$, the form $Q$ naturally induces a form $T_Q \in  \PD(W_\R^\vee) \cong \PD(\Lambda_\R/W_\R^\perp)$ and the image of $T_Q$ under $\Phi$ precisely equals $[\Lambda, J, i, Q]$.

    To end the proof, we let $(\Lambda', J',i',Q')$ be any pptav of dimension $g$ with level $m$ structure, and show that it is isomorphic to some pptav of the form $(\Lambda, J, i, Q)$. Let $I' : \Lambda' \to \Z^{2g}$ be an isomorphism taking $J'$ to the standard symplectic form on $\Z^{2g}$; such an isomorphism exists because $J'$ is assumed to have determinant $1$ by Definition~\ref{def-pptav}. Moreover, since the mod $m$ reduction $\Sp_{2g}(\Z) \to \Sp_{2g}(\Z/m\Z)$ is surjective by \cite[Theorem 1]{newman-smart}, we can pick $I'$ so that the diagram
    \[
\begin{tikzcd}[column sep = 3.5em, row sep = 3em]
    \Lambda' \arrow[r, "I'"] \arrow[d,two heads]& \ZZ^{2g} = \Lambda \arrow[d,two heads] \\
    \Lambda'/m\Lambda' \arrow[r,"i'"] & (\ZZ/m\ZZ)^{2g} = \Lambda/m\Lambda
\end{tikzcd}
\]
commutes. Therefore, the map $I': \Lambda' \to \Lambda$ induces an isomorphism of pptav's between $(\Lambda',J',i',Q')$ and $(\Lambda,J,i,Q)$, where $Q$ is the pullback of $Q'$ along $(I')^{-1}$, finalizing the proof.
\end{proof}


\begin{theorem}\label{thm:modular interpretation}
    Continue to assume $\Lambda = \Z^{2g}$ and $J$ is the standard symplectic form on $\Lambda$. Then there exists a bijection of sets $\Psi: \Agtropm \to S_{g,m}$
    such that the following diagram commutes.
\[
\begin{tikzcd}[column sep = 2.5em, row sep = 3.5em]
    \displaystyle \bigsqcup_{\substack{W\subset \Lambda_{\QQ}\\ \text{J-isotropic}}} \PD(W^\vee_\R) \arrow[d, two heads, swap, "\Phi"] \arrow[r,two heads,"\pi"] & \Agtropm \arrow[dl,rightarrow,dashed,"\Psi"] \\
    S_{g,m}
    & 
\end{tikzcd}
\]
\end{theorem}

\begin{proof}
    Let us construct inverse maps $\Psi:\Agtropm\to S_{g,m}$ and $\Psi':S_{g,m}\to \Agtropm$. Continue to let $i:\Lambda/m\Lambda \to (\Z/m\Z)^{2g}$ denote the identity isomorphism.

    Note first that, as suggested by the diagram above, the set $\bigsqcup_W \PD(W^\vee_\R)$ naturally covers $\Agtropm$ since the support of any admissible collection, as a set, precisely equals the union of the cones $C(W) = \PD(W^\vee_\R)$ over all isotropic subspaces $W$ (see Remark~\ref{rem:adm-decomp-support}). 
    Given a point $p \in \Agtropm$, let $T\in \PD(W^\vee_\R)$ be an element covering it and define $\Psi(p)=[\Lambda, J,i,Q_T]$ for $Q_T:\Lambda_\R \times \Lambda_\R \to \R$ the positive semidefinite form with kernel $W_\R^\perp$ that $T$ induces as in the proof of Lemma~\ref{lem:fix-trop-mod}. This is well-defined because two forms $T \in \PD(W^\vee_\R)$ and $T' \in \PD\big((W'_\R)^\vee \big)$, for $W,W' \subset \Lambda_\Q$ isotropic, descend to the same point in $\Agtropm$ if and only if the induced forms $Q_T, Q_{T'}$ on $\Lambda_\R$ differ by an element of $\Sp_{2g}(\Z)[m]$.

    Conversely, recall from the proof of Lemma~\ref{lem:fix-trop-mod} that every isomorphism class in $S_{g,m}$ has a representative $(\Lambda,J,i,Q)$. Define $\Psi'$ to send $[\Lambda,J,i,Q]$ to the point $\pi(T_Q) \in \Agtropm$, where $T_Q$ is as described in the proof of Lemma~\ref{lem:fix-trop-mod}. This is well-defined because, if $[\Lambda, J, i, Q] = [\Lambda, J, i, Q']$, then there exists an element of $\Sp_{2g}(\Z)[m]$ taking $Q$ to $Q'$, meaning that $\pi(T_Q) = \pi(T_{Q'})$.


It is straightforward to check that $\Psi$ and $\Psi'$ are inverses of each other.   
\end{proof}


\begin{remark}\label{rem:same as bmv}
    For $m=1$, i.e.\ the case with no level structure, pptav's were defined by \cite{bmv} as pairs $(L, Q)$, where $L\cong \ZZ^g$ is a free abelian group and $Q$ is a positive semidefinite form on $L_\RR$ with $L$-rational kernel; and two such pairs are isomorphic if they differ by an element of $\GL_g(\Z)$. For this $m=1$ case, there is a natural bijection between isomorphism classes of pptav's as in Definition~\ref{def-pptav} and isomorphism classes of pptav's in the sense of~\cite{bmv}. Indeed, this is precisely Theorem~\ref{thm:modular interpretation} specialized to $m = 1$, since $A_g^\trop \cong \PD^{\text{rt}}\!/\GL_g(\Z)$, and the points of the latter are in bijection with isomorphism classes of pptav's in the sense of~\cite{bmv}. 
\end{remark}



