The doubling phenomenon then yields the data in Table~\ref{table: spectral sequence disc -4 undoubled}, as well as the following lower bounds on the dimensions of the homology groups, which are illustrated in the $s=5$ column of Table~\ref{table: spectral sequence disc -4}.
\begin{proposition}\label{prop:1 and 3}
    The homologies of $\GL_5(\Z[i])$ and $\GL_5(\Z[\zeta_3])$ satisfy
    $$
    \dim H_{4}(\GL_{5}(\Z[i]); \St_5(\Q(i)) \otimes \Q) \ge 2, \quad
     \dim H_{4}(\GL_{5}(\Z[\zeta_3]); \St_5(\Q(\zeta_3)) \otimes \Q) \ge 2.
    $$
    For $k \in \{7,9,12\}$, they satisfy
    $$
    \dim H_{k}(\GL_{5}(\Z[i]); \St_5(\Q(i)) \otimes \Q) \ge 1, \quad
    \dim H_{k}(\GL_{5}(\Z[\zeta_3]); \St_5(\Q(\zeta_3)) \otimes \Q) \ge 1.
    $$
\end{proposition}

\begin{proof}
Let $R$ be either $\Z[i]$ or $\Z[\zeta_3]$, and $E$ its field of fractions. Then
from (the dual of) ~\eqref{eq:general-doubling-phenomenon}  
it follows that 
$$
  \bigoplus_{n,k} H_{k} (\GL_n(R); \St_n(E) \otimes \QQ)
  \cong 
  \left(
  \bigoplus_{n,k} H_{n+k}^{\mathrm{BM}} (\PD_n^{E\text{-rt}} \!/ \GL_n(R);\QQ)
  \right) \otimes \QQ[x]/(x^2).
$$
In particular, if $H_{k}(\GL_{n-1}(R); \St_{n-1}(E) \otimes \Q) = 0$ and $\dim H_{k}(\GL_{n}(R); \St_{n}(E) \otimes \Q) = d$, then $H_{n-1+k}^{\mathrm{BM}}(\PD_n^{E\text{-rt}}/\GL_n(R);\Q) = 0$ and $\dim H_{n+k}^{\mathrm{BM}}(\PD_n^{E\text{-rt}}/\GL_n(R);\Q) = d$.

This implies that $\dim H_{k+1}(\GL_{n}(R); \St_{n}(E) \otimes \Q) \ge d$. Applying this observation to $k \in \{4,7,9,12\}$, with the results from Table~\ref{table: spectral sequence disc -4}, the result follows.
\end{proof}

