        B=\left(\begin{array}{cc}
        0 & b \\
        -b & 0
        \end{array}\right), \\
        C=\left(\begin{array}{cc}
        0 & -c \\
        c & 0
        \end{array}\right), \\
        D=\left(\begin{array}{cc}
        d & 0 \\
