         \begin{equation}\label{innerproductA_0}
             \langle f,g\rangle_{\mathcal{A}_0}(l)=e(\langle-T(l),J'T(l)/2\rangle)\int_{\R\times \Z_c}\langle x,-T''(l)\rangle g(x+T'(l))\overline{f(x)}dx,
         \end{equation}
         \begin{equation}\label{V_lf}
             V_l.f(x)=e(\langle-S(l),J'S(l)/2\rangle)\langle x,-S''(l)\rangle f(x+S'(l)),
