             \prescript{}{\mathcal{B}_0}\langle f,g\rangle(l)=K\cdot e(\langle S(l),J'S(l)/2\rangle)\int_{\R\times \Z_c}\langle x,S''(l)\rangle \overline{g(x+S'(l))}{f(x)}dx
