\section{Preliminaries}
In this section, we give the basic definitions, notations and fundamental assumptions that provide a foundation for the results given in this paper.
There are several approaches to the generalization of the notation of differentiation to fractional orders e.g. the Riemann-Liouville and the Caputo approach.\\
\textbf{Definition 1}. A fractional integral operator of order $\alpha(\alpha>0)$ of type Riemann-Liouville [2-24] is defined by
\vspace*{0.2cm}
\begin{equation}
\begin{cases}
J^{\alpha} f(t)=\frac{1}{\Gamma(\alpha)} \int_{0}^{t} (t-s)^{\alpha-1} f(s) ds,&\alpha,t>0,\\
J^0 f(t)=f(t).
\end{cases}
\end{equation}
\vspace*{0.2cm}
In (1), $\Gamma$ is the Gamma function. The fundamental properties of $J^\alpha$ for $f(t)$ are
\begin{compactenum}[1$^o$]
\item $J^\alpha J^\theta f(t)=J^{\alpha+\theta} f(t)$.
\item $J^\alpha t^\gamma =\frac{\Gamma(\gamma+1)}{\Gamma(\alpha+\gamma+1)} t^{\alpha+\gamma}, \Gamma(\alpha+\gamma+1) > 0$.
\item $J^\theta J^\alpha f(t)=J^\alpha J^\theta f(t)$, commutativity property.
\end{compactenum} 
\vspace*{0.2cm}
\textbf{Definition 2.} Fractional derivatives of order $\alpha$ of $f(t)$ of type Caputo are defined by
\begin{equation}
D^\alpha f(t)=J^{n-\alpha} D^n f(t)=\frac{1}{\Gamma(n-\alpha)} \int_{0}^{t} (t-s)^{n-\alpha-1} \frac{d^n}{ds^n} f(s), t>0, n-1<\alpha<n.
\end{equation}
In (2), $D^n$ is a differential operator of order $n$. In addition,
\begin{equation}
D^\alpha t^\mu =\begin{cases}
0&\mu\in N_0, \mu<\lceil \alpha \rceil \\
\frac{\Gamma(\mu+1)}{\Gamma(\mu+1-\alpha)} t^{\mu- \alpha}&\mu \in N_0, \mu\geq \lceil \alpha\rceil or \mu \notin N, \mu>\lfloor \alpha\rfloor,
\end{cases}
\end{equation}
In (3), $N=1,2,\dots$ (natural numbers) and $N_0=0,1,2,\dots$ (an integer greater than or equal to 0). Next, consider\\
\textbf{Definition 3}. Let $(\Omega,F,P)$ be a probability space with filteration ${\{F_t\}}_{t\geq 0}$. The Brownian motion $B$ is a stochastic process over a a probability space $(\Omega,F,P)$ with filteration ${\{F_t\}}_{t\geq 0}$, having the following properties [27]:
\begin{enumerate}
	\item $B(0)=0$ (0 is a Spanier-Brouwer fixed point for $B:\mathbb{R}\rightarrow \mathbb{R}$~[31],[41],[42]).
	\item $B(t)-B(s), t>s$ is independent of $F_s$, such that
	\item $B(t)-B(s)$ is normally disributed with mean $\mu = 0$ and variance $t-s$.
	\item $B(t), t\geq 0$ is a continuous function.
\end{enumerate}
\vspace*{0.2cm}
\textbf{Definition 5}. An integral of the form$\int_{a}^{b} f(t) dB(t)$ where $B(t)$ denotes the Brownian motion process can be defined in various ways. This integral can be approximated as
\begin{equation}
\sum_{i=1}^{n} f(\tau_i)(B(t_i)-B(t_{i-1}))
\end{equation}
where $\tau_i$ is chosen arbitrary in the subinterval $[t_{i-1},t_i]$ of the partition $ a=t_0<t_1<\cdots<t_n=b$. If $\tau_i$ is taken as $t_{i-1}$, (4) is an It\^o integral and if , (4) is a Stratonovich integral.
\section{Properties of Legendre and shifted Legendre polynomials}
The Legendre polynomials $L_n(x)$, are defined on the interval $I=[-1,1]$ have the following properties
\begin{equation}
L_0=1,
 L_1=x,
 \cdots,
  L_\text{i+1}(x)=\frac{2i}{i+1}L_i(x)-\frac{i}{i+1}L_\text{i-1}(x),
\end{equation} 
In order to use these polynomials on the interval $x\in I=[a,b]$ we define the so-called shifted Legendre polynomials by introducing the change of variable $t=\frac{2x}{I}-1$. Let $P_i(x)$ denote the shifted Legendre polynomials and we define shifted Legendre polynomials as:
\begin{equation}
\begin{cases}
P_0=1, P_1(x)=\frac{2x-(b+a)}{b-a}\\
P_i(x)=(2-\frac{1}{i})(\frac{2x-(b+a)}{b-a})P_\text{i-1}(x)-(1-\frac{1}{i})P_\text{i-2}(x), i=2\cdots,
\end{cases}
\end{equation}
For example these polynomials on the interval $[0,1]$ can be obtained as 
\begin{equation}
P_\text{i+1}(x)=\frac{(2i+1)(2x-1)}{(i+1)}P_i(x)-\frac{i}{i+1}P_\text{i-1}(x), i=1,2,\cdots,
\end{equation}
where $P_0=1$ and $P_1(x)=2x-1$.
The analytical form of the shifted Legendre polynomials $P_i(x)$ of degree $i$ is given by
\begin{equation}
P_i(x)=\sum_{k=0}^i (-1)^\text{i+k} \frac{(i+k)!x^k}{(i-k)!(k!)^2 I^k}
\end{equation}
note that $P_{i}(0)=(-1)^i$ and $P_i(1)=1$. The orthogonality condition is
\begin{equation}
\int_0^I P_i(x)P_j(x)\omega_I(x)dx=h_I,k\sigma_jk,
\end{equation}
where $\omega_I=1$ and $h_I,k=\frac{I}{(2k+1)}$.
A function $u(x)$, square integrable on $I=[a,b]$, can be expressed in terms of shifted Legendre polynomials as
\begin{equation}
u(x)=\sum_{j=0}^{m} u(x)P_j(x)dx, j=0,1,2,\cdots.
\end{equation}
In practice, only the first $(m+1)$-terms of shifted Legendre polynomials are considered. Hence, we have
\begin{equation}
u(x)=\sum_{j=0}^{m} c_jP_(x)=C \psi(x),
\end{equation}
where $C$ is a shifted Legendre coefficient vector and $\phi$ is a shifted Legendre vector as the following
\begin{equation}
C=[c_0,c_1,\cdots,c_m],  \psi(x)=[P_0(x),P_1(x),\cdots,P_m(x)]^T.
\end{equation}
\textbf{Theorem 1}. The derivative of the vector $\psi(x)$ can be expressed by
\begin{equation}
D\psi(x)=\Lambda^\text{(1)} \psi(x),
\end{equation}
where $\Lambda^{(1)}$ is the $(m+1) \times(m+1)$ operational matrix of derivative given by
\begin{equation}
\Lambda^{(1)}=[(d_{ij})]^T=
\begin{cases}
$2(2j+1), \text{for} j=i-k$,\\
0, \text{otherwise},
\end{cases}
\end{equation}
where $i,j$ are numbers of the rows and columns respectively on the interval $[0,1]$.\\
For example for even $m$ we have
\begin{equation*}
\Lambda^{(1)}=\begin{bmatrix}
0&0&0&0&\ldots&0&0&0\\
1&0&0&0&\ldots&0&0&0\\
0&3&0&0&\ldots&0&0&0\\
1&0&5&0&\ldots&0&0&0\\
1&0&5&0&\ldots&(2m-3)&0&0\\
0&3&0&7&\ldots&0&(2m-1)&0
\end{bmatrix}
\end{equation*}
By using equation(8) for $n \in N$, we have
\begin{equation}
D^n \psi(x)=(\Lambda^{(1)})^n \psi(x).
\end{equation}\\
\textbf{Theorem 2.} Let $\psi(x)$ be a shifted Legendre vector with $\alpha>0$, then, from [33], we have\\
$D^\alpha \psi(x)\simeq D^{(\alpha)} \psi(x)$,\\
such that $D^{(\alpha)}=(m+1)\times (m+1)$, an operational matrix of a Caputo fractional derivative of order $\alpha$ defined by
\begin{equation}
D^{(\alpha)}=\begin{bmatrix}
0&0&\ldots&0\\
\vdots&\vdots&\ldots&\vdots\\
0&0&\ldots&0\\
\sum_{k=\lceil \alpha \rceil}^{\lceil \alpha \rceil} \theta_{\lceil \alpha \rceil,0,k}&\sum_{k=\lceil \alpha \rceil}^{\lceil \alpha \rceil} \theta_{\lceil \alpha \rceil,1,k}&\ldots&\sum_{k=\lceil \alpha \rceil}^{\lceil \alpha \rceil} \theta_{\lceil \alpha \rceil,m,k}\\
\vdots&\vdots&\ldots&\vdots\\
\sum_{k=\lceil \alpha \rceil}^{i} \theta_{i,0,k}&\sum_{k=\lceil \alpha \rceil}^{i} \theta_{i,1,k}&\ldots&\sum_{k=\lceil \alpha \rceil}^{i} \theta_{i,m,k}\\
\vdots&\vdots&\ldots&\vdots\\
\sum_{k=\lceil \alpha \rceil}^{m} \theta_{m,0,k}&\sum_{k=\lceil \alpha \rceil}^{m} \theta_{m,1,k}&\ldots&\sum_{k=\lceil \alpha \rceil}^{m} \theta_{m,m,k}\\
\end{bmatrix},
\end{equation}
where %$\theta_{i,j,k}$ is given by
\begin{equation}
\theta_{i,j,k}=(2j+1)\sum_{l=0}^{j} \frac{(-1)^{i+j+k+l} (i+k)! (l+j)!}{(i-k)! k! \Gamma{(k-\alpha+1)} (j-l)! (l!)^2 (k+l-\alpha +1)}.
\end{equation}\\
%Note that in $D^{(\alpha)}$, the first $\lceil \alpha \rceil$ rows, are all zero.\\
\textbf{Proof}. See[33].
\\2-D shifted Legendre polynomials are defined on $\Delta=[0,a] \times[0,b]$ as follows
\begin{equation}
P_{r,s}(x,t)=P_r(x) P_s(t)=\psi(x) \times \Phi(t) , i,j=0,1,2,\cdots,
\end{equation}
and from  [30], $P_{r,s}(x,t)$ is defined by
\begin{equation}
\int_{0}^{s} \int_{0}^{z} P_{r,s}(x,t) dxdt \simeq W P_{r,s}(x,t)=(Q_{1} \otimes Q_{2}) P_{r,s}(x,t)
\end{equation}
such that $x \in[0,a], t \in[0,b]$, $W$ is $(m+1)^2 \times (m+1)^2$
 %operational matrix of integration 
and $Q_1$, $Q_2$ are operational matrices of 1-D shifted Legendre polynomials on $[0,a]$ and $[0,b]$ defined by
\begin{align*}
Q_1 &=\begin{bmatrix}
1&1&0&\ldots&0&0&0\\
-\frac{1}{3}&0&\frac{1}{3}&\ldots&0&0&0\\
\vdots&\vdots&\vdots&\vdots&\vdots&\vdots&\vdots\\
0&0&0&\ldots&-\frac{1}{2m-1}&0&\frac{1}{2m-1}
\end{bmatrix},\\
Q_2 &=\begin{bmatrix}
1&1&0&\ldots&0&0&0\\
-\frac{1}{3}&0&\frac{1}{3}\ldots&0&0&0\\
\vdots&\vdots&\vdots&\vdots&\vdots&\vdots&\vdots\\
0&0&0&\ldots&-\frac{1}{2m-1}&0&\frac{1}{2m-1}\\
0&0&0&\ldots&0&-\frac{1}{2m+1}&0
\end{bmatrix}.
\end{align*}
Also, we can write[14]
\begin{equation}
\int_{0}^{x} P(x,t) dx \simeq Q_{3} P(x,t), 
\int_{0}^{t} P(x,t) dt \simeq Q_{4} P(x,t).
\end{equation}\\
where $Q_{3}$ and $Q_{4}$ are $(m+1)^{2} \times (m+1)^{2}$ matrices of the form
\begin{equation*}
Q_3=\begin{bmatrix}
I&I&O&\ldots&O&O&O\\
-\frac{I}{3}&O&\frac{I}{3}&\ldots&O&O&O\\
\vdots&\vdots&\vdots&\ddots&\vdots&\vdots&\vdots\\
O&O&O&\ldots&-\frac{I}{2m-1}&O&\frac{I}{2m-1}\\
O&O&O&\ldots&O&-\frac{I}{2m+1}&O
\end{bmatrix},
Q_4=\begin{bmatrix}
p_2&O&O&\ldots&O\\
O&p_2&O&\ldots&O\\
O&O&p_2&\ldots&O\\
\vdots&\vdots&\vdots&\ddots&\vdots\\
O&O&O&\ldots&p_2
\end{bmatrix}.
\end{equation*}\\
where I and O are the identify and zero matrix of order $(m+1)$, respectively and $p_2$ is a square matrix of order $(m+1)$ which is defined by
\begin{equation*}
p_2=\frac{b-a}{2} \begin{bmatrix}
1&1&0&\ldots&0&0&0\\
-\frac{1}{3}&0&\frac{1}{3}&\ldots&0&0&0\\
\vdots&\vdots&\vdots&\ddots&\vdots&\vdots&\vdots\\
\vdots&\vdots&\vdots&\ddots&-\frac{1}{2m+1}&0&\frac{1}{2m+1}\\
0&0&0&\ldots&0&-\frac{1}{2m+1}&0
\end{bmatrix}.
\end{equation*}

\textbf{Theorem 3}. We can express the function of $u(x,t)$ as the following matrix form
\begin{equation}
u(x,t)=\sum_{r=0}^{\infty} \sum_{s=0}^{\infty} c_{r,s} P_{r,s}(x,t)=\psi(x) \Phi(t) \bar{C},
\end{equation}
where $\bar{C}$ is the unknown Legendre coefficient matrix
\begin{equation*}
\bar{C}=[c_{0,0},c_{0,1},\cdots,c_{0,m},c_{1,0},c_{1,1},\cdots,c_{1,m},\cdots,c_{m,0},\cdots,c_{m,m}]_{(m+1)^2 \times1}^{T}
\end{equation*}
where the coefficient matrix $\bar{C}$ is given by
\begin{equation}
c_{i,j}=\frac{(2i+1)}{b-a} \int_{a}^{b} \int_{a}^{b} u(x,t)L_{i}(x) L_{j}(t) dx dt
\end{equation}
and
\begin{equation*}
\Phi(t)=\begin{bmatrix}
P_0(t)&\ldots&P_m(t)&0&0&0&\ldots&0&0&0\\
0&0&0&P_0(t)&\ldots&P_m(t)&\ldots&0&0&0\\
\vdots&\vdots&\vdots&\vdots&\vdots&\vdots&\ddots&\vdots&\vdots&\vdots\\
0&0&0&0&0&0&\ldots&P_0(t)&\ldots&P_m(t)\\  
\end{bmatrix}.
\end{equation*}
is a matrix of order ${(m+1)\times (m+1)^2}$.\\
\textbf{Proof}: See proof in[24].\\

\section{Analysis of the solution method}
This section is devoted to analyze a numerical solution of the following fractional stochastic integro-differential equation based on the presented method
\begin{equation}
D^\alpha f(t)=g(t)+ \int_{0}^{t} k_1(s,t) f(s) ds+ \int_{0}^{t} k_2(s,t) f(s) dB(s),
\end{equation} 
where $g(t)$, $k_1(t,s)$ and $k_2(t,s)$ are given functions on the same probability space $(\Omega,F,P), f(t)$ is the unknown function and $B(t)$ is a Brownian motion also, $t,s \in [0,1]$ are variables.\\
In order to use the proposed method, we pursue the following process. We expand functions $f(t), g(t)$ in the following approximations
\begin{equation}
f_n (t)=\bar{f}\psi(t),
\end{equation}
\begin{equation}
g_n (t)=\bar{g}\psi(t),
\end{equation}
where $\bar{f}$ and $\bar{g}$ are coefficient vectors that $ \bar{f}=[f_{0}, f_1,\cdots,f_m] $ and $ \bar{g}=[g_0, g_1, \cdots, g_m]$. Also, by using equation(21) we approximate $k(s,t)$ as the following
\begin{equation}
k_n (s,t)=\psi(s) \Phi(t) \bar{k},
\end{equation}
where $\bar{k}$ is a vector and its elements obtain similar to equation(22)
Now, we approximate $ D^\alpha f(t)$ as
\begin{equation}
D^\alpha f_n(t)=\bar{f} D^{(\alpha)} \Psi(t). 
\end{equation}
In order to approximate the first integral in equation(23) by applying equation(20), we have
\begin{equation}
\int _{0}^{t} k_{1,m} (s,t) f_{m}(s) ds=\int_{0}^{t} \psi(s) \Phi(t) \bar{C} \Psi(s) \bar{f} ds =\bar{f} \Phi(t) Q_{3} \bar{k_1}.
\end{equation}
Now we approximate the second integral in equation(23) by applying the following operation mertix from equation (20)
\begin{equation}
\int_{0}^{t} P(s,t)dB(s)=\bar{Q_3}P(s,t),
\end{equation}
where $\bar{Q_3}$ is a matrix of order $(m+1)\times (m+1)$ is given by
\begin{equation}
\bar{Q_3}=\begin{bmatrix}
\bar{B}&\bar{B}&O&\ldots&O&O&O\\
-\frac{\bar{B}}{3}&O&\frac{\bar{B}}{3}&\ldots&O&O&O\\
\vdots&\vdots&\vdots&\ddots&\vdots&\vdots&\vdots\\
O&O&O&\ldots&-\frac{\bar{B}}{2m-1}&O&\frac{\bar{B}}{2m-1}\\
O&O&O&\ldots&O&-\frac{\bar{B}}{2m+1}&O
\end{bmatrix},
\end{equation}
where $\bar{B}$ is a diagonal matrix of order $(m+1)$ which the elements of this matrix is given by\\
$\bar{B_i}=B(\varphi_i)-B(\varphi_{i-1}) $, \\
where $B(\varphi)$ denots the Brownian motion which is normalized as follows\\
$B(\varphi)=\sqrt{\varphi} N(0,1),$
on the subinterval $[\varphi_{i-1}, \varphi_{i}]$ of the partition $a=\varphi_0<\varphi_1<\ldots<\varphi_{m}=b$.\\
Now, by employing equations(4), (26), (20) and (29) in the second integral in equation(23) we have
\begin{equation}
\int_{0}^{t} k_{2,m} (s,t) f_m(s) dB(s)=\int_{0}^{t} \psi(s) \Phi(t) \bar{k_2} \psi(s) \bar{f} dB(s)=\bar{f} \Phi(t)^{T} \bar{Q3} \bar{k_2}.
\end{equation}
where vector $\bar{k_2}$ is known and obtain similar to equation (22).\\
We collocate equation (23) at (m+1) points $s_{\delta}=t_{\delta}, \delta=0,1,2,\ldots,(m+1)$ as\\
\begin{equation}
\bar{f}D^\alpha \psi(t_{\delta})=\bar{g}\psi(t_{\delta})+ \int_{0}^{t} k_{1,m}(s_{\delta},t_{\delta}) f_m(s_{\delta}) ds+ \int_{0}^{t} k_{2,m}(s_{\delta},t_{\delta}) f_m(s) dB(s).
\end{equation}
For collocation points, we use roots of shifted Legendre polynomials $P_{(m+1)-r}(t),m>r$, these equations together with $r$ equations of boundary and initial conditions give $(m+1)$ linear or nonlinear algebraic equations. These $(m+1)$ equations can be solved by using Gauss elimination method or Newton's iterative method respectively. 
\section{Error Analysis}
In this section, an error estimation for the approximate solution is provided. For this purpose, we pursue the proposed convergence analysis in [38] by Taheri et al. \\
To obtain an error estimation for the approximate solution of equation (23) with supplementary conditions, we call $e_{n}(t)=f(t)-f_{m}(t)$ the error function of the presented method. Therefore, $f_{m}(t)$ satisfies the following equation
\begin{equation}
D^\alpha f_m(t)=g_n(t)+\int_{0}^{t} k_{1,m}(t,s)f_{m}(s) ds+\int_{0}^{t}k_{2,m}(t,s) f_{m}(s) dB(s) +H_{m}(t), t\in [0,1]
\end{equation}
which $H_{m}(t)$ is the perturbation term. Now by subtracting equation (23) from equation (30)
\begin{align*}
D^{\alpha}(f(t)-f_m(t)) &=(g(t)-g_{m}(t))\\
&+\int_{0}^{t} k_{1}(t,s)f(s)-k_{1,m}(t,s)f_{m}(s) ds\\ 
&+ \int_{0}^{t} k_{2}(t,s)f(s)- k_{2,m}(t,s)f(s) dB(s) -H_{m}(t), t \in [0,1].\ (34)
\end{align*}
We rewrite equation (34) in the following form\\
\begin{equation}
e_m(t)=I^{\alpha}(\int_{0}^{t} k_1(s,t) e_{m}(s) ds)+ I^{\alpha}(\int_{0}^{t} k_2(s,t) e_{m}(s) dB(s))- H_m(t).
\end{equation} 
So, we have\\
\begin{equation}
e_{m}(t)=E_1+E_2+E_3.
\end{equation}
Now, we state some properties and theorem in the following.\\
Suppose that $f_{m}(t)$ is the best approximation of $f(t)$ which is approximated by shifted Legendre polynomials in $[a,b]$ so, we have\\
\textbf{Theorem 4}. Let $f_{m}(t)=\bar{f} \psi(t)$ where $\bar{f}=[f_0,\ldots,f_m]$ and 
\begin{equation*}
f_{m}=(2m+1) \int_{0}^{1} f(t) P_m(t) dt,
\end{equation*} 
then there exists a real number $\bar{z}$ such that
\begin{equation}
\|f(t)-f_m(t)\|_{2} \leq \bar{z} \frac{1}{(m+1)! 2^{2m+1}}
\end{equation}\\
where $\|f\| = \int_{0}^{1} |f(t)|^{2} dt$.\\
\textbf{Proof}. See [16]. \\
To approximate $E_1 and E_2$ by applying equation(37) we have\\
\begin{equation*}
\|E_1\|\leq \frac{1}{\Gamma(\alpha)} max_{s,t\in I}|k_1(s,t)| \|f(t)-f_m(t)\|,
\end{equation*}
so we have\\
\begin{equation}
\|E_1\|\leq \bar{z} \frac{1}{\Gamma(\alpha) (m+1)! 2^{2m+1}} max_{s,t\in I}|k_1(s,t)|.
\end{equation}
In the same way for $E_2$, we can write\\
\begin{equation}
\|E_2\|\leq \bar{z} \frac{1}{\Gamma(\alpha) (m+1)! 2^{2m+1}} max_{s,t\in I}|k_2(s,t)|
\end{equation}
and for $E_3$ we have\\
\begin{equation}
\|E_3\|=\frac{1}{\Gamma(\alpha)}\|H_m(t)\|.
\end{equation}\\
Therefore, by replacing equations(38-40) in equation (36), we obtain:
\begin{equation}
\|e_{m}\|^{2}\leq \frac{1}{Gamma(\alpha)}(\bar{z} \frac{max_{s,t \in I}(|k_1(s,t)|+|k-2(s,t)|)}{(m+1)!2^{2m+1}}).
\end{equation}


\section{Application and Numerical Examples}
In this section, some applications of stochastic differential equations, fractional stochastic differential equations and fractional Fokker-Planck equations are presented. Moreover, numerical examples are given to illustrate the high accuracy of the presented method.\\
In recent years, it has turned out many phenomena in signal processing and filtering, Population dynamics, economics, finance, fluid dynamics, microelectrons, structural mechanics, chemistry and medicine and etc can be successfully modelled by stochastic differential equations[11,9,12,1]. Ornstein and Uhlenbeck expressed a model to study the behaviour of gasses by the theory of stochastic differential equations. Ornstein and Uhlenbeck were interested in the velocity of an individual molecule of gas. Their equation is given by
\begin{equation*}
dX_{t}=-\alpha X_{t} dt+ \rho dB_{t}  with X_{0}=x_{0}
\end{equation*}
where $\alpha$ and $\rho$ are positive constants. In this equation $-\alpha X_{t} dt$ is negative when $X_{t}$ is larger than zero, and is positive when $X_{t}$ is smaller than zero[11].\\
Stochastic modelling has an important role in financial economics. For example, the Black-Scholes model [5] used abstract notations such as the It$\hat{o}$ calculus. The fractional Black-scholes market consist of a bank account or a bond and a stock also, by a fractional Volterra equations of the following form, we are able to govern the price $X_{t}$ of the stock 
\begin{equation*}
X_{t}=X_{0}+ \frac{1}{\Gamma(\beta)} \int_{0}^{t} \frac{\mu(s)}{(t-s)^{1-\beta}} ds+ \frac{1}{\Gamma(\frac{(\beta+1)}{2})} \int_{0}^{t} \frac{\chi(s)X_{s}}{(t-s)^{\frac{(1-\beta)}{2}} dW_{s}}
\end{equation*}
where ${W_{t}(\omega)=w(t), t>=0}$ is a Wiener process, $t\in[0,T]$, $0<\beta<1$ and the drift $\mu>=0$ and volatility $\chi>0$ are continuous functions on $[0,T]$.\\

\begin{example} 
Consider the following fractional stochastic integro-differential equation [38]
\begin{equation}
D^\alpha f(t)=-\frac{t^5 e^t}{5}+\frac{6t^{2.25}}{\Gamma(3.25)}+\int_{0}^{t} e^t s f(s) ds+ \sigma \int_{0}^{t} e^t s f(s) dB(s), t \in [0,1],
\end{equation}
where the exact solution with $\theta=0.75$, $\sigma=0$ is $f(t)=t^3$.\\
