\section{Proof of Theorem \ref{thm:optimal policy for fixed prior}}
Define the value function associated with Problem \ref{prob:MIOCP without terminal constraint} with $\rho$ fixed as
\begin{align*}
    &V(k,x) := \min_{\pi_{k}}\mathbb{E}\left[ \frac{1}{2}\|u_{k}\|_{R_{k}}^{2} + \varepsilon \mathcal{D}_{\text{KL}}\left[\pi_{k}(\cdot|x)\| \rho_{k}(\cdot)\right] \right. \\
    & \hspace{45pt}\left.+ \mathbb{E}[V(k+1, A_{k}x + B_{k}u_{k}  +w_{k}) ] \mid x_{k} = x\right],\\
    &x \in \mathbb{R}^{n}, k \in \llbracket 0, T-1 \rrbracket,\\
    &V(T,x) := \|x-r_{T}\|_{\Pi_{T}}^{2}, x\in \mathbb{R}^{n}.
\end{align*}
In addition, define the corresponding Q-function as
\begin{align*}
    &Q_{k}(x,u) := \frac{1}{2}\|u\|_{R_{k}}^{2} + \mathbb{E}[ V(k+1, A_{k}x + B_{k}u +w_{k})],\\
    &x\in \mathbb{R}^{n}, u \in \mathbb{R}^{m}, k \in \llbracket 0, T-1 \rrbracket.
\end{align*}
Then, we have
\begin{align*}
    &\mathbb{E}\left[ \frac{1}{2}\|u_{k}\|_{R_{k}}^{2} + \varepsilon \mathcal{D}_{\text{KL}}\left[\pi_{k}(\cdot | x)\| \rho_{k}(\cdot)\right]\right.\\
    &\hspace{10pt}\left.+ \mathbb{E}[V(k+1, A_{k}x + B_{k}u_{k}  +w_{k}) ] \mid x_{k} = x\right]\\
    =&\varepsilon \left\{\mathcal{D}_{\text{KL}}\left[\pi_{k}(\cdot | x) \middle\| \rho_{k}(\cdot)\exp\left(-\frac{1}{\varepsilon }Q_{k}(x, \cdot)\right)/z_{k}\right]\right.\\
    &\hspace{17pt}\left. -\log{z_{k}}\right\},
\end{align*}
where $z_{k}:= \int_{\mathbb{R}^{m}} \rho_{k}(u)\exp\left(-\frac{1}{\varepsilon}Q_{k}(x,u)\right)du$.
Therefore, it follows that
\begin{align}
    \pi_{k}^{\rho}(u|x) \propto \rho_{k}(u)\exp\left(-\frac{1}{\varepsilon}Q_{k}(x, u)\right). \label{eq:optimal policy for fixed prior using Q-function}
\end{align}
Now, let us calculate $Q_{T-1}(x,u)$.
Considering that $\Sigma_{Q_{T-1}}$ is positive definite and $A_{T-1}$ is invertible thanks to Lemma \ref{lem:positive semidefiniteness of Pi} and the assumption of Theorem \ref{thm:optimal policy for fixed prior}, respectively, it follows that
\begin{align*}
    &Q_{T-1}(x,u)\\
    =& \frac{1}{2}\|u\|_{R_{T-1}}^{2} + \frac{1}{2} \mathbb{E}[\|A_{T-1}x + B_{T-1}u-r_{T} +w_{k}\|_{\Pi_{T}}^{2} ]\\
    =& \frac{1}{2}\|u - \mu_{Q_{T-1}}\|_{\varepsilon \Sigma_{Q_{T-1}}^{-1}}^{2} + \frac{1}{2}\|x-A_{T-1}^{-1}r_{T}\|_{\Gamma_{T-1}}^{2} \\
    &+\frac{1}{2}\mathrm{Tr}[\Pi_{T}\Sigma_{w_{T-1}}],
\end{align*}
where $\Gamma_{k} := A_{k}^{\top}\Pi_{k+1}A_{k} - A_{k}^{\top}\Pi_{k+1} B_{k}(R_{k} + B_{k}^{\top}\Pi_{k+1}B_{k})^{-1}B_{k}^{\top}\Pi_{k+1}A_{k}, k\in \llbracket0,T-1 \rrbracket$.
By substituting this into \eqref{eq:optimal policy for fixed prior using Q-function}, we have the policy \eqref{eq:optimal policy for fixed prior} for $k = T-1$.

The value function for $k = T-1$ can be calculated as
\begin{align}
    &V(T-1, x) = -\varepsilon \log{z_{T-1}} \nonumber\\
    = &\frac{1}{2}\|x-A_{T-1}^{-1}r_{T}\|_{\Gamma_{T-1}}^{2}-\frac{\varepsilon}{2}\log\{(2\pi)^{m}|\Sigma_{Q_{T-1}}|\} \nonumber \\
    &+\frac{1}{2}\mathrm{Tr}[\Pi_{T}\Sigma_{w_{T-1}}]\nonumber\\
    & - \varepsilon \log \left\{ \int_{\mathbb{R}^{m}} \mathcal{N}(\mu_{Q_{T-1}},\Sigma_{Q_{T-1}})\rho_{T-1}(u)du\right\}. \label{eq:value function for k = T-1}
\end{align}
The argument of the logarithm of the last term can be calculated as

\begin{align*}
    &\int_{\mathbb{R}^{m}} \mathcal{N}(\mu_{Q_{T-1}},\Sigma_{Q_{T-1}})\rho_{T-1}(u)du\\
    =&\frac{1}{\sqrt{(2\pi)^{m}|\Sigma_{\rho_{T-1}}+\Sigma_{Q_{T-1}}|}}\\
    &\times\exp\left(-\frac{1}{2}\|\mu_{\rho_{T-1}}-\mu_{Q_{T-1}}\|_{(\Sigma_{\rho_{T-1}}+\Sigma_{Q_{T-1}})^{-1}}^{2}\right).
\end{align*}
Therefore, \eqref{eq:value function for k = T-1} can be rewritten as
\begin{align*}
    &V(T-1, x)\\
    = &\frac{1}{2}\|x-A_{T-1}^{-1}r_{T}\|_{\Gamma_{T-1}}^{2}+\frac{\varepsilon}{2}\log\frac{|\Sigma_{\rho_{T-1}}+\Sigma_{Q_{T-1}}|}{|\Sigma_{Q_{T-1}}|}\\
    &+\frac{\varepsilon}{2}\|\mu_{\rho_{T-1}}-\mu_{Q_{T-1}}\|_{(\Sigma_{\rho_{T-1}}+\Sigma_{Q_{T-1}})^{-1}}^{2} +\frac{1}{2}\mathrm{Tr}[\Pi_{T}\Sigma_{w_{T-1}}].
\end{align*}
By substituting \eqref{eq:mean of Q} into $V(T-1,x)$, we have % and arranging $V(T-1,x)$ with respect to $x$
\begin{align}
    &V(T-1, x) \nonumber\\
    = &\frac{1}{2}\|x-r_{T-1}\|_{\Pi_{T-1}}^{2} +(\text{Terms independent of }x).\label{eq:arranged value function for k = T-1}
\end{align}
Since the first term of the right-hand side of \eqref{eq:arranged value function for k = T-1} takes the same form as $V(T, x)$, we can derive the policy \eqref{eq:optimal policy for fixed prior} for $k = T-2, T-3, \ldots, 0,$ recursively by following the same procedure as for $k = T-1$, which completes the proof.







