\section{Corresponding mesoscopic and macroscopic models}\label{sec:macro}
In this section, we formally derive first the mesoscopic counterpart of the microscopic model presented in the previous section and then the corresponding macroscopic model.

\subsection{Preliminaries and notation} We let 
\begin{equation}
\label{def:celprobdens}
(\X_t,V_t,\hbV_t, Y_t) \sim f(t,\x,v,\hv,y) \, ,
\end{equation}
where the distribution function $f : \mathbb{R}^+_0 \times \mathbb{R}^d \times [0,V_{\rm max}] \times \mathbb{S}^{d-1} \times [0,1] \to \mathbb{R}^+_0$, which represents the cell distribution in each of phase and phenotype space, is a probability density function and is thus such that
\begin{equation}
\label{ass:intf1}
\int_{\mathbb{R}^d} \int_{0}^{V_{\rm max}} \int_{\mathbb{S}^{d-1}} \int_{0}^1 f(t,\x,v,\hv,y) \, {\rm d}y \, {\rm d}\hv \, {\rm d}v \, {\rm d}\x = 1 \, .
\end{equation}
In the remainder of the article, we will use the more compact notation
$$
f(t,\x,v,\hv,y) \equiv f(t,\x,\bnu,y), \quad \bnu \equiv (v,\hv) \in \mathcal{V}.
$$
{The macroscopic quantities are defined as the statistical moments of $f$ at $(t,\x)$ fixed:}
\begin{itemize}
\item the number density (per unit volume) of the cell population (i.e. the cell density)
\begin{equation}\label{def:m}
\rho(t,\x) := \int_{\mathcal{V}} \int_0^1 f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu\,;
\end{equation}
\item the normalised distribution of the cell population in the phase space 
\begin{equation}\label{def:p}
p(t,\x,\bnu) := \dfrac{1}{\rho(t,\x)}\int_{0}^1 f(t,\x,\bnu,y)\, {\rm d}y \,;
\end{equation}
\item the mean velocity of the cell population (i.e. the ensemble average velocity)
\begin{equation}\label{def:U}
{\bf U}(t,\x) :=  \int_{\mathcal{V}} \vb \, p(t,\x,\bnu) \,  {\rm d}\bnu
\end{equation}
and the corresponding momentum
\begin{equation}\label{def:rhoU}
\rho(t,\x) \, {\bf U}(t,\x) = \rho(t,\x) \int_{\mathcal{V}} \vb\, p(t,\x,\bnu) \,  {\rm d}\bnu \,;
\end{equation}
\item {the second order tensor of the cell population 
\begin{equation}\label{def:rhoD}
\rho(t,\x)\, \mathbb{D}(t,\x) =  \rho(t,\x)\int_{\mathcal{V}} (\vb-{\bf U})\otimes (\vb-{\bf U})  \,p(t,\x,\bnu) \,  {\rm d}\bnu\,,
\end{equation}
being $\mathbb{D}(t,\x)$ the variance-covariance matrix of $p$ for each $(t,\x)$ fixed.}
\end{itemize}
Moreover, we will use the following definitions of the counterparts of the above quantities for cells in a given phenotypic state $y$:
\begin{itemize}
\item the normalised distribution of the cell population in the phenotype space
\begin{equation}\label{def:n}
n(t,\x,y) := \dfrac{1}{\rho(t,\x)}\int_{\mathcal{V}} f(t,\x,\bnu,y) \, {\rm d}\bnu \,,
\end{equation}
whereby $\rho(t,\x) n(t,\x,y)$ is the number density of cells in the phenotypic state $y$; 
\item the mean velocity of cells in the phenotypic state $y$ 
\begin{equation}\label{def:Uy}
{\bf u}(t,\x,y) := \frac{1}{\rho(t,\x)n(t,\x,y)} \int_{\mathcal{V}} \vb  \, f(t,\x,\bnu,y) \,  {\rm d}\bnu
\end{equation}
and the corresponding momentum
\begin{equation}\label{def:nUy}
\rho(t,\x) n(t,\x,y) \, {\bf u}(t,\x,y) = \int_{\mathcal{V}} \vb \, f(t,\x,\bnu,y) \,  {\rm d}\bnu \,;
\end{equation}
\item {the second order tensor of cells in the phenotypic state $y$}
\begin{equation}\label{def:nD}
\rho(t,\x)n(t,\x,y)\, \mathbb{d}(t,\x,y) =  \int_{\mathcal{V}} (\vb-{\bf u})\otimes (\vb-{\bf u})  \,f(t,\x,\bnu,y)\,  {\rm d}\bnu\, ,
\end{equation}
{where $n(t,\x,y)\mathbb{d}(t,\x,y)$ is the variance-covariance matrix of $f$ with respect to $\bnu$ for each $(t,\x,y)$ fixed.} 
\end{itemize} 
Finally, we will use the following definition of the mean phenotypic state of the cell population
\begin{equation}\label{eq:ave_phen}
\bar{y}(t,\x) := \int_{0}^1  y \, n(t,\x,y) \, {\rm d}y \, ,
\end{equation}
which corresponds to the average phenotype of the normalised distribution $n$.

\subsection{The corresponding mesoscopic and macroscopic models}\label{mesomacromodels}



{The mesoscopic model corresponding to the microscopic model presented in section~\ref{sec:micro}} consists of a phenotype-structured kinetic equation for the {distribution function} $f(t,\x,\bnu,y)$ given in~\eqref{def:celprobdens}, 
the strong form of which reads as
\begin{equation}\label{eq:Boltz_coll_2:strong}
\begin{cases}
&\displaystyle{\partial_t f + \vb \cdot \nabla_\x f = \mu  \left(\rho \, T[\mathcal{S},\mathcal{S}^\dagger] \, n - f \right)} \\
&\displaystyle{\phantom{\partial_t f + \vb \cdot \nabla_\x f =} + \lambda \left(\int_{0}^1 K[\mathcal{S}^\ddagger]({y}|y')  \, f(t,\x,\bnu,y') \,  {\rm d}y' \, - f \right)} \, ,
\\\\
& \displaystyle{n(t,\x,y) := \dfrac{1}{\rho(t,\x)}\int_{\mathcal{V}} f(t,\x,\bnu,y) \, {\rm d}\bnu} \,.
\end{cases}
\end{equation}
{This kinetic model is formally derived in~Section~\ref{appendix} in the supplementary material, starting from system~\eqref{eq:micro_stoch} complemented with relations~\eqref{eq:micro_vel}, using a limiting procedure which generalises the one employed, for instance, in~\citep{conte2023non} to the case of phenotypically heterogeneous cell populations.} 
\begin{remark}
In~\eqref{eq:Boltz_coll_2:strong}, the term 
$$
\int_{0}^1 K[\mathcal{S}^\ddagger]({y}|y') \, f(t,\x,\bnu,y') {\rm d}y' \, - f
$$
could also be rewritten as a differential term by using the quasi-invariant limit approach for transition probabilities, as similarly done in~\citep{loy2020markov}. 
\end{remark}


{Our aim is now to derive a macroscopic model, that is, a set of PDEs describing the evolution of macroscopic quantities which are conserved by the cellular processes (i.e. reorientations and phenotypic changes) incorporated into the mesoscopic model.} In order to obtain a closed macroscopic model, different approaches could be adopted {in different regimes} (see~Section~\ref{sec:macroclosure} in the supplementary material). Amongst these, in the light of the experimental results presented in~\citep{goodman1989e8} and the considerations made in Section~\ref{sec:justscal} in the supplementary material, introducing a small parameter $\varepsilon \in \mathbb{R}^+$, one can consider the following {scaling} 
\begin{equation}\label{ass:epsscal3}
\lambda = \dfrac{1}{\varepsilon} \, , \quad \mu = \dfrac{1}{\varepsilon} \, ,
\end{equation}
which corresponds to scenarios where phenotypic changes and cell reorientation occur on similar time scales, which are faster than the time scale of spatial dynamics of the cells. {The non-dimentionalisation leading to~\eqref{ass:epsscal3} is provided in~Section~\ref{sec:justscal} in the supplementary material}.

 To this end, denoting the solution to the phenotype-structured kinetic equation~\eqref{eq:Boltz_coll_2:strong} under the parameter scaling~\eqref{ass:epsscal3} by $f_{\varepsilon}$, we make the following expansion ansatz (i.e. the Chapman-Enskog expansion)
\begin{equation}\label{ass.CE}
f_{\varepsilon}=f_0+\varepsilon f^{\bot}, \qquad \rho_0:=\int_{\mathcal{V}} \int_0^1 f_0 \, {\rm d}y \,  {\rm d}\bnu= \rho,  \quad \rho^{\bot}:=\int_{\mathcal{V}} \int_0^1 f^{\bot} \, {\rm d}y \, {\rm d}\bnu=0.
\end{equation}
The ansatz~\eqref{ass.CE} implies that the mass is concentrated in the leading order term, $f_0$, while the correction, $f^{\bot}$, carries no mass, and thus
\begin{equation}\label{cond:rho_0}
\rho_\varepsilon=\rho_0 =\rho.
\end{equation}
From~\eqref{ass.CE}, one obtains analogous expansions for the marginals. In fact, integrating $f_\varepsilon/\rho$ over $[0,1]$ and using~\eqref{ass.CE} gives the expansion for the marginal $p_{\varepsilon}$ along with the mass of the corresponding leading order term and of the correction, i.e.
{\small
\begin{equation}\label{def:p_eps}
p_\varepsilon = p_0+\varepsilon p^{\bot}, \quad p_0=\dfrac{1}{\rho}\int_0^1 f_0 \, {\rm d}y, \quad p^{\bot}=\dfrac{1}{\rho}\int_0^1 f^{\bot} \, {\rm d}y, \quad \int_{\mathcal{V}} p_0 \, {\rm d}\bnu =1, \quad \int_{\mathcal{V}}p^{\bot} \, {\rm d}\bnu =0.
\end{equation}
}
Similarly, integrating $f_\varepsilon/\rho$ over $\mathcal{V}$ and using~\eqref{ass.CE} gives the expansion for the marginal $n_{\varepsilon}$ along with the mass of the corresponding leading order term and of the correction, i.e.
{\small
\begin{equation}\label{def:n_eps}
n_\varepsilon =n_0 +\varepsilon n^{\bot}, \quad n_0=\dfrac{1}{\rho}\int_{\mathcal{V}} f \, {\rm d}\bnu, \quad n^{\bot}=\dfrac{1}{\rho}\int_{\mathcal{V}} n^{\bot} \, {\rm d}{\bnu}, \quad \int_0^1 n_0 \, {\rm d}y=1, \quad \int_0^1 n^{\bot} \, {\rm d}y =0.
\end{equation}
}

\begin{remark}\label{rem:g1}
{We now introduce the following integral operator defined on the Banach space $L^1([0,1])$ into itself 
%$K[\mathcal{S}^\ddagger]$ 
\begin{align*}
%\longmapsto
&\mathcal{K}: L^1([0,1]) \longrightarrow L^1([0,1])\\
&\mathcal{K}[g] = \int_{0}^1 K[\mathcal{S}^\ddagger]({y}|y') \, g(t,\x,y') \, {\rm d}y',
\end{align*}
which is linear, bounded (cf. assumption~\eqref{hp:K.Linf}), and compact. Because of the positivity assumption in~\eqref{ass:K0}, this operator is strictly positive on the cone of positive functions of $L^1([0,1])$, which is reproducing and also total. Therefore, the Krein-Rutman theorem (see e.g. \citep[Theorem 19.2]{deimling}) allows one to conclude that this integral operator  admits a spectral radius associated with a positive eigenfunction, $g_1(t,\x,y)$, which depends on $(t,\x)$ through $\mathcal{S}^\ddagger(t,\x)$ (i.e. $g_1(t,\x,y) \equiv g_1[\mathcal{S}^\ddagger](y)$) and it is unique up to normalisation, i.e. 
$$
 \int_{0}^1 g_1[\mathcal{S}^\ddagger](y) \, {\rm d}y = 1 \, .
$$ 
In particular, note that, due to the normalisation assumption in~\eqref{ass:K0}, the eigenfunction $g_1(t,\x,y)$ is associated with the eigenvalue $1$.}
Moreover, if the phenotypic transition kernel $K[\mathcal{S}^\ddagger]$ also satisfies the following assumption
\begin{equation}\label{ass:Kclosure}
K[\mathcal{S}^\ddagger]({y}|y') \equiv K[\mathcal{S}^\ddagger](y),
\end{equation}
that is, if the new phenotypic states acquired by the cells upon phenotypic changes are independent of the original ones,
then
{
\[
\mathcal{K}[g] = \int_{0}^1 K[\mathcal{S}^\ddagger]({y}) \, g(t,\x,y') \, {\rm d}y'= K[\mathcal{S}^\ddagger]({y}) \int_{0}^1 g(t,\x,y') \, {\rm d}y'.
\]
In this case, since $g_1$ is the eigenfunction of $\mathcal{K}[g]$ associated with the eigenvalue 1 and it is normalised, then}
\begin{equation}\label{eq:g1explicit}
{g_1[\mathcal{S}^\ddagger](y)} = K[\mathcal{S}^\ddagger](y) \, .
\end{equation}
\end{remark}

{In the remainder of this section, we will be letting assumption~\eqref{ass:Kclosure} hold, so that the result~\eqref{eq:g1explicit} holds as well. Moreover, we will be assuming the distributions of environmental factors $\mathcal{S}$, $\mathcal{S}^\dagger$, and $\mathcal{S}^\ddagger$ to be constant in time, i.e. 
\begin{equation}\label{ass:constenvfact}
\mathcal{S}\equiv \mathcal{S}(\x) \, , \quad \mathcal{S}^\dagger\equiv\mathcal{S}^\dagger(\x) \, , \quad  \mathcal{S}^\ddagger \equiv \mathcal{S}^\ddagger(\x),
\end{equation}
in order to consider the scenario where the extracellular environment is stationary. Note that, in this scenario, the result~\eqref{eq:g1explicit} implies that $g_1[\mathcal{S}^\ddagger](y)$ is constant in time.}

In the framework of assumptions~\eqref{ass:Kclosure} and~\eqref{ass:constenvfact}, exploiting the result~\eqref{eq:g1explicit}, we now employ a limiting procedure that generalises the one used, for instance, in~\citep{hillen2006m}, to the case where a continuous phenotype structure and phenotypic changes are incorporated into the kinetic equation. As similarly done in~\citep{hillen2006m}, we define the operator 
\begin{equation*}
\begin{aligned}[b]
\mathcal{L}^{\bnu}: L^2(\mathcal{V}\times [0,1]) &\longrightarrow L^2(\mathcal{V}\times [0,1])\\[0.1cm]
\varphi & \longmapsto T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y)\int_{\mathcal{V}} \varphi(\bnu,y) \, {\rm d}\bnu - \varphi,
\end{aligned}
\end{equation*}
so that $\mathcal{L}^{\bnu}(f) = \rho T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y) n \, - f$. Moreover, since, compared to~\citep{hillen2006m}, in our model the microscopic state of the cells  comprises both a velocity component and a phenotype component, the dynamics of which are governed by two independent processes, we introduce the additional operator
\begin{equation*}
\begin{aligned}[b]
\mathcal{L}^y: L^2(\mathcal{V}\times [0,1]) &\longrightarrow L^2(\mathcal{V}\times [0,1])\\
\varphi &\longmapsto K[\mathcal{S}^\ddagger](y)\int_{0}^1 \varphi(\bnu,y) \, {\rm d}y  - \varphi,
\end{aligned}
\end{equation*}
so that $\mathcal{L}^y(f)=\rho \,K[\mathcal{S}^\ddagger](y) \, p \, - f$. Note that, on the same function space $L^2(\mathcal{V}\times [0,1])$, we can also define the sum of the two operators $\mathcal{L} := \mathcal{L}^{\bnu}+\mathcal{L}^y$, with 
\begin{equation}\label{def:L}
\begin{aligned}[b]
\mathcal{L}: L^2(\mathcal{V}\times [0,1]) &\longrightarrow L^2(\mathcal{V}\times [0,1])\\
\varphi &\longmapsto T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y)\int_{\mathcal{V}} \varphi(\bnu',y) \, {\rm d}\bnu'+K[\mathcal{S}^\ddagger](y)\int_{0}^1 \varphi(\bnu,y) \, {\rm d}y  - 2\varphi,
\end{aligned}
\end{equation}
which allows us to rewrite the phenotype-structured kinetic equation~\eqref{eq:Boltz_coll_2:strong} under the parameter scaling~\eqref{ass:epsscal3} as 
\begin{equation}\label{eq:kin_strong_op}
\partial_t f_\varepsilon +\vb\cdot \nabla_\x f_\varepsilon = \dfrac{1}{\varepsilon}\mathcal{L}(f_\varepsilon).
\end{equation}
Substituting~\eqref{ass.CE} into~\eqref{eq:kin_strong_op}, one finds a hierarchy of equations in $\varepsilon$. Specifically, in $\varepsilon^0$ 
\begin{equation}\label{eq:eps0}
\mathcal{L}(f_0)=0,
\end{equation}
while in $\varepsilon^1$ 
\begin{equation}\label{eq:eps1}
\partial_t f_0 +\vb \cdot \nabla_\x f_0=\mathcal{L}(f^{\bot}).
\end{equation}

{The only conserved quantity is the mass (i.e. the number density at $(t,\x)$ fixed), as \\ $\displaystyle{\int_{\mathcal{V}}\int_0^1 \mathcal{L}(f) \, {\rm d} y \, {\rm d} \bnu=0}$, while no higher-order moments of $f$ are conserved. As a consequence, in the regime~\eqref{ass:epsscal3}, wherein the operators $\mathcal{L}^{\bnu}$ and $\mathcal{L}^y$ defining the operator $\mathcal{L}$ are of the same order, the macroscopic model will be a closed PDE for the cell density, that is, the number density of the distribution $f_0$ which makes the operator $\mathcal{L}$ vanish.}

From~\eqref{eq:eps0} one obtains
\[
f_0(t,\x,\bnu,y)=\dfrac{\rho(t,\x)}{2}\left(T[\cS,\cS^\dagger](\bnu;y) \, n^0(\x,y)+K[\mathcal{S}^\ddagger](y) \, p^0(\x,\bnu)\right),
\]
which requires the marginal stationary equilibria $n^0(\x,y)$ and $p^0(\x,\bnu)$ that nullify, respectively, the operator corresponding to phenotypic changes and the operator corresponding to cell reorientation. 

Integrating~\eqref{eq:kin_strong_op} with respect to $y$ one recovers the evolution equation for the marginal $p_\varepsilon$, that is,
\begin{equation}\label{eq:p_eps}
\partial_t  \left(\rho p_\varepsilon\right) +\vb \cdot \nabla_\x \left(\rho p_\varepsilon \right) = \dfrac{1}{\varepsilon} \bar{\mathcal{L}}^{\bnu} ({f_\varepsilon}),
\end{equation}
where 
\begin{equation}\label{def:bLnu}
\begin{aligned}[b]
\bar{\mathcal{L}}^{\bnu}: L^2(\mathcal{V}\times [0,1]) &\longrightarrow L^2({\mathcal{V}})\\
\varphi &\longmapsto \int_0^1 T[\cS,\cS^\dagger](\bnu;y)\int_{\mathcal{V}} {\varphi}({\bnu'},y) \, {\rm d}{\bnu'} \, {\rm d}y - \int_0^1 {\varphi} (\bnu,y) \, {\rm d}y,
\end{aligned}
\end{equation}
while the evolution equation for $n_\varepsilon$ is
\begin{equation}\label{eq:n_eps}
\partial_t (\rho n_\varepsilon) + \nabla_\x \cdot \left(\rho n_\varepsilon \, {\bf u}\right) = \dfrac{1}{\varepsilon} \bar{\mathcal{L}^y}({f_\varepsilon}) \, ,
\end{equation}
where
\begin{equation}\label{def:bLy}
\begin{aligned}[b]
\bar{\mathcal{L}^y} : L^2(\mathcal{V}\times[0,1]) &\longrightarrow L^2({[0,1]})\\
\varphi &\longmapsto K[\mathcal{S}^\ddagger](y)\int_{\mathcal{V}}\int_0^1 \varphi(\bnu,y) \, {\rm d}y \, {\rm d}\bnu - \int_{\mathcal{V}} \varphi(\bnu,y) \, {\rm d}\bnu.
\end{aligned}
\end{equation}

At leading order in $\varepsilon$, from the equations for the marginals~\eqref{eq:p_eps} and \eqref{eq:n_eps} complemented with~\eqref{def:p_eps} and \eqref{def:n_eps}, one finds
\begin{equation}\label{eq:p0.n0}
p_0(\x,\bnu)=  \int_0^1 T[\cS,\cS^\dagger](\bnu;y)n_0(\x,y) \, {\rm d}y, \qquad n_0(\x,y)= K[\mathcal{S}^\ddagger](y),
\end{equation}
i.e.
{\small
\begin{equation}\label{eq:p0}
p_0(\x,\bnu)=T_K[\cS,\cS^\dagger,\mathcal{S}^\ddagger](\bnu), \quad T_K[\cS,\cS^\dagger,\mathcal{S}^\ddagger](\bnu):=\int_0^1 T[\cS,\cS^\dagger](\bnu;y) K[\mathcal{S}^\ddagger](y) \, {\rm d}y.
\end{equation}}
Therefore, the distribution $f_0$, i.e. the solution of~\eqref{eq:eps0}, is
{\begin{equation}\label{def:eq_0}
f_0(t,\x,\bnu,y)=\rho(t,\x) \, \mathcal{T}[\cS,\cS^\dagger,\mathcal{S}^\ddagger](\bnu,y),
\end{equation}
where
\begin{equation}\label{def:eq_0.T}
\mathcal{T}[\cS,\cS^\dagger,\mathcal{S}^\ddagger](\bnu,y):= \dfrac{K[\mathcal{S}^\ddagger](y)}{2}\left[T_K[\cS,\cS^\dagger,\mathcal{S}^\ddagger](\bnu)+T[\cS,\cS^\dagger](\bnu;y) \, \right].
\end{equation}}
{Note that from~\eqref{def:eq_0.T} one sees that the stationarity assumptions~\eqref{ass:constenvfact} are needed so as to ensure that $\mathcal{T}[\cS,\cS^\dagger,\mathcal{S}^\ddagger]$ does not depend on the time variable.} Note also that $\mathcal{T}$ is a probability distribution on $\mathcal{V}\times [0,1]$, since
\[
\int_{\mathcal{V}}\int_0^1 \mathcal{T}[\cS,\cS^\dagger,\mathcal{S}^\ddagger](\bnu,y) \, {\rm d}y \, {\rm d} \bnu =1, \qquad \forall \x \in \mathbb{R}^d,
\]
due to{~\eqref{ass:K0}, \eqref{ass:T0}, and to the measurability of $\mathcal{T}$ as a function of $y$, which provides the regularity needed to apply the Fubini-Tonelli theorem and, in so doing, obtain the above normalisation condition.} In~\eqref{def:eq_0} we have used~\eqref{cond:rho_0}. We also stress the fact that the time dependence of the distribution $f_0$ given by~\eqref{def:eq_0} is due exclusively to the time dependence of the number density $\rho$, while $p_0$ and $n_0$, which nullify, respectively, the operator $\bar{\mathcal{L}^{\bnu}}$ and the operator $\bar{\mathcal{L}^y}$, do not depend on the time variable, as a result of the stationarity assumptions~\eqref{ass:constenvfact}. Substituting~\eqref{def:eq_0} and \eqref{def:eq_0.T} into~\eqref{eq:eps1} and integrating over $\mathcal{V}\times [0,1]$ gives, at leading order in $\varepsilon$, the PDE
\begin{equation}\label{eq:govern3}
\partial_t \rho + \nabla_\x \cdot \left(\rho \, \Ub_{\mathcal{T}}\right) = 0 \, ,
