\section{Formal derivation of the mesoscopic model}\label{appendix}
Starting from system~\eqref{eq:micro_stoch} complemented with relations~\eqref{eq:micro_vel}, we formally derive the mesoscopic counterpart of the microscopic model presented in~\eqref{sec:micro}. The derivation method relies on classical limiting procedures of kinetic theory for multi-agent systems, as detailed, in the context of velocity-jump processes for cell migration, in~\cite{conte2023non}.

Since the components of the quadruple $(\X_{t+\Delta t},V_{t+\Delta t},\hbV_{t+\Delta t}, Y_{t+\Delta t})$ are given by the system~\eqref{eq:micro_stoch}, for any observable $\phi: \mathbb{R}^d \times \mathcal{V} \times [0,1] \to \mathbb{R}$, in the asymptotic regime $\Delta t \to 0^+$, the expectation
\begin{equation}\label{def:expext1}
\ave{\phi\left(\X_{t},V_{t},\hbV_{t}, Y_{t}\right)} = \int_{\mathbb{R}^d} \int_{\mathcal{V}} \int_{0}^1 \phi(\x,\bnu,y) \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu \, {\rm d}\x
\end{equation}
formally satisfies, see for example~\cite{pareschi2013interacting}, the following differential equation
{\small
\begin{equation}\label{eq:ave_2} 
\begin{aligned}[b]
& \dfrac{{\rm d}}{{\rm d} t}\ave{\phi\left(\X_t,V_t,\hbV_t,Y_t\right)}+\nabla_\x \cdot \ave{V_t\hbV_t \, \phi(\X_t,V_t,\hbV_t,Y_t)}= \\
& \phantom{ \dfrac{{\rm d}}{{\rm d} t}\ave{\phi\left(\X_t,V_t,\hbV_t,Y_t\right)}+} \mu\ave{\phi\left(\X_t,V_t',\hbV_t',Y_t\right)-\phi\left(\X_t,V_t,\hbV_t,Y_t\right)}  \\
& \phantom{ \dfrac{{\rm d}}{{\rm d} t}\ave{\phi\left(\X_t,V_t,\hbV_t,Y_t\right)}+} +\lambda\ave{\phi\left(\X_t,V_t,\hbV_t,Y'_t\right)-\phi\left(\X_t,V_t,\hbV_t,Y_t\right)}
\end{aligned}
\end{equation}
}
with
{\footnotesize
\begin{eqnarray}\label{def:expext2}
\ave{\phi\left(\X_t,V_t',\hbV_t',Y_t\right)}&=&\int_{\mathbb{R}^d}\int_{\mathcal{V}}\int_0^1\int_{\mathcal{V}} \Psi[\cS^\dagger]({v'};\hv',y) \, \mathcal{B}[\cS](\hv';y) \, \phi(\x,\bnu',y) \, {\rm d}\bnu' \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu \, {\rm d}\x \nonumber \\
&=& \int_{\mathbb{R}^d}\int_{\mathcal{V}}\int_0^1\int_{\mathcal{V}} T[\mathcal{S},\mathcal{S}^\dagger](\bnu';y) \, \phi(\x,\bnu',y) \, {\rm d}\bnu' \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu \, {\rm d}\x \, ,
\end{eqnarray}
}
where the kernel $T$ is defined via~\eqref{def:T_fact}, and
{\small
\begin{equation}\label{def:expext3}
\ave{\phi\left(\X_t,V_t,\hbV_t,Y'_t\right)}=\int_{\mathbb{R}^d}\int_{\mathcal{V}}\int_0^1\int_{0}^1 K[\mathcal{S}^\ddagger](y'|y) \, \phi(\x,\bnu,y') \, {\rm d}y' \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu \, {\rm d}\x \, ,
\end{equation}
}
with the kernel $K$ satisfying assumptions~\eqref{ass:K1}. By using \eqref{def:expext1}, \eqref{def:expext2}, and \eqref{def:expext3}, we rewrite \eqref{eq:ave_2} as
{\footnotesize
$$
\begin{aligned}[b]
&\dfrac{{\rm d}}{{\rm d}t}\int_{\mathbb{R}^d} \int_{\mathcal{V}}\int_0^1\phi(\x,\bnu,y) \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu \, {\rm d}\x +\int_{\mathbb{R}^d} \nabla_\x \cdot \int_{\mathcal{V}}\int_0^1 \phi(\x,\bnu,y) \, v \hv \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu \,  {\rm d}\x =\\
&\qquad\quad \mu\int_{\mathbb{R}^d} \int_{\mathcal{V}}\int_0^1\left(\int_{\mathcal{V}}T[\mathcal{S},\mathcal{S}^\dagger](\bnu';y) \, \phi(\x,\bnu',y) \, {\rm d}\bnu' -\phi(\x,\bnu,y)\right) \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu \, {\rm d}\x \\
&\qquad\quad + \lambda\int_{\mathbb{R}^d} \int_{\mathcal{V}}\int_0^1\left(\int_{0}^1 K[\mathcal{S}^\ddagger](y'|y) \, \phi(\x,\bnu,y') \, {\rm d}y' -\phi(\x,\bnu,y)\right) \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu \, {\rm d}\x \, .
\end{aligned}
$$
}
Then, using the fact that
\begin{eqnarray*}
&& \int_{\mathcal{V}}\int_0^1 \int_{\mathcal{V}}T[\mathcal{S},\mathcal{S}^\dagger](\bnu';y) \, \phi(\x,\bnu',y) \, {\rm d}\bnu' \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu = \\
&& \qquad \qquad \int_{\mathcal{V}}\int_0^1 \int_{\mathcal{V}}T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y) \, \phi(\x,\bnu,y) \, {\rm d}\bnu \, f(t,\x,\bnu',y) \, {\rm d}y \, {\rm d}\bnu'
\end{eqnarray*}
and
\begin{eqnarray*}
&& \int_{\mathcal{V}}\int_0^1 \int_{0}^1 K[\mathcal{S}^\ddagger](y'|y) \, \phi(\x,\bnu,y') \, {\rm d}y' \, f(t,\x,\bnu,y) \, {\rm d}y \, {\rm d}\bnu = \\
&& \qquad \qquad \int_{\mathcal{V}}\int_0^1 \int_{0}^1 K[\mathcal{S}^\ddagger](y|y') \, \phi(\x,\bnu,y) \, {\rm d}y \, f(t,\x,\bnu,y') \, {\rm d}y' \, {\rm d}\bnu
\end{eqnarray*}
along with definition~\eqref{def:n} of the number density of cells in the phenotypic state $y$, $\rho(t,\x) n(t,\x,y)$, and the notation $\vb = v \hv$, choosing $\phi(\x,\bnu,y) := \xi(\x) \varphi(\bnu,y)$, where $\xi(\x)$ and 
$\varphi(\bnu,y)$ are test functions, we obtain a weak formulation (in the physical space) of the following weak form of the phenotype-structured kinetic equation~\eqref{eq:Boltz_coll_2:strong} for the distribution function $f(t,\x,\bnu,y)$
{\small
\begin{equation}\label{eq:Boltz_coll_2}
\begin{aligned}[b]
\begin{cases}
& \displaystyle{\int_{\mathcal{V}}\int_0^1\varphi(\bnu,y) \, \partial_t f \, {\rm d}y \, {\rm d}\bnu + \nabla_\x \cdot \int_{\mathcal{V}}\int_0^1 \varphi(\bnu,y) \, \vb \, f \, {\rm d}y \, {\rm d}\bnu =}\\
&\qquad\quad \displaystyle{\mu \int_{\mathcal{V}}\int_0^1\varphi(\bnu,y) \, \Big(\rho \, T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y) \, n - f \Big) \, {\rm d}y \, {\rm d}\bnu} \\
&\qquad\quad + \, \displaystyle{\lambda \int_{\mathcal{V}}\int_0^1 \varphi(\bnu,y) \, \left(\int_{0}^1 K[\mathcal{S}^\ddagger](y|y') \, f(t,\x,\bnu,y') {\rm d}y' \, - f\right) {\rm d}y \, {\rm d}\bnu} \, ,
\\\\
& \displaystyle{n(t,\x,y) :=\dfrac{1}{\rho(t,\x)} \int_{\mathcal{V}} f(t,\x,\bnu,y) \, {\rm d}\bnu} \,,
\end{cases}
\end{aligned}
\end{equation}
}
which in the strong form is~\eqref{eq:Boltz_coll_2:strong}.

\section{Additional considerations on macroscopic models}\label{sec:macroclosure}
From the weak form~\eqref{eq:Boltz_coll_2} of the phenotype-structured kinetic equation for $f$, under suitable choices of the test function $\varphi(\bnu,y)$, one can formally derive the governing equations for the moments of $f$, which provide a macroscopic counterpart of the underlying microscopic model. In summary:
\begin{itemize}
\item choosing $\varphi(\bnu,y) := {\bf 1}_{\mathcal{V}}(\bnu) \, \zeta(y)$, where ${\bf 1}_{(\cdot)}$ is the indicator function of the set $(\cdot)$ and $\zeta(y)$ is a test function, we obtain a weak formulation of the following governing equation for the number density of cells in the phenotypic state $y$, which is defined via~\eqref{def:n}, 
\begin{equation}\label{eq:goveqn}
\partial_t \left( \rho n\right) + \nabla_\x \cdot \left(\rho n \, {\bf u}\right) = \lambda \rho \left(\int_{0}^1 K[\mathcal{S}^\ddagger](y|y') \, n(t,\x,y') \, {\rm d}y' \, - n \right) \, ,
\end{equation}
where ${\bf u}$ is the mean velocity of cells in the phenotypic state $y$, which is defined via~\eqref{def:Uy};

\item choosing $\varphi(\bnu,y) :=  \vb \, \zeta(y)$, with $\vb = v \, \hv$, we obtain a weak formulation of the following governing equation for the momentum of cells in the phenotypic state $y$, which is defined via~\eqref{def:nUy}, 
\begin{eqnarray}\label{eq:goveqnUy} 
&&\partial_t \left(\rho n \, {\bf u} \right) + \nabla_\x \cdot \left(\rho n \, {\bf u} \otimes {\bf u} + \rho n \, \mathbb{d}\right) = \mu \rho \left(n \, \ub_T  \, - n \, \ub \right) \nonumber \\
&& \qquad \qquad \qquad + \lambda \rho \, \left(\int_{0}^1 K[\mathcal{S}^\ddagger](y|y') \, n(t,\x,y') \, \ub(t,\x,y') \, {\rm d}y' - n \, \ub\right) \, ,
\end{eqnarray}
where $\ub_T$ is defined via~\eqref{ass:T1} and $\rho n \, \mathbb{d}$ is the {second order} tensor of cells in the phenotypic state $y$, which is defined via~\eqref{def:nD};

\item choosing $\varphi(\bnu,y) := {\bf 1}_{\mathcal{V}}(\bnu) \, {\bf 1}_{[0,1]}(y)$, we obtain the following governing equation for the cell number density, which is defined via~\eqref{def:m},
\begin{equation}\label{eq:goveqrhoAPP}
\partial_t \rho + \nabla_\x \cdot \left(\rho \, {\bf U}\right) = 0 \, ,
\end{equation}
where ${\bf U}$ is the mean velocity of the cell population, which is defined via~\eqref{def:U};

\item choosing $\varphi(\bnu,y) := \vb \, {\bf 1}_{[0,1]}(y)$, we obtain the following governing equation for the momentum corresponding to the mean velocity of the cell population, which is defined via~\eqref{def:rhoU},
\begin{equation}\label{eq:goveqrhoU}
\partial_t \left(\rho \, {\bf U} \right) + \nabla_\x \cdot \left(\rho \, {\bf U} \otimes {\bf U} + \rho \, \mathbb{D}\right) = \mu \left(\rho \, \Ub_T - \rho \, \Ub\right) \, ,
\end{equation}
where
\begin{equation}\label{def:UTK}
\Ub_T \equiv \Ub_T(t,\x) := \int_{0}^1 \ub_T[\mathcal{S},\mathcal{S}^\dagger](y) \, n(t,\x,y) \, {\rm d}y \, ,
\end{equation}
with $\ub_T$ defined via~\eqref{ass:T1}, and $\rho \, \mathbb{D}$ is the {second order} tensor of the cell population, which is defined via~\eqref{def:rhoD}.
\end{itemize}

In order to obtain a closed macroscopic model, we can consider appropriately rescaled versions of the system~\eqref{eq:goveqn}-\eqref{eq:goveqrhoU} corresponding to different biological scenarios. We first focus on biological scenarios where phenotypic changes and cell reorientation occur on different time scales. Under these scenarios, introducing a small parameter $\varepsilon \in \mathbb{R}^+$, we consider the case where phenotypic changes occur more frequently than cell reorientation by assuming
\begin{equation}\label{ass:epsscal1}
\lambda = \dfrac{1}{\varepsilon} \, , \quad \mu = O(1) \;\; \text{for } \varepsilon \to 0^+ \, ,
\end{equation}
and the opposite case, i.e. we alternatively assume
\begin{equation}\label{ass:epsscal2}
\mu = \dfrac{1}{\varepsilon} \, , \quad \lambda = O(1) \;\; \text{for } \varepsilon \to 0^+ \, .
\end{equation}
Then we consider biological scenarios where phenotypic changes and cell reorientation occur on similar time scales, which are faster than the time scale of collective spatial dynamics of the cells, i.e. we assume 
\begin{equation}\label{ass:epsscal3APP}
\lambda = \dfrac{1}{\varepsilon} \, , \quad \mu = \dfrac{1}{\varepsilon} \, .
\end{equation}

Throughout this section, we denote by $f$ the limit of $f_{\varepsilon}$ (i.e. the solution to the phenotype-structured kinetic equation~\eqref{eq:Boltz_coll_2:strong} under one of the {scalings}~\eqref{ass:epsscal1}-\eqref{ass:epsscal3APP}) as $\varepsilon \to 0^+$, with the corresponding macroscopic quantities being defined via~\eqref{def:m}-\eqref{def:rhoD} and~\eqref{def:n}-\eqref{def:nD}. Moreover, we refer the reader to~\eqref{rem:g1} for the definition of $g_1[\mathcal{S}^\ddagger](y)$.

\paragraph{Closure of the macroscopic model under the {scaling}~\eqref{ass:epsscal1}} Under the {scaling}~\eqref{ass:epsscal1}, in the asymptotic regime $\varepsilon \to 0^+$:
\begin{itemize}
\item from~\eqref{eq:goveqn} one formally finds
\begin{equation}\label{def:neps0}
n(t,\x,y) = g_1[\mathcal{S}^\ddagger](y) \, ;
\end{equation}
\item from~\eqref{eq:goveqrhoAPP}-\eqref{def:UTK}, using the expression for $n$ given by~\eqref{def:neps0}, one formally obtains the following system
\begin{equation}\label{eq:govern}
\begin{cases}
\partial_t \rho + \nabla_\x \cdot \left(\rho \, {\bf U}\right) = 0 \, ,
\\\\
\partial_t \left(\rho \, {\bf U} \right) + \nabla_\x \cdot \left(\rho \, {\bf U} \otimes {\bf U} + \rho \, \mathbb{D}\right) = \mu \left(\rho \, \Ub_T - \rho \, \Ub\right) \, ,
\end{cases}
\end{equation}
where
\begin{equation}\label{def:UTKeps0}
\Ub_T \equiv \Ub_T[\mathcal{S},\mathcal{S}^\dagger,\mathcal{S}^\ddagger] := \int_{0}^1 \ub_T[\mathcal{S},\mathcal{S}^\dagger](y) \,  g_1[\mathcal{S}^\ddagger](y) \, {\rm d}y 
\end{equation}
with $\ub_T$ being defined via~\eqref{ass:T1}.
\end{itemize}
In order to close the system~\eqref{eq:govern}, we need to find a closed-form expression for $\mathbb{D}$. To this end, building on a moment closure method that is commonly used for transport models of cell migration -- see, for instance, the review~\cite{Hillen2013} -- we make the ansatz
\begin{equation}\label{eq:pclosure1}
p(t,\x,\bnu) = \int_0^1 T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y) \, g_1[\mathcal{S}^\ddagger](y) \, {\rm d}y \, ,
\end{equation}
which follows from assuming that the normalised distribution of the cell population in the phase space, $p$ is fully determined by the environmental conditions. Substituting this ansatz into~\eqref{def:rhoD} gives the following closed-form expression for the variance-covariance matrix
\begin{equation}\label{eq:DEepsscal1}
\mathbb{D} \equiv \mathbb{D}[\mathcal{S},\mathcal{S}^\dagger,\mathcal{S}^\ddagger] :=  \int_{\mathcal{V}} (\vb-{\bf U})\otimes (\vb-{\bf U})  \, \int_0^1 T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y) \, g_1[\mathcal{S}^\ddagger](y) \, {\rm d}y  \,  {\rm d}\bnu\,, 
\end{equation}
which makes it possible to close system~\eqref{eq:govern}.

\paragraph{Closure of the macroscopic model under the {scaling}~\eqref{ass:epsscal2}} Under the {scaling}~\eqref{ass:epsscal2}, in the asymptotic regime $\varepsilon \to 0^+$:
\begin{itemize}
\item from~\eqref{eq:goveqnUy} and~\eqref{eq:goveqrhoU} one formally finds, respectively, 
\begin{equation}\label{def:ueps0}
{\bf u}(t,\x,y) = {\bf u}_{T}[\mathcal{S},\mathcal{S}^\dagger](y)
\end{equation}
and
\begin{equation}\label{def:Ueps0}
\Ub(t,\x) = \Ub_T(t,\x) \, ,
\end{equation}
where $\ub_T$ and $\Ub_T$ are defined via~\eqref{ass:T1} and~\eqref{def:UTK};
\item from~\eqref{eq:goveqn} and~\eqref{eq:goveqrhoAPP}, using the expressions for ${\bf u}$ and $\Ub$ given by \eqref{def:ueps0} and \eqref{def:Ueps0}, one formally obtains the following closed system
{\small
\begin{equation}\label{eq:govern2}
\begin{cases}
\displaystyle{\partial_t \left( \rho n\right) + \nabla_\x \cdot \left(\rho n \, {\bf u}_T\right) = \lambda \rho \left(\int_{0}^1 K[\mathcal{S}^\ddagger](y|y') \, n(t,\x,y') \, {\rm d}y' \, - n \right) \, ,} 
\\\\
\partial_t \rho + \nabla_\x \cdot \left(\rho \, \Ub_T\right) = 0 \, .
\end{cases}
\end{equation}
}
\end{itemize}

\paragraph{Closure of the macroscopic model under the {scaling}~\eqref{ass:epsscal3APP}} Under the {scaling}~\eqref{ass:epsscal3APP}, in the asymptotic regime $\varepsilon \to 0^+$:
\begin{itemize}
\item from~\eqref{eq:goveqn} and~\eqref{eq:goveqrhoU} one formally finds, respectively, \eqref{def:neps0} and \eqref{def:Ueps0}, where $\Ub_T$ is defined via~\eqref{def:UTKeps0};
\item from~\eqref{eq:goveqrhoAPP}, using the expression for $\Ub$ given by~\eqref{def:Ueps0} and~\eqref{def:UTKeps0}, one formally obtains 
\begin{equation}\label{eq:govern3APP}
\partial_t \rho + \nabla_\x \cdot \left(\rho \, \Ub_T\right) = 0 \, ,
\end{equation}
with $\Ub_T$ being defined via~\eqref{def:UTKeps0}.
\end{itemize}

\begin{remark}
Note that, under the {scaling}~\eqref{ass:epsscal3APP}, in the asymptotic regime $\varepsilon \to 0^+$ from~\eqref{eq:Boltz_coll_2} one formally finds the expression for $p$ given by~\eqref{eq:pclosure1} -- i.e. if assumptions~\eqref{ass:epsscal3APP} hold then~\eqref{eq:pclosure1} is the actual expression for $p$ and not only a closure approximation -- which makes it possible to compute explicitly all moments of $p$, including the average velocity and the variance-covariance matrix defined via~\eqref{def:U} and~\eqref{def:rhoD}. Moreover, note that, under the {scaling}~\eqref{ass:epsscal2}, making the ansatz~\eqref{def:neps0} -- i.e. assuming that the normalised distribution of the cell population in the phenotype space $n$ is fully determined by the local environmental conditions -- one could formally reduce the model~\eqref{eq:govern2} to the model~\eqref{eq:govern3APP}.
\end{remark}

\paragraph{Hyperbolic limit of the phenotype-structured kinetic equation} Under the {scaling}~\eqref{ass:epsscal3APP}, it is also possible to derive a more accurate closed macroscopic model through the hyperbolic limit of the phenotype-structured kinetic equation~\eqref{eq:Boltz_coll_2:strong}. This model consists of a first order in $\varepsilon$ correction to the PDE~\eqref{eq:govern3APP} (i.e. the PDE~\eqref{eq:govern3}), which is derived by means of an asymptotic procedure whereby one starts from the phenotype-structured kinetic equation~\eqref{eq:Boltz_coll_2:strong} under the {scaling}~\eqref{ass:epsscal3APP} and makes the Chapman-Enskog expansion~\eqref{ass.CE} for $f_{\varepsilon}$ -- see~\eqref{mesomacromodels}.


\section{Considerations about the {scaling}~\eqref{ass:epsscal3}}\label{sec:justscal}
Denoting by $t_0$ and $L$ some characteristic time and length scales of the system and by $V$ and $\bar{\rho}$ some reference values of the cell speed and the cell number density, letting
$$
t \rightarrow \dfrac{t}{t_0} \,, \quad {\bf x} \rightarrow \dfrac{{\bf x}}{L} \,, \quad {\bf v} \rightarrow \dfrac{{\bf v}}{V} \,, \quad  \rho \rightarrow \dfrac{\rho}{\bar{\rho}} \,, \quad f \rightarrow \dfrac{f}{\bar{\rho}/V^d}
$$
and
$$
T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y)\rightarrow \dfrac{T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y)}{V^d} \, ,
$$
we obtain the following non-dimensionalised form of the phenotype-structured kinetic equation~\eqref{eq:Boltz_coll_2:strong} for the distribution $f(t,\x,\bnu,y)$
\begin{eqnarray}\label{eq:cinetique_nondim}
\textrm{St} \,  \partial_t f + \vb \cdot \nabla_\x f &=& \dfrac{1}{\textrm{Kn}_{\bnu}}  \left(\rho \, T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y) \, n - f \right) \nonumber \\
&& + \dfrac{1}{\textrm{Kn}_y}  \left(\int_{0}^1 K[\mathcal{S}^\ddagger](y|y') \, f(t,\x,\bnu,y') \,  {\rm d}y' \, - f \right) \, ,
\end{eqnarray}
where the Strouhal number, $\textrm{St}$, and the Knudsen numbers, $\textrm{Kn}_{\bnu}$ and $\textrm{Kn}_y$, are defined as
\begin{equation*}
    \textrm{St}:=\dfrac{L}{V t_0}, \qquad  
    \textrm{Kn}_{\bnu}:=\dfrac{V}{L \mu}, \qquad \textrm{Kn}_y:=\dfrac{V}{L \lambda} \, .
\end{equation*}
Consistently with the experiments corresponding to Figure 1A in~\cite{goodman1989e8}, we choose $t_0=48$h, $V=0.5$cm/h, $L=10$cm, and $\mu=0.5$h$^{-1}$, and we also consider phenotypic changes and spatial movement of cells to occur on similar time scales (i.e. $\lambda \approx \mu$). Hence
\[
\dfrac{L}{V t_0} \approx 1 \, , \qquad \dfrac{V}{L \mu} =10^{-1} \, , \qquad \dfrac{V}{L \mu} \approx \dfrac{V}{L \lambda} \, .
\] 
It is then natural to introduce a small parameter $\varepsilon \in \mathbb{R}^+$ and set 
$$
\textrm{St} = 1 \, , \qquad \textrm{Kn}_{\bnu} = \varepsilon \, , \qquad \textrm{Kn}_{y} = \varepsilon \, .
$$
Substituting into~\eqref{eq:cinetique_nondim} yields 
$$
\partial_t f + \vb \cdot \nabla_\x f = \dfrac{1}{\varepsilon}  \left(\rho \, T[\mathcal{S},\mathcal{S}^\dagger](\bnu;y) \, n - f \right)+ \dfrac{1}{\varepsilon}  \left(\int_{0}^1 K[\mathcal{S}^\ddagger](y|y') \, f(t,\x,\bnu,y') \,  {\rm d}y' \, - f \right) \, ,
$$
which corresponds to~\eqref{eq:Boltz_coll_2:strong} under the {scaling}~\eqref{ass:epsscal3}, thus indicating that, in the light of the experiments of~\cite{goodman1989e8}, it is reasonable to consider the {scaling}~\eqref{ass:epsscal3}. 


