\bar{C}_L  & x_1\in \left[0,\frac{1}{3}L_M\right]\cup \left(\frac{2}{3}L_M,L_M\right]\,, \\
0 \,& \text{otherwise}\,,
\end{cases}} 
\quad \forall \,  x_2\in[-L_m,L_M] \, ,
