		\begin{theorem}\label{Univsup}
			Let $\mathcal{V}$ be a variety of graded algebra. Assume that $A$ is a finite-dimensional graded-simple and central algebra such that $A\otimes E$ lies in  	$\mathcal{V}$. For all $B\in \mathcal{V}$,  there exists a superring $\Xi$, and a graded homomorphism $\varrho_\Xi\colon B\rightarrow A\otimes \Xi$ such that: 	
			\begin{enumerate}
				\item [(a)] \label{rho-asup} The entries of the elements of the set $\{\varrho_\Xi(b)\mid b\in B\}$ do generate, together with the element 1, the algebra $\Xi$;
				\item [(b)] For every supercommutative-associative algebra $F_S$ over $K$ and for every graded homomorphism $\kappa\colon B\rightarrow A\otimes F_S$ there exists a graded homomorphism $\zeta\colon \Xi\to F_S$ such that, for the induced map $\zeta_A\colon A\otimes \Xi\to A\otimes F_S$, the relation $\zeta_A\varrho_\Xi=\kappa$ holds.
			\end{enumerate}
		\end{theorem}

