\begin{document}

\title{Mutli-Level Autoencoder: Deep Learning Based Channel Coding and Modulation 
%{\footnotesize %\textsuperscript{*}Note: Sub-titles are not captured in Xplore and
%should not be used}
}

\author{\IEEEauthorblockN{Ahmad Abdel-Qader}
