\title{Oscillation-Induced Frequency Generation in 1D Quantum Droplets under Harmonic–Gaussian Confinements}
\author{Jagnyaseni Jogania}
\affiliation{C. V. Raman Global University, Bhubaneswar, Odisha 752 054, India}
\author{Saurab Das}
\affiliation{Indian Institute of Information Technology Vadodara, Gujarat, India 382 028}
\author{Ajay Nath}
