\section{Appendix A}
The underlying dynamics can be solved analytically by using Lagrangian variational (LV) approach under some approximations \cite{Otajonov, Chen, Saha}. We start by considering the following ansatz solution,
\begin{eqnarray}
\psi(x,t)=A(t)\exp\Big[-\frac{x^2}{2\omega(t)^2}+i\beta(t)x^2+i\phi(t)\Big],\label{ansatz}
\end{eqnarray}
where $\omega(t)$ is the width, $\beta(t)$ is the chirping parameter and $\phi(t)$ is a absolute phase.
The Lagrangian density corresponding to the above ansatz is written as,

\begin{eqnarray}
l_{g}=\frac{i}{2}\Big(\psi(x,t)\frac{\partial\psi^{*}(x,t)}{\partial t}-\psi^{*}(x,t)\frac{\partial\psi(x,t)}{\partial t}\Big)\nonumber\\
+\frac{1}{2}\Big|\frac{\partial\psi(x,t)}{\partial x}\Big|^{2}+\frac{1}{2}\alpha(t)^2x^2|\psi(x,t)|^{2}\nonumber\\+ C(t)\exp\Big(\frac{-x^2}{2\sigma^2}\Big)|\psi(x,t)|^2
+\frac{1}{2}|\psi(x,t)|^4-\frac{1}{2}\psi(x,t)|^\frac{3}{2}\nonumber\\
\end{eqnarray}

\begin{eqnarray}
 l_ 1= \frac{i}{2}\Big(\psi(x,t)\frac{\partial\psi^{*}(x,t)}{\partial t}-\psi^{*}(x,t)\frac{\partial\psi(x,t)}{\partial t}\Big)\nonumber\\
 =\exp\Big(-\frac{x^2}{\omega(t)^2}\Big)A(t)^2 \Big(x^2\beta^\prime(t)+\phi^\prime(t)
\Big )
 \end{eqnarray}

 \begin{eqnarray}
L_1=\int_{-\infty}^{\infty}\exp\Big(-\frac{x^2}{\omega(t)^2}\Big)A(t)^2 \Big(x^2\beta^\prime(t)+\phi^\prime(t)\Big )dx\nonumber\\
=\frac{\sqrt{\pi}A(t)^2(\omega(t)^2\beta^\prime(t)+2\phi^\prime(t))}{2\sqrt\frac{1}{\omega(t)^2}}
 \end{eqnarray}

\begin{eqnarray}
l_2= \frac{1}{2}\Big|\frac{\partial\psi(x,t)}{\partial x}\Big|^{2}
&=\frac{\exp\Big(-\frac{x^2}{\omega(t)^2}x^2A(t)^2(1+4\beta(t)^2\omega(t)^4)\Big)}{2\omega(t)^4}
\nonumber\\
\end{eqnarray}

\begin{eqnarray}
L_2=\int_{-\infty}^{\infty}\frac{\exp\Big(-\frac{x^2}{\omega(t)^2}x^2A(t)^2(1+4\beta(t)^2\omega(t)^4)\Big)}{2\omega(t)^4}dx\nonumber\\ 
=\frac{1}{4}\sqrt{\pi}A(t)^2\sqrt{\frac{1}{\omega(t)^2}}(1+4\beta(t)^2\omega(t)^4)
\end{eqnarray}

\begin{eqnarray}
l_3=\frac{1}{2}\gamma^2x^2|\psi(x,t)|^{2}+C(t)\exp\Big(\frac{-x^2}{2\sigma^2}\Big)|\psi(x,t)|^2\nonumber\\
=\exp\Big(-\frac{x^2}{2\sigma^2}-\frac{x^2}{\omega(t)^2}\Big)A(t)^2C(t)+\nonumber\\
\frac{1}{2}\exp\Big(-\frac{x^2}{\omega(t)^2}\Big)x^2A(t)^2\gamma^2
\end{eqnarray}

\begin{eqnarray}
L_3=\int_{-\infty}^{\infty}\Big(\exp\Big(-\frac{x^2}{2\sigma^2}-\frac{x^2}{\omega(t)^2}\Big)A(t)^2C(t)+\nonumber\\
\frac{1}{2}\exp\Big(-\frac{x^2}{\omega(t)^2}\Big)x^2A(t)^2\gamma^2\Big)dx \nonumber\\
= \frac{\sqrt{2\pi}A(t)^2C(t)}{\sqrt{\frac{1}{\sigma^2}+\frac{2}{\omega(t)^2}}}+\frac{\sqrt{\pi}A(t)^2\gamma^2}{4(\frac{1}{\omega(t)^2})^\frac{3}{2}}
\end{eqnarray}

\begin{eqnarray}
l_4= \frac{1}{2}|\psi(x,t)|^4
= \frac{1}{2}\exp\Big(-\frac{2x^2}{\omega(t)^2}\Big)A(t)^4
\end{eqnarray}

\begin{eqnarray}
L_4=\int_{-\infty}^{\infty}\frac{1}{2}\exp\Big(-\frac{2x^2}{\omega(t)^2}\Big)A(t)^4dx
=\frac{\sqrt{\frac{\pi}{2}}A(t)^4}{2\sqrt{\frac{1}{\omega(t)^2}}}
\end{eqnarray}

\begin{eqnarray}
l_5= -\frac{1}{2}\psi(x,t)|^\frac{3}{2}
=-\frac{2}{3}\Big(\exp\Big(-\frac{x^2}{\omega(t)^2}\Big)A(t)^2\Big)^\frac{3}{2}
\end{eqnarray}

\begin{eqnarray}
L_5=\int_{-\infty}^{\infty}-\frac{2}{3}\Big(\exp\Big(-\frac{x^2}{\omega(t)^2}\Big)A(t)^2\Big)^\frac{3}{2}dx\nonumber\\
=-\frac{2\sqrt{\frac{2\pi}{3}}A(t)^3}{3\sqrt{\frac{1}{\omega(t)^2}}}
\end{eqnarray}

The effective total Lagrangian is given by
\begin{eqnarray}
L_{e\!f\!f}=\int_{-\infty}^{\infty}l_{g}dx\nonumber\\
=L_{1}+L_{2}+L_{3}+L_{4}+L_{5}\nonumber\\
=\frac{\sqrt{2\pi}A(t)^2C(t)}{\sqrt{\frac{1}{\sigma^2}+\frac{2}{\omega(t)^2}}}
+\frac{\sqrt{\pi}A(t)^2\gamma^2}{4\Big(\frac{1}{\omega(t)^2}\Big)^\frac{3}{2}}\nonumber\\
-\frac{2\sqrt{\frac{2\pi}{3}A(t)^3}}{3\sqrt{\frac{1}{\omega(t)^2}}}
+\frac{\sqrt{\frac{\pi}{2}}A(t)^4}{2\sqrt{\frac{1}{\omega(t)^2}}}\nonumber\\
+\frac{1}{4}\sqrt{\pi}A(t)^2\sqrt{\frac{1}{\omega(t)^2}(1+4\beta(t)^2\omega(t)^4)}\nonumber\\
+\frac{\sqrt{\pi}A(t)^2\Big(\omega(t)^2\beta^\prime(t)+2\phi^\prime(t)\Big)}{2\sqrt{\frac{1}{\omega(t)^2}}}
\end{eqnarray}

The corresponding Euler-Lagrange equation is given by
\begin{eqnarray}
\frac{d}{dt}\frac{\partial L_{e\!f\!f}}{\partial \dot{u}}=\frac{\partial L_{e\!f\!f}}{\partial u},\label{el}
\end{eqnarray}
where $u$ is one of the variational parameters, $\omega(t)$, $\beta(t)$ and $\phi(t)$. After solving Eq.(\ref{el})
for $u=\omega(t)$, $\beta(t)$ and $\phi(t)$, we obtain that the condensed width variation is derived as

\begin{eqnarray}
\omega ''(t)+\gamma^2 \omega (t)-\frac{1}{\omega (t)^3}-\frac{2 \sqrt{2} \sigma  c(t) \omega (t)}{\left(2 \sigma ^2+\omega (t)^2\right)^{3/2}}-\nonumber\\
\frac{\sqrt{\frac{N_{A}}{2 \pi }}}{\omega (t)^2}+\frac{2 \sqrt{6 N_{A}}}{9 \sqrt[4]{\pi } \omega (t)^{3/2}}=0\label{wd}
\end{eqnarray}


