    \centering
    \includegraphics{images/Scheme_BRiPTi.pdf}
    \caption{Organization of the i-th branch/labeled point structure within a bifurcation diagram structure. The fields in \textit{magenta} are contained only in labeled points associated with POs or BVPs.}
    \label{Fig:Scheme:BRiPTi}
