    We encourage the user to edit this file to customize the visualization. Figure~\ref{FIG:OPTSBD} contains a complete list of these settings.
    \end{enumerate}

\begin{sidewaysfigure}
    \centering
    \centerline{\includegraphics[width=9in]{images/Scheme_OPTSBD.pdf}}
