 \begin{section}{Left algebraicity over centralizers}\label{sec: algebraic elements} 
In general, it seems dif and only ificult to make substantial assertions about the structure of the set of left algebraic elements over a division subring. However, the situation becomes more tractable  when the division subring is the centralizer of a given element. As we will see in the next chapter, studying centralizers can help us to understand the class of division rings over which the central Nullstellensatz holds. Therefore, we devote this section to the study of left algebraicity over centralizers. 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{subsection}{Basic results}

	Let us fix a division ring $D$ throughout this subsection. Given a subsets $S$ of $D$, we set
	\[
	C(S)\colonequals \{a\in D\,|\, sa=as \text{ for all } s\in S\}.
	\]
	We adopt the convention $C(a_1,\dots,a_n)\colonequals C(\{a_1,\dots.a_n\})$. It is evident that for any subset $S$ of $D$, the centralizer $C(S)$ is a division subring of $D$. To explore algebraicity over centralizers, we begin with the following lemma. 
	\begin{lemma}\label{lem: left-right algebraic}
		Let $b\in D$ be a right root of a nonzero polynomial $p(x)=a_nx^n+\cdots+a_1x+a_0\in D[x]$. Then, $C(a_0,\dots,a_{n})$ is  right algebraic over $C(b)$ with right degree at most $n$. Moreover, the right $C(b)$-vector space generated by $C(a_0,\dots,a_{n})$ is finite-dimensional with dimension at most $n$. 
	\end{lemma} 
	\begin{proof}
		Observe that   	
		\[
		E(p,b)=\{r\in D\,|\,  a_nrb^n+a_{n-1}rb^{n-1}+\cdots+a_1rb+a_0r=0\}.
		\]
		As seen in Subsection \ref{subsec: evaluation}, $E(p,b)$ is a right vector space over $C(b)$ and $\dim_{C(b)} E(p,b)\leq n$ by Inequality \ref{inequ: equality for roots}. Clearly,  $C(a_0,\dots,a_{n})\subset E(p,b)$. In particular, for each $a\in C(a_0,\dots,a_{n})$, the elements $1,a,\dots.,a^{n}$ are right $C(b)$-linearly independent. Hence, $C(a_0,\dots,a_{n})$ is right algebraic over $C(b)$ with right degree at most $n$, which completes the proof. 
	\end{proof}

	In what follows, let $S$ be a subgroup of  the multiplicative group $D\setminus \{0\}$. Assume that $b\in D$ is left algebraic over $C(S)$, and let 	
	\[ p(x)=x^n+a_{n-1}x^{n-1}+\cdots+a_1x+a_0\in C(S)[x]\] be the minimal left polynomial of $b$ over $C(S)$. 
	\begin{proposition}\label{prop: left algebraic with subgroup}
		1) $\cap_{r\in S}D[x](x-rbr^{-1})=D[x]p(x)$.\\
		2) Every right root of $p(x)$ in $D$ is conjugate to $b$. \\
		3) The dimension of $E(p,b)$ as a right $C(b)$-vector space is $n$. 
	\end{proposition}
	\begin{proof}
		1) Since $D[x]$ is a principal ideal ring, we have $\cap_{r\in S}D[x](x-rbr^{-1})=D[x]q(x)$ for some monic $q(x)\in D[x]$. Note that $p(x)\in D[x]q(x)$ because $p(rbr^{-1})=0$ for all $r\in S\subset  E(p,b)$. For every $s\in S$, we have
		\[
		s\left( \cap_{r\in S}D[x](x-rbr^{-1}) \right)s^{-1} =D[x]sq(x)s^{-1},
		\]
		implying
		\[
		\cap_{r\in S}D[x](x-srbr^{-1}s^{-1}) =D[x]sq(x)s^{-1}\implies D[x]q(x)=D[x]sq(x)s^{-1}.
		\]
		It follows that $q(x)=sq(x)s^{-1}$ for all $s\in S$, that is, $q(x)\in C(S)[x]$. Since $q(b)=0$, we conclude that $q(x)=p(x)$.\\
		The second statement follows from 1), and 3) follows from 2). 
	\end{proof}
	\begin{remark}
		It follows from the  first part of the proposition that the polynomial $p(x)$ is a Wedderburn polynomial, a concept defined and studied  by Lam and Leroy \cite{lam2004wedderburn}. 
	\end{remark}
\end{subsection}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{subsection}{Algebraicity over $C(a)$}
	As before, let $D$ be a fixed division ring throughout this subsection. 
	\begin{proposition}\label{prop: leftalg-rightalg}
		For any $a,b\in D$, $b$ is left algebraic over $C(a)$ if and only if $a$ is right algebraic over $C(b)$, in which case the left degree of $b$ over $C(a)$ coincides with  the right degree of $a$ over $C(b)$. 
	\end{proposition}
	\begin{proof}
		Let \[ p(x)=x^n+a_{n-1}x^{n-1}+\cdots+a_1x+a_0\] be the minimal left polynomial of $b$ over $C(a)$. By Lemma \ref{lem: left-right algebraic}, every element of $C(a_0,\dots,a_{n-1})$ is right algebraic over $C(b)$ with right degree at most  $n$. Since $a\in C(a_0,\dots,a_{n-1})$, it follows that $a$ is  right algebraic over $C(b)$ with right degree at most $n$. By symmetry, the left degree of $b$ over $C(a)$ equals the right degree of $a$ over $C(b)$.
	\end{proof}
	As a consequence, we obtain the following description of the set of left algebraic elements over the centralizer of an element. 
	\begin{corollary}\label{cor: closure of C(a)}
		The set of all left algebraic elements of $D$ over $C(a)$ is 
		$\cup C(a_0,\dots,a_{n-1})$,
		where the union ranges over all $(a_0,\dots,a_{n-1})\in D^{n}$ satisfying
		\[
		a^n+a^{n-1}a_{n-1}+\cdots+aa_1+a_0=0.
		\]
	\end{corollary}
	\begin{proof}
		Let  $(a_0,\dots,a_{n-1})\in D^{n}$ satisfy the equation
		\[
			a^n+a^{n-1}a_{n-1}+\cdots+aa_1+a_0=0.
		\]
		It follows from Lemma \ref{lem: left-right algebraic} that every element of $C(a_0,\dots,a_{n-1})$ is left algebraic over $C(a)$. This proves that the union is left algebraic over $C(a)$. Now, let $b\in D$ be 
		left algebraic over $C(a)$. By Proposition \ref{prop: leftalg-rightalg}, $a$ is right algebraic over $C(b)$. Let   \[ p(x)=x^n+x^{n-1}a_{n-1}+\cdots+xa_1+a_0\]
		be the minimal right polynomial of $a$ over $C(b)$. We have
		\[
			0=p_r(a)=a^n+a^{n-1}a_{n-1}+\cdots+aa_1+a_0.
		\] 
		Since $b\in C(a_0,\dots,a_{n-1})$, the result follows. 

	\end{proof}


\end{subsection}
