\begin{subsection}{A rational criterion for algebraicity over $C(a)$}
Let $D$ be a division ring, and let $F(x_0,x_1,\dots)$ denote the set of all rational expressions in $x_0,x_1,\dots$ with coefficients from the prime field $F$ of $D$. For a comprehensive discussion of rational expressions, the reader is referred to Cohn's book \cite[Subsecion 7.2]{cohn1995skew}. Inductively, we define a sequence of rational expressions $L_1,L_2,\dots$ in $F(x_0,x_1,\dots)$  as follows: $L_1(x_0,x_1)\colonequals x_1$, and for $n\geq 1$, 
\[
	L_{n+1}(x_0,x_1,\dots,x_{n+1}) \colonequals L_n(x_0,[x_0,x_1x_{n+1}^{-1}],\dots,[x_0,x_nx_{n+1}^{-1}]),
\] 
where $[a,b]\colonequals ab-ba$.
\begin{lemma}\label{lem: linearly independence}
 For $a,b_1,\dots,b_n\in D$, the elements $b_1,\dots,b_n\in D$ are left linearly independent over $C(a)$ if and only if $L_n(a,b_1,\dots,b_n)$ is defined and nonzero.    
\end{lemma}
\begin{proof}
	The key observation is that $b_1,\dots,b_n\in D$ are left linearly independent over $C(a)$ if and only if $b_n\neq 0$ and $[a,b_1b_{n}^{-1}],\dots,[a,b_{n-1}b_{n}^{-1}]$ are left linearly independent over $C(a)$. A straightforward  induction on $n$ then proves the result.
\end{proof}

\begin{remark}
	It is easy to see that $L_n(a,b_1,\dots,b_n)$ is zero if and only if  $b_1,\dots,b_n$ are left linearly dependent over $C(a)$, while every proper subset of  $\{b_1,\dots,b_n\}$ remains left linearly dependent over $C(a)$. 
\end{remark}

By defining $F_n(x,y)\colonequals L_n(x,1,y,\dots,y^n)$, we can derive a rational criterion for left algebraicity over the centralizer of an element:  
\begin{proposition}\label{prop: rational identity for algebraicity}
	For any $a,b\in D$, the element $b$ is left algebraic of left degree $n$ over $C(a)$ if and only if $F_{n}(a,b)=0$.  
\end{proposition}
\begin{proof}
	Note that $b$ is left algebraic of left degree $n$ over $C(a)$ if and only if $1,b,\dots,b^{n-1}$ are left linearly independent over $C(a)$, while
	$1,b,\dots,b^{n}$ are left linearly dependent over $C(a)$. An application of Lemma \ref{lem: linearly independence} gives the result. 
\end{proof}
As an application of of this criterion, we present the following result. 
\begin{proposition}
	Let $D$ be  a division ring with infinite center. Suppose there exists a natural number $n$ such that every $b\in D$ is left algebraic of left degree $\leq n$ over $C(a)$ for all $a\in D$. Then, $D$ is centrally finite. 
\end{proposition}
\begin{proof}
	By Proposition \ref{prop: rational identity for algebraicity}, the rational expression $F_n(x,y)$ is a rational identity for $D$. Since the center of $D$ is infinite and $D$ satisfies a (nontrivial) rational identity, it follows from foundational results in the theory of generalized rational identities (see \cite{rowen1980polynomial}) that $D$ is centrally finite.   
\end{proof}
Clearly, the converse of the proposition holds true. 
\begin{remark}
	It is worth noting that Bell et al. have proved that if a division ring  is of bounded left degree over a (commutative) subfield, then it is centrally finite \cite{bell2013shirshov}.
\end{remark}

\end{subsection}


