Before introducing the quantum ${\frak{gl}}$-weight system, 
we define the universal characteristic map, which makes
computations more handleable.
For the next definition, we need the concatenation product on Hecke algebras.
 The \emph{concatenation product} is the algebra homomorphism $\mathbf{m}:\mathbb{H}_m \times \mathbb{H}_n \rightarrow \mathbb{H}_{m+n},\quad i=1,\dots,m,\quad j=1,\dots,n$, defined on the generators by the formula
$$\mathbf{m}: (g_i,g_j) \mapsto g_i g_{j+m}.$$

\begin{defn} \label{UnivCharMapDef}
    The { \it universal characteristic map} is the sequence of linear maps 
    $\chi_m : \mathbb{H}_m \rightarrow \mathbb{C}(q)[p_1, \dots, p_m]$,
    $m=1,2,\dots$, completely determined by the following properties:
        \begin{enumerate}
        \item~\label{UCMpm} $\chi_{m+n}(\mathbf{m}(x, y))=\chi_m(x)\chi_n(y)$, where $x \in \mathbb{H}_{m}$, $y \in \mathbb{H}_{n}$;
        \item\label{UCMpb} $\chi_m(C_{1m}) = p_m$, for each $m>0$;
        \item\label{UCMpe} $\chi_{m}(g_ix) = \chi_{m}(xg_i)$,
        for all $x \in \mathbb{H}_{m}$ and $1 \leq i \leq m-1$.
    \end{enumerate}
\end{defn}
Properties~\ref{UCMpm} and~\ref{UCMpb} imply the equality 
$$\chi_{m}(C_{m_1k_1} \dots C_{m_lk_l}) = p_{k_1-m_1+1}\dots p_{k_l-m_l+1} \times (p_1)^{m - \sum\limits_{i=1}^{l}(k_i-m_i+1)},$$
 where $m_1 < k_1 < m_2 < k_2 < \dots <m_l < k_l.$ Therefore, by Lemma \ref{UsefulLemma}, properties~\ref{UCMpm}--\ref{UCMpe} uniquely determine the set of mappings. Consistency of the definition will be proven in the next part of the section. 

\begin{defn}
    The {\it quantum trace} on $\mathbb{H}_m$, $m\geq 1$ is the sequence of linear mappings $$\BT r_{m}: \mathbb{H}_m \rightarrow \mathbb{H}_{m-1}$$ defined on the basic element $C_{i_1 1}C_{i_2 2}\dots C_{i_m m}$ by the formula
    $$\BT r_{m}(C_{i_1 1}\dots C_{i_m m})=
\left\{ 
    \begin{array}{l}
        (C_{i_1 1}\dots C_{i_{m-1} m-1}) C_{i_m m-1} ,\quad i_m<m\\
        q^{-1}[N]_q(C_{i_1 1}\dots C_{i_{m-1} m-1}),\quad i_m=m
    \end{array} 
\right. .$$
\end{defn}

\begin{defn} \label{UnivWeightSystemDef}
    The {\it universal quantum ${\frak{gl}}$-weight system} is the sequence of linear mappings $\omega_{m}:\mathbb{H}_m \rightarrow \mathbb{C}(q)[q^{-N};C_1,C_2,\dots],$ $m=1,2,\dots,$ completely determined by the following properties:
    \begin{enumerate}
        \item\label{UQWpm} $\omega_{m+n}(\mathbf{m}(x, y))= \omega_m(x)\omega_n(y)$, where $x \in \mathbb{H}_{m}$, $y \in \mathbb{H}_{n}$;
        \item\label{UQWpb} $\omega_m(C_{1m}) = C_m$, for any $m>0$;
        \item\label{UQWpe} $\omega_{m}(g_ix - xg_i)=$ $$= \omega_{m-1}(\BT r_{m}(g_{m-1}^{-1} \dots g_{i+1}^{-1} x g_{i+1} \dots g_{m-1}-g_{m-1}^{-1} \dots g_{i}^{-1} x g_{i} \dots g_{m-1})),$$
        for any $x \in \mathbb{H}_{m}$ and $1 \leq i \leq m-1$.
    \end{enumerate}
\end{defn}
The universal quantum ${\frak{gl}}$-weight system is uniquely determined by properties \ref{UQWpm}--\ref{UQWpe} due to the relation
$$\omega_{m}(C_{m_1k_1} \dots C_{m_lk_l}) = C_{k_1-m_1+1}\dots C_{k_l-m_l+1} \times (C_1)^{m - \sum\limits_{i=1}^{l}(k_i-m_i+1)},$$ where $m_1 < k_1 < m_2 < k_2 < \dots <m_l < k_l$ and Lemma \ref{UsefulLemma}. We have not yet establish that the maps $\chi_m$ and $\omega_m$ exist. Below in this section we will construct a characteristic mapping and a quantum weight system in the Reflection Equation algebra. This construction will allow us to introduce universal properties of the maps $\chi_m$ and $\omega_m$ (Proposition \ref{UnivPropCharMap2} and Corollary \ref{CorUnivProp}) and to prove their existence (Proposition \ref{PropUnivCharMap} and Proposition \ref{PropUnivWeightMap}).

\begin{ex}
Each basis element $C_{i_1 1}C_{i_2 2}\dots C_{i_m m}$ of the Hecke algebra can be associated with a permutation. This permutation is obtained by replacing each generator $g_i$ with the transposition $(i,i+1)$. This defines a bijective correspondence between permutations and the basis elements of the Hecke algebra.
However, the composition of the correspondence with the quantum weight system does not determine the weight system, see examples below.
We now compute the values of the quantum weight system for certain elements of the Hecke algebra corresponding to specific permutations.

    \begin{enumerate}
        \item The value of the quantum weight system on the standard cycle $(123)$ is $\omega_3(g_2g_1) = C_3$.
        \item  The value on the cycle $(132)$ is computed as follows
        \begin{align*}
           & \omega_3(g_1g_2) = \omega_3(g_2g_1) + \omega_2 (\BT r_{3} (g_2^{-1} g_2 g_2) - \omega_2(\BT r_{3}(g_2^{-1} g_1^{-1} g_2 g_1 g_2))= \\
           &= C_3 + \omega_2(1) - q^{-1}[N]_q \omega_2(g_1) = C_3 + C_1^{2} - q^{-1}[N]_q C_2.
        \end{align*} 
        Here we used the braid relation $g_2^{-1} g_1^{-1} g_2 g_1 g_2 = g_2^{-1}  g_2 g_1 g_2^{-1} g_2 = g_1$.

        \item The value on the transposition $(13)$ is \begin{align*}    
       & \omega_3(g_1g_2g_1) = \omega_3(g_2g_1^2)+\omega_2(\BT r_{3}(g_2^{-1}g_2g_1g_2)) - \omega_2(\BT r_{3}(g_2^{-1}g_1^{-1}g_2g_1g_1g_2)) =\\
       &= C_1C_2 + (q-q^{-1})C_3 +C_2 - \omega_2(\BT r_{3}(g_1g_2^{-1}g_1g_2)) = C_1C_2+(q-q^{-1})C_3\end{align*}
       The braid relation was applied twice $g_2^{-1}g_1^{-1}g_2g_1g_1g_2 = g_1g_2^{-1}g_1^{-1}g_1g_1g_2 = g_1^2g_2g_1^{-1}$.

        \item The permutation $(1243)$ corresponds to the element $g_1g_3g_2$ of the Hecke algebra. The value of the quantum weight system on this element is computed as:
        \begin{align*}
            &\omega_4(g_1g_3g_2) =  \omega_4(g_3g_2g_1)+ \omega_3(\BT r_{4} (g_3^{-1}g_2^{-1}g_3g_2^2g_3 - g_3^{-1}g_2^{-1}g_{1}^{-1}g_3g_2g_1g_2g_3)) = \\
            &= C_4 +C_1C_2 - q^{-1}[N]_qC_3 
        \end{align*}
        The calculation relies on: $g_3^{-1}g_2^{-1}g_{1}^{-1}g_3g_2g_1g_2g_3 = g_3^{-1}g_2^{-1}g_3g_2g_1g_3 = g_2g_3^{-1}g_2^{-1}g_2g_1g_3 = g_2g_1.$

        \item For the permutation $(13)(24)$, the corresponding element of the Hecke algebra looks like $g_2g_1g_3g_2$. 
        \begin{align*}
            &\omega_4(g_2g_1g_3g_2) = \\ 
            &=\omega_4(g_1g_3 + (q-q^{-1})g_1g_3g_2) + \omega_3(\BT r_{4}(g_3^{-1}g_1g_3g_2g_3 - g_3^{-1}g_2^{-1}g_1g_3g_2^2g_3)) = \\ 
            &= \omega_4(g_1g_3) + (q-q^{-1})\omega_4(g_1g_3g_2) + \omega_3(g_1g_2) - \omega_3(g_2+\frac{1}{q^{2N}}g_2g_1) = \\
            &= C_2^2 + (q-q^{-1})(C_4+C_2C_1) +C_1^2 - q^{-1}[N]_qC_2-C_1C_2
        \end{align*}
        To calculate the value $\omega_3(\BT r_{4}(g_3^{-1}g_2^{-1}g_1g_3g_2^2g_3))$, we used the following chain of equalities $g_3^{-1}g_2^{-1}g_1g_3g_2^2g_3 = g_2g_3^{-1}g_2^{-1}g_1(1+(q-q^{-1})g_2)g_3 = g_2g_3^{-1}g_2^{-1}g_3g_1 + (q-q^{-1})g_2g_3^{-1}g_2^{-1}g_1g_2g_3 = g_2^2g_3^{-1}g_2^{-1}g_1 + (q-q^{-1})g_2g_1g_2g_3g_2^{-1}g_1^{-1}$ and the trace property $\BT r_4(g_3^{-1}) = \BT r_4(g_3) +(q-q^{-1}) q^{-1}[N]_q= q^{-2N}$.

        \item For the permutation $(143)$, the corresponding element of the Hecke algebra looks like $g_1g_3g_2g_1$.
        \begin{align*}
           & \omega_4(g_1g_3g_2g_1)= \\
           &=C_3C_1 + (q-q^{-1})C_4 + \omega_3(\BT r_{4}(g_3^{-1}g_2^{-1}g_3g_2g_1g_2g_3-g_3^{-1}g_2^{-1}g_1^{-1}g_3g_2g_1^{2}g_2g_3))= \\ 
           &=C_3C_1 + (q-q^{-1})C_4 + \omega_3(\BT r_{4}(g_2g_3^{-1}g_1g_2g_3-g_2g_1g_3^{-1}g_2^{-1}g_1g_2g_3)) = \\
           &= C_3C_1+(q-q^{-1})C_4
        \end{align*}
        The last equality follows from: $g_3^{-1}g_2^{-1}g_1g_2g_3 = g_1g_2g_3g_2^{-1}g_1^{-1}$ and $g_3^{-1}g_2g_3 = g_2g_3g_2^{-1}$. The coefficient of $C_3$ vanishes: $-q^{-1}[N]_q +1 - q^{-2N} = 0$.

        \item For the permutation $(1423)$, the corresponding element of the Hecke algebra looks like $g_2g_1g_3g_2g_1$.
        \begin{align*}
            &\omega_4(g_2g_1g_3g_2g_1)= \\ 
            &= \omega_4(g_3g_2g_1) + (q-q^{-1})\omega_4(g_1g_3g_2g_1) + \omega_3(g_1g_2g_1 - g_2(q^{-1}[N]_qg_1 + (q-q^{-1})g_1) = \\
            &= C_4 + C_1C_2 - q^{-1}[N]_qC_3+(q-q^{-1})C_3C_1 + (q-q^{-1})^2C_4
        \end{align*}
        This combines results from items 3 and 6.

        \item For the permutation $(14)(23)$, the corresponding element of the Hecke algebra looks like $g_1g_2g_1g_3g_2g_1$.
        Using recurrence relations, we obtain 
        \begin{align*}
            &\omega_4(g_1g_2g_1g_3g_2g_1) = \\ 
            &= \omega_4(g_2g_1g_3g_2) + (q-q^{-1})\omega_4(g_2g_1g_3g_2g_1) + \omega_3(g_1^2g_2g_1) - \omega_3(g_1g_2g_1^2) = \\ 
            &=  \omega_4(g_2g_1g_3g_2) + (q-q^{-1})\omega_4(g_2g_1g_3g_2g_1) + \omega_3(g_2g_1) - \omega_3(g_1g_2)
        \end{align*}
        Substituting from items 5 and 7:
        \begin{align*}
            &\omega_4(g_1g_2g_1g_3g_2g_1) = \\ 
            &= C_2^{2} + (q-q^{-1})(2C_4 + C_1C_2-q^{-1}[N]_qC_3) +(q-q^{-1})^2C_3C_1 + (q-q^{-1})^3C_4
        \end{align*}
    \end{enumerate}
    In particular, we see that the quantum weight system 
    can take different values on cyclically equivalent permutations,
    as well as the four-term relations do not hold even for diagrams with two chords:
    $$\omega_4(g_1g_3) -\omega_4(g_2g_1g_3g_2) \neq \omega_4(g_1g_2g_1g_3g_2g_1) - \omega_4(g_2g_1g_3g_2). $$ Despite the quantum corrections, the zeroth order terms in $q$ of the obtained expressions coincide with the classical $\gl$ weight system, although at the moment we do not know how to prove this assertion
    in full generality. \hfill\rule{6.5pt}{6.5pt}
\end{ex}


From now on, let us identify the ranges of the invariants $\chi_m$
and $\omega_m$ by expressing the variables $C_1,C_2,\dots$
in the variables $p_1,p_2,\dots$ by means of the following
equality between the generating functions for them:
\begin{equation}\label{e-Cp}
e^{\frac{t}{q-q^{-1}}} \left(q^{-1}[N]_q + \sum\limits_{m=1}^{\infty}\frac{p_m}{m!}\frac{(-t)^m}{(q-q^{-1})^m}\right) = q^{-1}[N]_q + \sum\limits_{m=1}^{\infty}\frac{C_m}{m!}t^m;
\end{equation}
the coefficients are rational functions of~$q$.
This relation is explained using the quantum analogue of the Perelomov-Popov formula (see \cite{GPS}).
It allows one to express the values of the maps $\chi_m$ and $\omega_m$ 
through each other using a formula of the form
$$\omega_m(x) =\frac{1}{(q-q^{-1})^m} \sum\limits_{I \subset \{1,\dots,m\}}(-1)^{|I|}\chi_{|I|}(\tilde{x}_I), \quad  x \in \mathbb{H}_m,$$
where the sum is taken over all subsets $I$ of the set $\{1,\dots,m\}$, symbol $|I|$ denotes the cardinality of $I$ and the element $\tilde{x}_I \in \mathbb{H}_{|I|}$ is obtained from $x$ by conjugation with some invertible element of the algebra $\mathbb{H}_n$ and taking all traces in positions $|I|+1,\dots,m$. Details can be found in Proposition \ref{PropWeightCharConnection}.


\subsection{$R$-matrix representations of Hecke algebras}

In this Section, following~\cite{GPS,GS}, we introduce the Reflection
equation algebra~$\BM(N)$ and two sequences of linear mappings
$$
\chi_{m,N}:\BH_m\to Z\BM(N),\qquad \omega_{m,N}:\BH_m\to Z\BM(N),
$$ 
called the characteristic map and the quantum $\mathfrak{gl}(N)$-weight system,
respectively. Both mappings take value in the center $Z\BM(N)$
of $\BM(N)$, which can be identified with the ring of polynomials
in either of the two set of variables, $p_1,p_2,\dots,p_N$,
$p_i=\chi_{m,N}(C_{1m})$, or $C_1,\dots,C_N$, $C_i=\omega_{m,N}(C_{1m})$.
These two sets of variables are related by Eq.~(\ref{e-Cp}).
Similarly to the classical case, the invariants $\chi_{m,N}$ and
$\omega_{m,N}$ can be viewed as specializations of the universal
characteristic map~$\chi_m$ and the universal quantum $\mathfrak{gl}$-weight
system~$\omega_m$, respectively.
To construct the quantum ${\gl(N)}$-weight system and characteristic map, we need $R$-matrix representations of Hecke algebras (see \cite{OP}) and the associated Reflection Equation algebras (see \cite{GPS}).


We denote by $R=R(N)$, for $N=1,2,\dots$, the 
\emph{Drinfeld--Jimbo $R$-matrix}, which is the
$N^2\times N^2$-matrix acting
on the vector space~$\BC(q)^N\otimes\BC(q)^N$ according to the formula
\begin{equation}
	R(N) = q \sum\limits_{i=1}^N E_{i}^i \otimes E_{i}^i + \sum\limits_{i \neq j} E_{i}^j \otimes E_{j}^i + (q-q^{-1}) \sum\limits_{i<j}E_{i}^i \otimes E_{j}^j,
\end{equation}
where $E_i^j$, $i,j=1,\dots,N$ are standard matrix units. The $R$-matrix acting on the tensor
product of the $i$~th and the $(i+1)$~st factors in a tensor power $V^{\otimes m}$,
$V\equiv\BC(q)^N$, 
will be denoted $R_{i,i+1}$, $i=1,\dots,m-1$.

Below, we will make use of the following properties of the $R$-matrix:
\begin{itemize}
	\item $R^2=I+(q-q^{-1})R$ (the \emph{Hecke relation});
	\item $R_{i-1,i}R_{i,i+1}R_{i-1,i}
	=R_{i,i+1}R_{i-1,i}R_{i,i+1}$ (the \emph{braid relation}).
\end{itemize} 

For a vector space $V=\BC(q)^N$, the mapping 
\begin{equation}  
	\rho : \mathbb{H}_m \rightarrow End(V^{\otimes m}), \qquad 
	\rho:g_i \mapsto R_{i,i+1},
\end{equation} as can be easily seen, defines a representation 
of the Hecke algebra $\mathbb{H}_m$, which we call
the \textit{R-matrix representation}.


\begin{defn} \label{DefRTr}
 The \textit{R-trace} is the mapping $Tr_R : Mat_{N \times N}(\mathbb{C}(q))\otimes V \rightarrow V$ defined by the following formula:
    $$Tr_R(X) = Tr(DX), \quad  X \in Mat_{N \times N}(\mathbb{C}(q))\otimes V,$$ 
    where $D = diag(q^{1-2N},q^{3-2N}, \dots , q^{-1})$.
\end{defn}
 A direct generalization of Definition \ref{DefRTr} is 
that of the \emph{multiple $R$-trace} for a more general matrix $X \in Mat_{N \times N}(\mathbb{C}(q))^{\otimes m} \otimes U$, $1\le k\le n\le m$,
 $$\langle X \rangle_{k,n} = Tr_{R}(X) = Tr_{k,n} (D_k \dots D_n X),$$
 here we also introduce a convenient notation for the $R$-trace. 
The $R$-trace has the cyclic property 
$$\langle XR_{i,i+1} \rangle_{1,m} = \langle R_{i,i+1}X \rangle_{1,m}$$ for any matrix $X \in Mat_{N \times N}(\mathbb{C})^{\otimes m} \otimes U$ and $1 \leq i \leq m-1$, and it is normalized, so that 
$$\langle R_{1,2}\rangle_{2,2}=\BI, \qquad\langle \BI \rangle_{1,1} = q^{-1}[N]_q.$$

% The \emph{Harish-Chandra homomorphism} maps symmetric polynomials of $N$ variables to the center of the Reflection Equation algebra.

 The {\it Reflection Equation algebra} $\BM(N)$
  is generated by $N^2$ generators $m_i^j$, their permutation relations being written in the matrix form as
\begin{equation}\label{REfirst}
    R_{1,2} M_1 R_{1,2} M_1 = M_1 R_{1,2} M_1 R_{1,2},
\end{equation} where $M = ||m_i^j||_{1 \leq i,j, \leq N}$. 


For a matrix  $ K \in Mat_{N \times N}(\mathbb{C}(q)) \otimes \BM(N)$,
 let us denote 
 $$K_{\overline{i}} = R_{i-1,i} \dots R_{1,2} K_1 R_{1,2}^{-1} \dots R_{i-1,i}^{-1},$$
 so that
 $$
 K_{\bar{i}}=R_{i-1,i}K_{\overline{i-1}}R_{i-1,i}^{-1},\qquad i=2,3,\dots,m.
 $$
  There is a sequence of mappings $\chi_{m,N} : \mathbb{H}_m \rightarrow \BM(N)$
   from the Hecke algebras $\mathbb{H}_m$, $m=1,2,\dots$, to the Reflection Equation algebra $\BM(N)$. They are defined by the formula
   $$\chi_{m,N}(x) = \langle M_{\overline{1}} \dots M_{\overline{m}}\rho (x) \rangle_{1,m}, \quad  x \in \mathbb{H}_m.$$
 \begin{defn}
     \rm The mappings $\chi_{m,N}, \,\, m \in \mathbb{Z}_{\geq 1}$ are called \textit{characteristic mappings}.
 \end{defn}
 The value $\chi_{m,N}(x)$ of the characteristic mapping can be expressed as a polynomial in
 the elements~$p_1,p_2,\dots$ defined by

 \begin{equation}\label{e-qps}
 	p_m=\chi_{m,N}(C_{1m}) = \langle M_{\overline{1}} \dots M_{\overline{m}}R_{m-1,m}R_{m-2,m-1}\dots R_{1,2}\rangle_{1,m}.
 \end{equation}
 The elements $p_i$ are called {\it quantum power sums}. They lie in the center of the Reflection Equation algebra and, therefore, the value $\chi_{m,N}(x)$ of the characteristic mapping is a central element of the algebra $\BM(N)$ for any $x \in \mathbb{H}_m$.

 \begin{st} \label{PropUnivCharMap}
     The universal characteristic mapping $\chi_m$ is well-defined;  the substitution
of Eq.~(\ref{e-qps})
transforms it into the characteristic mapping $\chi_{m,N}$.
 \end{st}
 \begin{pf} In the case $N > m$, the elements $p_1,\dots,p_m$ of the algebra $\BM(N)$ are algebraically independent. We deduce that the characteristic mapping $\chi_{m,N}$ defines a linear mapping $\mathbb{H}_m \rightarrow \mathbb{C}(q)[p_1,p_2,\dots, p_m] \hookrightarrow \mathbb{C}(q)[p_1,p_2,\dots]$. We check that this mapping satisfies all the properties of Definition \ref{UnivCharMapDef}, which implies the existence of a universal characteristic mapping.

     Let us use several standard facts about the Reflection Equation algebra (see \cite{GPS}). The cyclic property of the $R$-trace and the relations in the algebra $\BM(N)$ imply the equality   
     $$\langle  M_{\overline{1}} \dots M_{\overline{m}}\rho (x)R_{i,i+1}\rangle_{1,m} = \langle  M_{\overline{1}} \dots M_{\overline{m}}R_{i,i+1} \rho (x)\rangle_{1, m}, \quad  1 \leq i \leq m-1.$$ 
     This is equivalent to property~\ref{UCMpm} of the definition of the universal characteristic map. 
Property~\ref{UCMpb} of the definition coincides with the definition of the element $p_m$. Property~\ref{UCMpe} follows from the formula 
     \begin{eqnarray*}
         & & \langle M_{\overline{1}} \dots M_{\overline{m}}\rho(x) f(R_{k,k+1},R_{k+1,k+2},\dots, R_{m-1,m})\rangle_{1, m} = \\ &=&  \langle M_{\overline{1}} \dots M_{\overline{k-1}}\rho(x)\rangle_{1,k-1} \times\langle M_{\overline{1}} \dots M_{\overline{m-k+1}}f(R_{1,2},R_{2,3},\dots, R_{m-k+1,m-k+2})\rangle_{1,m-k+1},\end{eqnarray*} where $1 \leq k \leq m$, $x \in \mathbb{H}_{k-1}$,
         which is valid  for any noncommutative polynomial $ f(z_{1},z_{2},\dots, z_{m-k+1})$. \hfill\rule{6.5pt}{6.5pt}
 \end{pf}     

\begin{st}[Universal property of the characteristic mapping] \label{UnivPropCharMap2}
     The universal characteristic mapping is the unique sequence of mappings from Hecke algebras $\mathbb{H}_m$, $m=1,2,\dots$, 
     to the ring of polynomials in infinitely many variables $\mathbb{C}(q)[p_1,p_2,\dots]$ such that for any $x \in \mathbb{H}_m$
      and any specific value of $N$, the polynomial $\chi_m(x)$ coincides with the element $\chi_{m,N}(x)$ after substitution of Eq.~(\ref{e-qps}).
\end{st}
\begin{pf}
             Define the homomorphism $f: \mathbb{C}(q)[p_1,p_2,\dots] \rightarrow Z\BM(N)$ from the ring of polynomials to the center of the Reflection Equation algebra by Eq.~(\ref{e-qps}). The sequences of maps $f \circ \chi_{m}$ and $\chi_{m,N}$ satisfy the assumptions of Lemma \ref{UsefulLemma} and coincide on elements of the form $C_{m_1k_1} \dots C_{m_lk_l}$, where $m_1 < k_1 < m_2 < k_2 < \dots <m_l < k_l$, and therefore, by the lemma, they coincide everywhere.  Therefore, the universal characteristic mapping satisfies the universal property.

             Conversely, if some mapping satisfies the universal property, then it coincides with the mapping $\chi_{m,N}$ for $N>m$, and hence with the mapping $\chi_m$.\hfill\rule{6.5pt}{6.5pt}
\end{pf}

 A simple calculation shows that the matrix $L = \frac{1-M}{q-q^{-1}}$ satisfies the \emph{modified Reflection Equation} \cite{GS}:
\begin{equation} \label{MREsecond}
    R_1L_1R_1L_1 -L_1R_1L_1R_1 = R_1 L_1 - L_1 R_1 .
\end{equation}
\begin{defn}{\normalfont \cite{GS} }\label{d-qws}
    The \emph{ quantum ${\frak{gl}}(N)$-weight system} 
    $\omega_{m,N}:\BH_m\to Z\BM(N)$
    is defined by the formula $$\omega_{m,N}(x) = \langle  L_{\overline{1}} \dots L_{\overline{m}}\rho (x)\rangle_{1,m}, \quad  x \in \mathbb{H}_m.$$
\end{defn}
The value of the quantum ${\frak{gl}}_{N}$-weight system can be written as a polynomial in the quantum Casimir elements. The \emph{quantum Casimir elements}
 are a direct generalization of the classical ones, 
 and are defined by
 $$C_m = \omega_{m,N}(C_{1m}).$$
They lie in the center $Z\BM(N)$ of the Reflection Equation algebra $\BM(N)$ and, therefore, the value $\omega_{m,N}(x)$ of the quantum ${\gl(N)}$-weight system is a central element of the algebra $\BM(N)$ for any $x \in \mathbb{H}_m$.
\begin{st} \label{PropUnivWeightMap}
    The universal quantum ${\frak{gl}}$-weight system 
    $\omega_m:\BH_m\to\BC(q)[q^{-N};C_1,C_2,\dots]$ is well defined and coincides with the quantum ${\gl(N)}$-weight system under the substitution of specific $N$ and the corresponding Casimir elements.
\end{st}
\begin{pf}
Let us check the defining relations of the definition of the universal ${\frak{gl}}$-weight system for the quantum ${\gl(N)}$-weight system.

    The recurrence relation for the quantum ${\frak{gl}}(N)$-weight system (property~\ref{UQWpe}) follows from the cyclic property of the trace and the following relation in the Reflection Equation algebra
    $$L_{\overline{1}}\dots L_{\overline{m}}R_i - R_i L_{\overline{1}}\dots L_{\overline{m}} = L_{\overline{1}}\dots L_{\overline{i}}L_{\overline{i+2}}\dots L_{\overline{m}} - L_{\overline{1}}\dots L_{\overline{i-1}}L_{\overline{i+1}}\dots L_{\overline{m}}.$$
    Properties~ \ref{UQWpm} and~ \ref{UQWpb} of the definition follow from the equality
         \begin{eqnarray*}
         & & \langle L_{\overline{1}} \dots L_{\overline{m}}\rho(x) f(R_{k,k+1},R_{k+1,k+2},\dots, R_{m-1,m})\rangle_{1,m} = \\ &=&  \langle L_{\overline{1}} \dots L_{\overline{k-1}}\rho(x)\rangle_{1,k-1}
          \times\langle L_{\overline{1}} \dots L_{\overline{m-k+1}}f(R_{1,2},R_{2,3},\dots, R_{m-k+1,m-k+2})\rangle_{1,m-k+1},\end{eqnarray*}
          where $1 \leq k \leq m$, $x \in \mathbb{H}_{k-1}$,
          which is valid for any polynomial $ f(z_{1},z_{2},\dots, z_{m-k+1})$
          in  noncommuting variables. 

       For $N>m$, the quantum Casimir elements $C_1,\dots, C_m$ are algebraically independent. Consequently, the quantum $\frak{gl}(N)$-weight system defines a mapping $$\chi_{m,N}:\mathbb{H}_{m} \rightarrow \mathbb{C}(q)[C_1,C_2,\dots, C_m] .$$ 
        By Remark 1 after Lemma \ref{UsefulLemma}, we can express the value of the resulting mapping in terms of quantum Casimir elements using only conjugations and traces in the Hecke algebra. The resulting expressions depend polynomially on the parameter $q^{-N}$. 
        For each element $x \in \mathbb{H}_m$, we fix such an expression $\omega_m(x)$. Thus, we have obtained a mapping $\omega_{m}:\mathbb{H}_m \rightarrow \mathbb{C}(q)[q^{-N}][C_1,C_2,\dots, C_m]$, $ x\mapsto \omega_m(x)$. This mapping may not satisfy the definition of a quantum weight system and may even be non-linear. However, substitution of a given~$N$, $N>m$, transforms $\omega_{m}$ into the mapping $\omega_{m,N}:\mathbb{H}_{m}  \rightarrow \mathbb{C}(q)[C_1,C_2,\dots,C_m]$, which satisfies the definition of a quantum weight system.

        Let us check that the sequence of mappings $\omega_{m}$
        constructed above is a quantum weight system in the sense of Definition \ref{UnivWeightSystemDef}.
        For each element $x \in \mathbb{H}_m$, we choose a set of polynomials $P(x,f) \in \mathbb{C}(q)[q^{-N}]$. The polynomial $P(x,f)$ is the coefficient of the monomial $f = f(C_1,\dots,C_n)$ in the polynomial $\omega_m(x)$. 

        Each of the defining relations~ \ref{UQWpm}-- \ref{UQWpe} of Definition \ref{UnivWeightSystemDef} imposes some polynomial conditions on the polynomials $P(x,f)$:
        \begin{itemize}
           \item The linearity of the constructed mapping is equivalent to the property $P(\alpha x+\beta y,f) - \alpha P( x,f) -\beta P(y,f)=0$, for all $x,y \in \mathbb{H}_{n}(q)$, $\alpha,\beta \in \mathbb{C}(q)$.
            \item  Relation~\ref{UQWpm} is equivalent to the property $$\sum\limits_{gh=f}P(x,g)P(y,h) - P(\mathbf{m}(x,y),f)=0,$$
             for all 
             $$x \in \mathbb{H}_{k}, \quad y \in \mathbb{H}_{m-k},\quad 1 \leq k \leq m-1.$$ 
             Note that there are only finitely many pairs of monomials $g$ and $h$ such that $gh=f$. 
            \item Relation~\ref{UQWpb} is equivalent to the property $P(C_{1m},C_m) - 1=0$.
            \item  Relation~\ref{UQWpe} is equivalent to the property 
            \begin{align*}            	
            P(g_ix,f) & - P(xg_i,f)- P(\BT r_{m}(g_{m-1}^{-1} \dots g_{i+1}^{-1} x g_{i+1} \dots g_{m-1}),f)\\
            & + P(\BT r_{m}(g_{m-1}^{-1} \dots g_{i}^{-1} x g_{i} \dots g_{m-1}),f)=0,\end{align*}
        for any $x \in \mathbb{H}_{m}$ and $1 \leq i \leq m-1$.
        \end{itemize}

        For given elements of the Hecke algebra and a given monomial $f$, we denote by $P(x)$ the polynomial in one variable on the left-hand side of any of the identities.
        We know that $P(q^{-N})=0$ for all $N>m$, which means that the corresponding polynomial~$P$ is identically equal to zero. This means that the constructed mapping satisfies the definition of the universal quantum ${\frak{gl}}$-weight system.

         The proof of the fact that the universal quantum ${\frak{gl}}$-weight system after substitution of the Casimir elements coincides with the quantum ${\gl(N)}$-weight system completely repeats the proof of Proposition \ref{UnivPropCharMap2}.
 \hfill\rule{6.5pt}{6.5pt}

\end{pf}
\begin{cor}[Universal property of the quantum $\frak{gl}$-weight system]\label{CorUnivProp} 
 The universal quantum $\frak{gl}$-weight system is the unique sequence of mappings from Hecke algebras $\mathbb{H}_m$, $m=1,2,\dots$, 
 to the ring of polynomials in infinitely many variables $\mathbb{C}(q)[q^{-N}][C_1,C_2,\dots]$ such that for any $x \in \mathbb{H}_m$ and any particular $N$ the polynomial $\omega_{m}(x)$ coincides with the element $\omega_{m,N}(x)$ after substituting the corresponding value of $q^{-N}$ and the 
 corresponding quantum Casimir elements $C_i$.
\end{cor}
%\begin{rem}
%    The statement can be strengthened by requiring that the condition be satisfied for any Hecke $R$-matrix of $GL(N)$-type for which the notion of $R$-trace is defined.
%\end{rem}
\begin{pf}
%    Note that the calculations in the proof of Proposition \ref{PropUnivWeightMap} do not depend on the choice of a Hecke $R$-matrix. Therefore, conditions 1-4 of the universal $\frak{gl}$-weight system definition are satisfied in any Reflection Equation algebra of the $GL(N)$-type. This remark allows us to use the lemma \ref{UsefulLemma} as in the proof of Proposition \ref{UnivPropCharMap2}.

    It remains to verify the uniqueness of the mapping that satisfies the universal property. Let $\omega_m$, $m=1,2,\dots$, be any sequence
    of mappings satisfying assumptions of Definition~\ref{UnivWeightSystemDef}. As we have already noted, the quantum ${\gl(N)}$-weight system 
     determines a mapping $\mathbb{H}_{m} \rightarrow \mathbb{C}(q)[C_1,C_2,\dots, C_m] \hookrightarrow \mathbb{C}(q)[C_1,C_2,\dots]$ which coincides with the result of substituting a specific value of $N$ to the mapping $\omega_m$. Therefore, the polynomials $P(x,f)$ defined in the proof of Theorem \ref{PropUnivWeightMap} coincide with the corresponding coefficients of the polynomial $\omega_m(x)$ at infinitely many points. We conclude that the mappings $\omega_m$ coincide with the quantum weight system defined in the proof of Theorem \ref{PropUnivWeightMap}.\textbf{}\hfill\rule{6.5pt}{6.5pt}
\end{pf}

The corollary shows that all algebraic relations for the universal quantum $\frak{gl}$-weight system can be verified for the quantum $\frak{gl}(N)$-weight system in the Reflection Equation algebra. We see that 
the invariants $\chi_{m,N}$ and $\omega_{m,N}$ take values in the same ring, 
namely, the center $Z\BM(N)$ of the algebra $\BM(N)$. For generators of this ring we can use either elements $p_i$, $i=1,2,\dots$ or elements $C_i$, $i=1,2,\dots$. The connection between these generators is described by the following 
quantum analogue of the Harish-Chandra isomorphism and the Perelomov--Popov formula for this isomorphism.

The {\it Harish-Chandra isomorphism} for the Reflection Equation algebra is defined on the quantum power sums $p_n$  by the formula
\begin{equation} \label{HarishChandra}
    1+(q-q^{-1})\sum_{m=1}^{\infty}p_m v^m = \prod\limits_{i = 1}^{N} \frac{1 - q^{-2} \xi_i  v}{1 - \xi_i v}.
\end{equation}
In the variables $x_i=\frac{q^{1-N}-\xi_i}{q^2-1}$, the generating function of the Casimir elements $C_n$ has the form  
\begin{equation} \label{PerelomovPopov}1 - [N]_qv-(v-1+q^{-2})\sum_{m=1}^{\infty}q^{m+1}C_mv^{m} = \prod_{i=1}^N \frac{1-(x_i+[\frac{N+1}{2}]_q)v}{1-(q^2x_i+[\frac{N-1}{2}]_q)v}.\end{equation}
\begin{rem}
    Here we have identified the ranges of the classical and quantum weight systems. They take values in the ring of symmetric polynomials in variables $x_i$. Thus, the limit of the quantum weight system value as $q\rightarrow 1$ can be taken coefficient-wise.

    We consider all invariants over the ring $\mathbb{C}(q)[q^{-N},N]$, where $q$, $N$ and $q^{-N}$ are independent variables. If we want to pass to the limit, we should consider $q^{-N}$ as a power series in the neighborhood of $q= 1$ with coefficients that depend polynomially on $N$.
\end{rem}

% \begin{rem}
%     The invariant $h$ is the multiplicative analogue of the invariant $\omega$. The variables $\xi$ play the same role with respect to the variables $x$.
% \end{rem}



\begin{st} \label{PropWeightCharConnection}
    The value of the quantum weight system $\omega_{m,N}(x)$ on an element $x\in \mathbb{H}_m$ is expressed through the values of the characteristic mapping $\chi_{m,N}$ according to the formula
$$\omega_{m,N}(x) =\frac{1}{(q-q^{-1})^m} \sum\limits_{k=0}^{m} \left(\sum\limits_{1 \leq i_1 < i_2 < \dots <i_k \leq m} (-1)^{k}\chi_{k,N}(\tilde{x}_{i_1 i_2 \dots i_k})\right), \quad  x \in \mathbb{H}_m, $$
where the sum is taken over all directed subsets $1 \leq i_1 < i_2 < \dots <i_k \leq m$ of the set $\{1,\dots,m\}$. Denote 
the monomial $C_{1i_1}C_{2i_2}\dots C_{ki_k}$ by $r_{i_1 i_2 \dots i_k}$, for the set of indexes $ 1 \leq i_1 < i_2 < \dots <i_k \leq m$. The element $\tilde{x}_{i_1 i_2 \dots i_k} \in \mathbb{H}_{k}$ is obtained from $x$ using the formula $$\tilde{x}_{i_1 i_2 \dots i_k} = \langle r_{i_1 i_2 \dots i_k}^{-1}\,x \,r_{i_1 i_2 \dots i_k} \rangle_{i+1,m}.$$
\end{st}
\begin{pf}
We obviously have \begin{eqnarray*}
    \omega_{m,N}(x) = \langle L_{\overline{1}} \dots L_{\overline{m}} \rho(x)\rangle_{1,m} = \frac{1}{(q-q^{-1})^m}\langle (1-M_{\overline{1}}) \dots (1-M_{\overline{m}}) \rho(x)\rangle_{1,m} = \\ = \frac{1}{(q-q^{-1})^m}\sum\limits_{k=0}^{m} \left(\sum\limits_{1 \leq i_1 < i_2 < \dots <i_k \leq m} (-1)^{k}\langle M_{\overline{i_1}} \dots M_{\overline{i_k}} \rho(x)\rangle_{1,m}\right).
\end{eqnarray*}
    Note that $M_{\overline{k}} = R_{k-1,k}R_{k-2,k-1}\dots R_{l,l+1} M_{\overline{l}} (R_{k-1,k}R_{k-2,k-1}\dots R_{l,l+1})^{-1}$ for $l < k$.  Thus, we have $$M_{\overline{i_1}} \dots M_{\overline{i_k}} = \rho(C_{1i_1})M_{\overline{1}}\rho(C_{1i_1})^{-1}M_{\overline{i_2}} \dots M_{\overline{i_k}} = \rho(C_{1i_1})M_{\overline{1}}M_{\overline{i_2}} \dots M_{\overline{i_k}}\rho(C_{1i_1})^{-1},$$
    here we have used the mutual commutativity of $\rho(C_{ij})$ and $M_{\overline{k}}$ for $i,j<k$ or $i,j > k$. Repeating this procedure for all $M_{\overline{i_l}}$, we obtain
    $$M_{\overline{i_1}} \dots M_{\overline{i_k}} = \rho(r_{i_1 i_2  \dots i_k}) M_{\overline{1}} \dots M_{\overline{k}} \rho(r_{i_1 i_2  \dots i_k}^{-1}).$$ Application of the cyclic property of the $R$-trace to this formula proves the result.  \hfill\rule{6.5pt}{6.5pt}
\end{pf}
The formula is simplified for central elements of the algebra $\mathbb{H}_m$.
\begin{cor} \label{CorWeightCharConnection}
    For any central element $x \in \mathbb{H}_m$, we have $$\omega_{m,N}(x) =\frac{1}{(q-q^{-1})^m} \sum\limits_{k=0}^{m} (-1)^{k}\binom{m}{k}\chi_{k,N}\langle x\rangle_{k+1,m}.$$
\end{cor}


\section{Average value of the $\frak{gl}$-weight system}~\label{sqglN}
The average value of the ${\frak{gl}}(N)$-weight system over all permutations 
in the group $\BS_m$ can be expressed as the image of the group algebra $\mathbb{C}(q)[\BS_m]$ idempotent,
\begin{eqnarray*}
W_{m}(N) 
 &=& \frac{1}{m!} \sum_{\alpha \in \BS_m}w_{{\gl(N)}}(\alpha)\\
 &=&\frac{1}{m!}\langle E_1 \dots E_m \sum_{\alpha \in \BS_m}P_{\alpha^{-1}}\rangle_{1,m}\\
  &=& \frac{1}{m!} \langle E_1 \dots E_m \sum_{\alpha \in \BS_m}P_{\alpha}\rangle_{1,m}.
\end{eqnarray*}

\begin{defn} The {\it symmetrizer} in~$\BC[\BS_m]$ is the element $\Bs_m=\frac{1}{ m!}\sum_{\alpha \in \BS_m}\alpha$, so that $W_m(N)= w_{\gl(N)}(\Bs_m)$.
%An idempotent $\frac{1}{n!}\sum\limits_{\alpha \in S_n}\alpha \in \mathbb{C}[S_n]$ is called a symmetrizer. Its matrix image is denoted by $S^{(n)} = \frac{1}{n!}\sum_{\alpha \in S_n}P_{\alpha}$.
\end{defn}
The symmetrizer is a central idempotent of the algebra $\mathbb{C}[\BS_m]$.
It can be defined recursively by
$$
\Bs_m=\frac1m\Bs_{m-1}(id_m+(m-1)\cdot(m-1,m))\Bs_{m-1},
$$
where $id_m\in\BS_m$ is the identity permutation and $(m-1,m)\in\BS_m$
is a transposition.
Hence, its matrix image $S^{(m)} = \frac{1}{ m!}\sum_{\alpha \in \BS_m}P_{\alpha}
\in End(\BC^N)^{\otimes m}$ also 
can be calculated recursively by the following rule
$$S^{(1)} =1, \quad S^{(m)} = \frac{1}{m} S^{(m-1)}(1+(m-1)P_{(m-1,m)})S^{(m-1)}, \quad m \geq 2.$$
The corresponding central idempotent $\Bh_m$ in the Hecke algebra $\BH_m$ is called the $q$-\emph{symmetrizer} and is constructed similarly: 
$$\Bh_1 =1, \quad \Bh_m = \frac{1}{[m]_q} \Bh_{m-1}(q^{2-2m}+q^{-1}[m-1]_q g_{m-1})\Bh_{m-1}, \quad m \geq 2.$$
Let $H^{(m)} = \rho(\Bh_m)$ denote the $R$-matrix image of the idempotent $\Bh_m$.
\begin{defn} {\it The average value of the quantum ${{\gl(N)}}$-weight system} is the element 
	$$\Omega_m(N) = \omega_{m,N}(\Bh_m) = \langle L_{\overline{1}} \dots L_{\overline{m}} H^{(m)}\rangle_{1, m}.$$
\end{defn}

\begin{thm}\label{LimitThm}
    The image of $W_{m}(N)$ under the Harish-Chandra homomorphism coincides with the image of $\Omega_{m}(N)$ in the limit $q \rightarrow 1$.
\end{thm}

Along with the average value $W_m(N)$ of the ${\mathfrak gl}(N)$-weight system
and its quantum analogue $\Omega_m(N)$, we introduce one more pair of elements
$\widehat W_m(N)\in ZU\gl(N)$ and $\widehat \Omega_m(N)\in Z\BM(N)$. %(see \cite{OK}, \cite{JLM}).
The elements $W_m(N),\widehat W_m(N),\Omega_m(N),\widehat \Omega_m(N)$ 
can be considered as symmetric polynomials
in the set of independent variables $x_1,\dots,x_N$. Now, we have
\begin{itemize}
	\item there are known explicit formulas for $\widehat W_m(N), \widehat \Omega_m(N)$, which
	imply, in particular, that 
	$$\widehat W_m(N)=\lim_{q\to1}\widehat \Omega_m(N);$$
	\item the two sequences of polynomials $\Omega_m(N)$, $\widehat \Omega_m(N)$, $m=1,2,\dots$,
	are related by a triangular invertible linear transformation.
	Each coefficient of the transformation has a limit as $q\to1$
	and the limit transformation (which is also linear and triangular) 
	relates the corresponding sequences of polynomials $W_m(N)$ and $\widehat W_m(N)$.
	\end{itemize} 

	By combining the two assertions above, we establish the assertion of 
	Theorem~\ref{MainThm}.

In more detail, we set %(Proposition 3.1 \cite{JLM})
$$\widehat \Omega_{m}(N)= \langle L_{\overline{1}} (L_{\overline{2}}-q^{-1}[1]_q) \dots (L_{\overline{n}}-q^{-1}[m-1]_q)H^{(m)}\rangle_{1, m}\in Z\BM(N).$$ 
%
 The image of this element under the Harish-Chandra isomorphism is equal to %(Theorem 3.2 \cite{JLM})
\begin{eqnarray}\nonumber
    \frac{1}{(q^2-1)^m}\sum\limits_{1 \leq i_1 \leq \dots \leq i_m \leq N} \prod\limits_{k=1}^{m}(q^{-2(\nu-i_k+k)}-\xi_{i_k}) = \\ =\sum\limits_{1 \leq i_1 \leq \dots \leq i_m \leq N} \prod\limits_{k=1}^{m}  \left(x_{i_k}-q^{-N-1}\left[\frac{\nu}{2}-i_k+k\right]_q\right). \label{QQImm}
\end{eqnarray}
The elements $\widehat \Omega_{m}(N)$ were introduced in \cite{JLM}. Here, we adopt the definition given in Proposition 3.1 of \cite{JLM}, and Eq.~(\ref{QQImm}) restates Theorem 3.2 therein.

Similarly, set %(formula (2.1) \cite{OK})
 $$\widehat W_m(N)= \langle E_1 (E_2-1)\dots (E_m-m+1)S^{(m)}\rangle_{1,m} \in U\gl(N).$$ 
 %
 The image of this element under the Harish-Chandra isomorphism is equal to %(formula (2.2) \cite{OK})
\begin{equation}\label{ClassImm}
    \sum\limits_{1 \leq i_1 \leq \dots \leq i_n \leq N} \prod\limits_{k=1}^{m}\left(x_{i_k}-\frac{N+1}{2}+i_k-k+1\right).
\end{equation}
The elements $\widehat W_m(N)$ are described in \cite{OK} (2.1)-(2.2).

    Passing to the limit $q\rightarrow1$ in Eq.~(\ref{QQImm}), we obtain Eq.~(\ref{ClassImm}). To prove Theorem \ref{LimitThm}, we need a couple of lemmas.
\begin{lemma}
    The following formulas hold
        \begin{equation}\label{TrH}       
    \langle H^{(m)}\rangle_{m,m} = q^{-1} \frac{[\nu+m]_q}{[m]_q} H^{(m-1)}, \quad 
    Tr_{m,m} (S^{(m)} )= \frac{\nu+m}{m} S^{(m-1)}.\end{equation}
    %
\end{lemma}
\begin{pf}
    Using the definition of the $q$-symmetrizer, we obtain $$\langle H^{(m)} \rangle_{m,m} = \frac{q^{1-m}}{[m]_q}H^{(m-1)} (q^{1-m}\langle \BI^{\otimes m} \rangle_{m,m} + q^{m-2}[m-1]_q \langle R_{m-1,m} \rangle_{m,m})H^{(m-1)}. $$
    Since $\langle \BI^{\otimes m} \rangle_{m,m} = q^{-1}[N]_q\BI^{\otimes m-1}$ and $\langle R_{m-1,m} \rangle_{m,m}= \BI^{\otimes m-1}$, it follows that $$\langle H^{(m)} \rangle_{m,m} = (H^{(m-1)})^2 \frac{q^{1-m}(1-q^{-2N})+q^{m-1}-q^{1-m}}{q^m - q^{-m}} = q^{-1}\frac{1-q^{-2(\nu+m)}}{1-q^{-2m}}H^{(m-1)}.$$
    In the last implication we used the fact that $\Bh_{m-1}$ is a Hecke algebra idempotent.
    Passing to the limit $q\rightarrow 1$, we obtain the relation in the classical case. \hfill\rule{6.5pt}{6.5pt}
    %
\end{pf}   

\begin{st} \label{PropImmanantWConnection}
    The elements $\widehat \Omega_m(N)$ admit the following expression in terms of $\Omega_m(N)$:
    \begin{equation} \label{qImm->WS}
        \widehat \Omega_m(N) = \sum\limits_{k=0}^m(-1)^k\frac{([\nu+m]_q)_k}{([m]_q)_k} e_k \Omega_{m-k}(N),
    \end{equation}
    where $e_k = q^{-k}\sum\limits_{1 \leq i_1<\dots < i_k \leq m}\prod\limits_{l=1}^{k}[i_l]_q$.
    A similar formula holds for the elements $\widehat W_m(N)$ and $W_m(N)$ in the algebra $U({\gl(N)})$:
     \begin{equation} \label{Imm->WS}
        \widehat W_m(N) = \sum\limits_{k=0}^m(-1)^k e_k \frac{(\nu+m)_k}{(m)_k} W_{m-k}(N),
    \end{equation}
    where $e_k = \sum\limits_{1 \leq i_1<\dots < i_k \leq m}\prod\limits_{l=1}^{k}i_l$.
    %
\end{st}
\begin{pf}
   As in Proposition~\ref{PropWeightCharConnection}, any set of matrices $L_{\overline{i_1}} \dots L_{\overline{i_k}}$ is conjugate to a set of matrices $L_{\overline{1}} \dots L_{\overline{k}}$, and, therefore, the cyclic property of the $R$-trace and centrality of $H^{(m)}$ imply the equality $$\langle L_{\overline{1}} (L_{\overline{2}}-q^{-1}[1]_q) \dots (L_{\overline{m}}-q^{-1}[m-1]_q)H^{(m)}\rangle_{1, m}=\sum\limits_{k=0}^{m} (-1)^k e_k\langle L_{\overline{1}} \dots L_{\overline{m-k}}H^{(m)}\rangle_{1, m}.$$
    Using Eq.~(\ref{TrH}), we obtain the required result.
    Calculation in the case of the algebra $U({\gl(N)})$ is completely analogous.\hfill\rule{6.5pt}{6.5pt}
\end{pf}
The coefficients in formula (\ref{Imm->WS}) are the limits of the corresponding coefficients in formula (\ref{qImm->WS}). This remark is the key in the proof of Theorem \ref{LimitThm}.

\noindent
\textbf{Proof of Theorem \ref{LimitThm}} The transition matrix from
the elements $\widehat \Omega_m(N)$ to $\Omega_m(N)$ is unitriangular, which means that the elements of the inverse matrix are polynomials with integer coefficients in the elements of the original matrix. Moreover, the limits of the elements of the transition matrix in the quantum case are the corresponding elements in the classical case. Rewriting the elements $\Omega_m(N)$ as linear combinations of $\widehat \Omega_m$'s, we deduce that the limits of $\Omega_m(N)$ are equal to $W_m(N)$.\hfill\rule{6.5pt}{6.5pt}





