\section{Calculation of the quantum and classical ${\frak{gl}}$-weight systems average values}~\label{sHgl}
In this section we will calculate the average value of the quantum ${\frak{gl}}$-weight system and its limit. For any fixed $N\geq 1$, the value of the averaged quantum ${\gl(N)}$-weight system is calculated by the formula 
 \begin{eqnarray}\nonumber
        \Omega_m(N) &=& \omega_{m,N}(\Bh_m) =\frac{m!}{ (\nu+m)!}\frac{[\nu+m]_q!}{[m]_q!} \sum_{l=0}^{n} (\nu+m)_l \times \\ &&\times\frac{1}{q^{2l} l!}\beta_{l}^{(\nu+m-l,\nu)}\left(\frac{\nu}{2}\right) S_{m-l}(x_1,\dots,x_N) .\label{AvgVal}
    \end{eqnarray}
    Recall that $\nu=N-1$ and $\beta_{m}^{(h,k)}(\xi)$ is the q-Bernoulli polynomial of order $k$,
       $$\beta_{m}^{(h,k)}(\xi) = \frac{1}{(1-q^{-2})^m} \sum\limits_{i=0}^{m}\binom{m}{i}(-q^{-2\xi})^i \frac{(i+h)_k}{( [i+h]_q)_k }.$$ 
    Here $\xi$ is a formal parameter which can be specialized at integer and half-integer points, $m \in \mathbb{Z}_{\geq 0}$, $h,k \in \mathbb{Z}_{\geq 1}$ and $h \geq k$.

The limit of the $q$-Bernoulli numbers $\beta_{m}^{(1,1)}= \beta_{m}^{(1,1)}(0)$ of order $1$ is well known and coincides with the classical Bernoulli numbers. The $q$-Bernoulli polynomial of order $k$ can be expressed in terms of $q$-Bernoulli numbers of order 1, which allows us to calculate the limit $$\lim\limits_{q\rightarrow 1}\beta_m^{(h,k)}(\xi)=B_m^{(k)}(\xi)$$
and prove that it does not depend on the value of $h$ and is given by the generating series
$$\sum_{m=0}^\infty B_m^{(k)}(\xi)\frac{t^m}{m!}=e^{\xi t}\left(\frac{e^t-1}{t}\right)^{-k},$$
see Proposition~\ref{BkmLimit} below.

We conclude that all the summands in the right hand side of  Eq.~(\ref{AvgVal}) have limits as $q\to 1$ and the limit values satisfy the relation
$$W_m(N)=w_{\frak{gl}(N)}(\Bs_m)=\sum_{l=0}^m \frac{(\nu)_l}{l!}
B_l^{(\nu)}\left(\frac{\nu}{2}\right)S_{m-l}(x_1,\dots,x_N).
$$
Collecting these equalities for all $n$ in a generating series, we obtain the required relation of Theorem \ref{MainThm} for the ${\gl(N)}$-weight system. 

Proposition \ref{ClassUnivProp} and Corollary \ref{CorUnivProp} show that if a polynomial relation holds for all ${\gl(N)}$-weight systems, then it also holds for the universal ${\frak{gl}}$-weight system, so that we obtain expressions (\ref{AlmostMain}) and (\ref{MainMain}) for the classical and quantum universal ${\frak{gl}}$-weight systems, respectively. 

\subsection{Computation of the average value of the quantum $\gl(N)$-weight system}

In this section, we will prove that the average value of the quantum ${\gl(N)}$-weight system is given by Eq.~(\ref{AvgVal}).
We start with a formula from~\cite{GPS} for the mean value of the quantum 
character.

\begin{st}[\cite{GPS}] \label{REAcenter} In the Reflection Equation algebra, the following relation holds
    $$\chi_m(\Bh_m)=\langle M_{\overline{1}} \dots M_{\overline{m}}H^{(m)}\rangle_{1, m}  = q^{-m}S_{m}(\xi_1,\dots,\xi_N) = q^{-m} \sum\limits_{1 \leq i_1 \leq\dots \leq i_m \leq N}\xi_{i_1}\dots\xi_{i_m}.$$


\end{st}
%In this formula, we have identified a central element 
%of the Reflection Equation algebra
%with its image under the Harish-Chandra isomorphism. 

\begin{st}
    In terms of the $\xi$  variables, the value of the quantum 
    ${\frak{gl}}$-weight system on the $q$-symmetrizer is as follows
        \begin{equation}\label{Quant}
        \omega_{m,N}(\Bh_m) = \Omega_m(N) = \frac{1}{(q^2-1)^m}\sum\limits_{k=0}^{m}(-1)^k  \binom{m}{k}\frac{([\nu+m+l]_q)_{m-k}}{([m+l]_q)_{m-k}}S_k(\xi_1,\dots,\xi_N).
    \end{equation}
\end{st}
\begin{pf} Combining Corollary \ref{CorWeightCharConnection} and formula (\ref{TrH}) we obtain
$$ \Omega_m(N) = \frac{1}{(q^2-1)^m}\sum\limits_{k=0}^{m}(-1)^k  \binom{m}{k}\frac{([\nu+m+l]_q)_{m-k}}{([m+l]_q)_{m-k}}\chi_{k,N}(\Bh_k).$$
It remains to apply Proposition \ref{REAcenter} to the obtained expression.
\hfill\rule{6.5pt}{6.5pt}
    %We used the same calculation as in the proof of Proposition \ref{PropImmanantWConnection}. Here, $L_{\overline{k}} = \frac{1-M_{\overline{k}}}{q-q^{-1}}$ and $e_k$ are replaced by $\binom{n}{k}$.\hfill\rule{6.5pt}{6.5pt}
\end{pf}

\begin{st}
    The one-part Schur polynomials have the property 
    \begin{equation}\label{Class}
        S_m(\xi_1,\dots,\xi_N)= \sum\limits_{k=0}^{m}(-1)^k \binom{\nu+m}{m-k} S_k(u - \xi_1,\dots,u - \xi_N)u^{m-k}.
    \end{equation}
\end{st}
% \begin{pf}
%     Let $X = diag(u-\xi_1, \dots,u-\xi_N)$ be a matrix of commutative variables. Note that $$s_n(u-\xi_1,\dots,u-\xi_N)= Tr_{(1\dots n)}(X_1 \dots X_n S^{(n)}).$$ A simple calculation with the expression $$s_n(\xi_1,\dots,\xi_N) = Tr_{(1\dots n)}((u-X_1) \dots (u-X_n ) S^{(n)})$$
%  shows that $$s_n(\xi_1,\dots,\xi_N) =\sum\limits_{k=0}^{n}u^{n-k}(-1)^{k}\binom{n}{k}Tr_{(1\dots n)}(X_1 \dots X_k S^{(n)}).$$
%  If we combine this with with formula (\ref{TrH}), we get formula (\ref{Class}).\hfill\rule{6.5pt}{6.5pt}
% \end{pf}
\begin{pf} This results from the following simple calculation with generating series:
    \begin{eqnarray*}
\sum_{m=0}^\infty S_m(\xi_1,\dots,\xi_N)t^m&=&\prod_{i=1}^N\frac{1}{1-\xi_i t}=\prod_{i=1}^N\frac{1}{1-ut+(u-\xi_i) t}
\\
&=&(1-u t)^{-N}\prod_{i=1}^N\frac1{1+(u-\xi_i) \frac{t}{1-u t}}\\
&=&
 (1-u t)^{-N}\sum_{m=0}^\infty S_m(u-\xi_1,\dots,u-\xi_N)\left(\frac{-t}{1-u t}\right)^m.
     \end{eqnarray*}
     Expanding $ (1-u t)^{-N}\left(\frac{-t}{1-u t}\right)^m$ into a power series in~$t$, we obtain the desired formula.\hfill\rule{6.5pt}{6.5pt}
\end{pf}
\begin{cor} \label{CorWFormula}
    Equation~(\ref{AvgVal}) is valid.

\end{cor}
\begin{pf} The coefficient of $S_{l}$ in the expansion of $\Omega_{n}(N)$ is the sum of the expressions
    %The coefficient of $s_{l}$ is the sum of the products of the coefficients from the expansions of $s_{k}$, $k\geq l$ by the formula (\ref{Class}) and the coefficients of $s_{k}$ in the formula (\ref{Quant}), that is, the sum of the following expressions
    $$(-u)^{k-l}\frac{1}{(q^2-1)^{m-l}}\frac{m!}{l!(k-l)!(m-k)!} \times \frac{([\nu+m]_q)_k (\nu+k)_{k-l}}{([m]_q)_{m-k} (k)_{k-l}}.$$
    This expression is obtained by substituting Eq.~(\ref{Class}) into 
    Eq.~(\ref{Quant}).
    After dividing the coefficient by $\frac{m!}{[m]_q!}\frac{[\nu+m]_q!}{(\nu+m)!} \frac{(\nu+m)_l}{(m-l)!}$, we get
        $$(-u)^k\frac{1}{(q^2-1)^{m-l}}\frac{[k]_q!}{[\nu+k]_q!} \frac{(\nu+k)!}{k!} \frac{(m-l)!}{(m-k)!(k-l)!}.$$
        The sum of these expressions for $k = l,l+1,l+2,\dots, m$ coincides with the $q$-Bernoulli polynomial. Note that by the definition of the variables $x_i$ we need to choose $u=q^{-\nu} = q^{-2\cdot\frac{\nu}{2}}$. \hfill\rule{6.5pt}{6.5pt}
\end{pf} 

\subsection{The limit of the $q$-Bernoulli polynomials}

%In this part of the section we will focus on calculating the limit of $q$-Bernoulli polynomials as $q \rightarrow 1$. Denote the $m$~th $q$-Bernoulli number of order $k$ by $\beta_{m}^{(h,k)} = \beta_{m}^{(h,k)}(0)$.

This section is devoted to a proof of the following result.

\begin{st} \label{BkmLimit}
	The $q$-Bernoulli polynomial $\beta_m^{(h,k)}(\xi)$
	has a limit as $q\to1$. This limit
	$$
	B_m^{(k)}(\xi)=\lim_{q\to1}\beta_m^{(h,k)}(\xi)
	$$
is independent of~$h$ and coincides with the classical Bernoulli polynomial,
whose sequence is defined by the generating series
$$
\sum_{m=0}^\infty B_m^{(k)}(\xi)\frac{t^m}{m!}=e^{\xi t}\left(\frac{e^t-1}{t}\right)^{-k}.
$$ 
\end{st}	

The proof is based on the following recursions for the 
$q$-Bernoulli polynomials. Denote by $\beta_m^{(h,k)}=\beta_m^{(h,k)}(0)$,
the corresponding $m$~th $q$-Bernoulli number.

\begin{lemma} \label{recurrence}
	We have 
\begin{eqnarray}\label{Polynomial->Number}
\beta_m^{(h,k)}(\xi)&=&\sum_{i=0}^m {m\choose i} \beta_{m-i}^{(h+i,k)}
([\xi]_q)^i;\\ \label{k->1}
\beta_m^{(h,k)}&=&\sum_{i_1+\dots+i_k=m} {m\choose i_1,\dots,i_k}
\prod_{j=1}^k \beta_{i_j}^{(h-j+1+i_1+\dots+i_{j-1},1)};\\ \label{h->1}
\beta_m^{(h+1,1)}&=& \beta_{m}^{(h,1)}-(1-q^{-2})\beta_{m+1}^{(h,1)}.
\end{eqnarray}

\end{lemma}	

The first relation expresses the $q$-Bernoulli polynomials in terms of
$q$-Bernoulli numbers. The second one reduces computation of
$q$-Bernoulli numbers to the case $k=1$, and reduces the latter to the
case $h=1$. Thus, all these relations together express $q$-Bernoulli 
polynomials in terms of the numbers $\beta_{m}^{(1,1)}$.

The relations of the last Lemma have classical analogues.
Namely, denoting $B_m^{(k)}=B_m^{(k)}(0)$, $k=0,1,2,\dots$, we have
\begin{eqnarray} \label{ClassPol->Number}
B_m^{(k)}(\xi)=\sum_{i=0}^m{m\choose i} B_{m-i}^{(k)}\xi^i; \\ \label{Clask->1}
B_m^{(k)}=\sum_{i_1+\dots+i_k=m}{m\choose i_1,i_2,\dots,i_k}
\prod_{j=1}^k B_{i_j}^{(1)}.
\end{eqnarray}
The coefficients in these relations are obtained by taking the limit $q\to1$.
Finally, we use the following result:

\begin{st}[\cite{C}] \label{b11Limit}
   For any $m>0$ the limit as $q \rightarrow 1$ of the $q$-Bernoulli number $\beta_{m}^{(1,1)}$ of order $1$  exists and is equal to the classical Bernoulli number $B_m^{(1)}(0)$.
\end{st}

Applying this Proposition and induction we obtain, step by step, 
the following equations:
$$
\lim_{q\to1} \beta_m^{(h,1)}=B_m^{(1)};
$$
$$
\lim_{q\to1} \beta_m^{(h,k)}=B_m^{(k)};
$$
$$
\lim_{q\to1} \beta_m^{(h,k)}(\xi)=B_m^{(k)}(\xi).
$$

Thus, it remains to prove Lemma \ref{recurrence} to complete the proof of Proposition \ref{BkmLimit}.

Let $q^{-N}$ be a formal variable. Define the linear operator $\Phi_y:  \mathbb{C}(q)[q^{-2y}] \rightarrow \mathbb{C}(q)$ by the formula
$$\Phi_y(q^{-2ay}) = \frac{a+1}{[a+1]_q}, \quad a \in \mathbb{Z}_{\geq 0}.$$
% , \quad \Phi_y(q^{2y})=\frac{0}{[0]_q}=0
This operator is a model of the {\it $p$-adic $q$-Volkenborn integral} (see \cite{KCR} and references therein). 
\begin{st} \label{PropIntegralFormula}
    The $q$-Bernoulli polynomial admits the following description in
    terms of the operator $\Phi_y$:
         \begin{equation} \label{Bernoulli}
             \beta_{m}^{(h,k)}(\xi) = \Phi_{y_1}\dots\Phi_{y_k} \left( q^{-2\sum\limits_{i=1}^k(h-i)y_i}([\xi+y_1+\dots+y_k]_q)^m\right).
        \end{equation}
\end{st}
\begin{pf} A simple calculation shows that
     \begin{eqnarray*}
        q^{-2\sum\limits_{j=1}^k(h-j)y_j}([\xi+y_1+\dots+y_k]_q)^m= \frac{q^{-2\sum\limits_{j=1}^k(h-j)y_j}}{(1-q^{-2})^m}(1 - q^{-2(\xi+y_1+\dots+y_k)})_q^m = \\ = \frac{1}{(1-q^{-2})^m}\sum_{i=0}^{m}\binom{m}{i}(-q^{-2\xi})^i  \prod_{j=1}^{k}q^{-2(h-j+i)y_j}. 
    \end{eqnarray*}
    The operators $\Phi_{y_i}$ can be applied independently to each factor $q^{-2(h-j+i)y_j}$, hence applying the operator $ \Phi_{y_1}\dots\Phi_{y_k}$ to the last part of the formula, we obtain a $q$-Bernoulli polynomial. \hfill\rule{6.5pt}{6.5pt}
\end{pf}
We now use formula (\ref{Bernoulli}) to prove Lemma \ref{recurrence}.
\paragraph{Proof of formula (\ref{Polynomial->Number}).}
Note that $[\xi + y]_q = [\xi]_qq^{-2y}+[y]_q$, using this we can calculate
\begin{eqnarray*} 
\beta_{m}^{(h,k)}(\xi) &=& \Phi_{y_1}\dots\Phi_{y_k} \left( q^{-2\sum\limits_{i=1}^k(h-i)y_i}\left(\left[\xi+\sum\limits_{i=1}^ky_i\right]_q\right)^m\right) \\&=& \Phi_{y_1}\dots\Phi_{y_k} \left( q^{-2\sum\limits_{i=1}^k(h-i)y_i}\left( q^{-2\sum\limits_{i=1}^ky_i}[\xi]_q+\left[\sum\limits_{i=1}^ky_i\right]_q\right)^{\Large m} \,\right)  \\&=&\sum\limits_{j=0}^{m}([\xi]_q)^{j}\binom{m}{j}\Phi_{y_1}\dots\Phi_{y_k} \left(q^{-2\sum\limits_{i=1}^k(h-i+j)y_i}\left(\left[\sum\limits_{i=1}^ky_i\right]_q\right)^{m-j} \right)\\ &=& \sum\limits_{j=0}^{m}\binom{m}{j}([\xi]_q)^{j}\beta_{m-j}^{(h+j,k)}.
\end{eqnarray*}
    %\hfill\rule{6.5pt}{6.5pt}
\paragraph{Proof of formula (\ref{k->1}).} Note that $[x+y]_q = [x]_qq^{-2y} + [y]_q$. Moreover, a simple induction on $k$ shows that $\left[\sum\limits_{j=1}^ky_j\right]_q = \sum\limits_{j=1}^k[y_j]_q q^{-2\sum\limits_{i<j}y_i} $. Therefore,
    $$\left(\left[\sum\limits_{j=1}^ky_j\right]_q\right)^m = \left(\sum\limits_{j=1}^k[y_j]_q q^{-2\sum\limits_{i<j}y_i}\right)^m = \sum\limits_{i_1+\dots+i_k = m} \binom{m}{i_1,i_2,\dots,i_k} \prod\limits_{j=1}^{k}([y_{j}]_q)^{i_j}q^{-2\sum\limits_{i<j}i_jy_j}.$$
    To obtain the result, it remains to use linearity of the operators $\Phi_y$ and the following formula $$\Phi_{y_1}\dots\Phi_{y_k}\left(q^{-2\sum\limits_{j=1}^k(h-j)y_j}\prod\limits_{j=1}^{k}([y_{j}]_q)^{i_j}q^{-2\sum\limits_{i<j}i_jy_j} \right)= \prod\limits_{j=1}^{k}\Phi_{y_1}(([y_{j}]_q)^{i_j} q^{-2 (h-j+i_1+\dots+i_{j-1})y_i}).$$
%\hfill\rule{6.5pt}{6.5pt}


\paragraph{Proof of formula (\ref{h->1}).} 
   We have
    \begin{eqnarray*}
        \beta_{m}^{(h,1)}-(1-q^{-2})\beta_{m+1}^{(h,1)} = \Phi_y(q^{-2(h-1)y}([y]_q)^m-q^{-2(h-1)y}(1-q^{-2})([y]_q)^{m+1}) =\\= \Phi_y(q^{-2(h-1)y}([y]_q)^m (1-(1-q^{-2y}))) = \Phi_y(q^{-2hy}([y]_q)^m) = \beta_{m}^{(h+1,1)}.
    \end{eqnarray*} 
    %\hfill\rule{6.5pt}{6.5pt}

\paragraph{Proof of formulas (\ref{Clask->1}) and (\ref{ClassPol->Number}).}
    Using the obvious equality $$\sum_{m=0}^\infty B_m^{(k)}(0)\frac{t^m}{m!} = \left(\sum_{m=0}^\infty B_m^{(1)}(0)\frac{t^m}{m!}\right)^k.$$ we obtain formula (\ref{Clask->1}) for classical Bernoulli numbers. 

Formula (\ref{ClassPol->Number}) can be obtained directly from the following relation $\sum_{m=0}^\infty B_m^{(k)}(\xi)\frac{t^m}{m!}=e^{\xi t}\sum_{m=0}^\infty B_m^{(k)}(0)\frac{t^m}{m!}.$\hfill\rule{6.5pt}{6.5pt}



