$$\xymatrix@C=20ex{
&  \tK_j^+\conv\Daf(\Qtp\ang{i}_{z})\ar[d]^{Q_{i,j}(z,z_j)}\ar@{.>}[dl]\\
\Daf(\Qtp\ang{i}_{z})\conv \tK_j^+\akew
