      \Th\label{th:SW}
      The family $(\tK_j^\pm)_{j\in I_\mp}$ in $\Pro(\Loc_{\pm})$
      is a Schur-Weyl datum for $R_\mp$.
      \enth
\Proof
Since $\Loc_+$ is quasi-rigid, it is enough to show \eqref{eq:DeQ} of  \eqref{eq: duality daum}, which is nothing but Theorem \ref{thm:DeSW}. \QED



      Let $\Psi_{\pm,\mp}\cl R_\mp \gmod\to \Loc_\pm$
      be the associated Schur-Weyl duality functor.




      Then $\Psi_{\pm,\mp}$ induces an isomorphism
      $\psi_{\pm,\mp}\cl\rtl(R_\mp)\isoto\rtl(R_\pm)$ given by
      $$\psi_{\pm,\mp}(\al_j)=\bc
      s_i(\al_j)&\text{if $j\in I$,}\\
       -\al_{i_\pm}
       &\text{if $j=\al_{i_\mp}$.}
      \ec$$



Note that  we only know here  that $\Psi_{\pm,\mp}$ is right exact.
(The exactness of $\Psi_{\pm,\mp}$ follows from Proposition~\ref{prop:FF*}
below.) 
Let $\Ld_n\Psi_{\pm,\mp}$ be the left derived functor of $\Psi_\pm\cl R_\mp\gmod\to\Locp$.
Since the family of $M\in R_\mp\gmod$ with finite projective dimension
  is $\Psip$-projective by Proposition~\ref{prop:F proj},  
  $\Ld_n\Psi_{\pm,\mp}(M)\simeq 0$ for $M$ with finite projective dimension.

We extend $\Ld_n\Psi_{\pm,\mp}\cl\Pro(R_\mp\gmod)\to\Pro(\Loc_\pm)$
so that it commutes with codirected projective limits.


\Lemma  \label{lem:Psi C}
We have $\Psi_{\pm,\mp}(C_\mp)\simeq(\tC_\pm)^{\circ-1}$.
\enlemma
\Proof We have
\eqn\Psi_{+,-}(C_-)\simeq\D^{-1}\Qtp(\ang{i_+})\hconv\Di
&&\simeq \bl\tC_+^{\circ-1}\conv\Qtp(\ang{i})\br\hconv\bl\Qtp(\ang{i_+})\conv\tC_+^{\circ-1}\br\\
&&\simeq\tC_+^{\circ-1}\conv\tC_+\conv \tC_+ ^{\circ-1}\simeq\tC_+^{\circ-1}.
\eneqn
\QED


\Prop
$\Psi_{+,-}$ factors as
$R_-\gmod\to\Loc_-\To[\F_i]\Loc_+$.
\enprop
\Proof
By Lemma \ref{lem:Psi C} and Theorem \ref{Thm: graded localization},
it remains to show that $\Psi_{+,-}(\coRr_{C_-}(M))\cl\Psi_{+,-}(M) \conv \Psi_{+,-}(C_-)  \to  \Psi_{+,-}(C_-) \conv \Psi_{+,-}(M)$
is an isomorphism for any $M\in R_-\gmod$. 

\medskip
We shall first show that
$$\text{$\Psi_{+,-}(\coRr_{C_-}(\ang{j}_z)) \cl \Psi_{+,-}(\ang{j}_z) \conv \tC_+  \to  \tC_+ \conv \Psi_{+,-}(\ang{j}_z)$ is an isomorphism for any $j\in I_-$.}$$
Since $\coRr_{C_-}(\ang{j}_z)$ is a rational isomorphism of homogeneous degree $0$,
so is $\Psi_{+,-}(\coRr_{C_-}(\ang{j}_z)) \cl \tK_j^+\conv \tC_+  \to  \tC_+ \conv \tK^+_j$. Since  $\La(K_j^+,\tC_+)=0$,
 $\Psi_{+,-}(\coRr_{C_-}(\ang{j}_z))$ is a renormalized R-matrix.
 Since $\tC_+$ is central in $\Loc_+$,
 the morphism $\Psi_{+,-}(\coRr_{C_-}(\ang{j}_z))$ is an isomorphism.

  \medskip
Since $\Psi_{+,-}$ is a monoidal functor,
$\Psi_{+,-}(\coRr_{C_-}(R_-(\beta)))$ is an isomorphism for any
$\beta\in\prtl(R_-)$.
Hence, 
the morphism $\Psi_{+,-}(\coRr_{C_-}(M))\simeq
\Psi_{+,-}(\coRr_{C_-}(R_-(\beta)))\tens_{R_-(\beta)} M$
is an isomorphism  for any $M\in R_-(\beta)\gmod$. 
\QED



\Lemma\label{lem:bijSW}
We have
\bnum
\item
  $\Psi_{+,-}(\ang{j\,i^{-c_{i,j}}})\simeq\Qtp(\ang{j})$
  for any $j\in I\setminus\st{i}$,
\item
  $  \F_i\bl\D^{-1}(\Qt_-(\ang{i}))\br\simeq\Qtp(\ang{i})$,
  \item
$  \F_i\bl\D(\Qt_-\ang{i_-})\br\simeq\Qtp(\ang{i_+})$.
\ee
\enlemma

\Proof
Set $c=-c_{i,j}$.
\noi
(i)\
Note first that
$\ang{j\,i^c}$ is the image of
$\rmat{\ang{j},\ang{i^c}}\cl\ang{j}\conv\ang{i^c}\to\ang{i^c}\conv\ang{j}$.

By applying the right exact functor $\Psip$
to $\ang{j}\conv\ang{i^c}\epito\ang{j\,i^c}$,
we obtain
$$\Psip(\ang{j})\conv\Psip(\ang{i^c})\epiTo\Psip(\ang{j\,i^c}).$$
It does not vanish by Lemma~\ref{lem:ijc}. 
Let us consider an exact sequence
$$0\To\ang{j\,i^c}\To\ang{i^c}\conv\ang{j}\To N\To0.$$
Since $\ang{j\,i^c}$ and $\ang{i^c}\conv\ang{j}$ have finite projective dimension (see \cite{Murata}), 
so does $N$.
Hence $\Ld_1\Psip(N)\simeq0$ and we obtain an exact sequence
$$0\To\Psip(\ang{j\,i^c})\To\Psip(\ang{i^c})\conv\Psip(\ang{j}).$$
  Hence $\Psip(\ang{j\,i^c})$ is the image of
    the R-matrix $\Psip(\ang{j})\conv\Psip(\ang{i^c})
    \To\Psip(\ang{i^c})\conv\Psip(\ang{j})$,
    i.e.
    $$\Psip(\ang{j\,i^c}) \simeq  \Psip(\ang{j})\hconv\Psip(\ang{i^c})\simeq
    \Qtp(\ang{i^c\,j})\hconv\D(\Qtp\ang{i^c})\simeq\Qtp(\ang{j}).$$

    \snoi
    (ii)\ We have
