    \F_i\bl\D^{-1}(\Qt_-(\ang{i}))\br\simeq
    \D^{-1}\Psip(\ang{i})\simeq
    \D^{-1}\D(\Qtp\ang{i})\simeq\Qtp(\ang{i}).\eneqn

    \snoi(iii) can be proved similarly.
\QED
\Lemma\label{lem:SW} We have
\bnum
\item 
  $\Psi_{+-}(\ang{j\,i^{-c_{i,j}}}_{z_j})\simeq\Qtp(\ang{j}_{z_j})$
  for any $j\in I\setminus\st{i}$,
