\ee
\enlemma
\Proof
(i)\ Set $c=-\sfc_{i,j}$.
We have an exact sequence
$$0\To\ang{j\,i^c}_{z_j}\To[z_j]\ang{j\,i^c}_{z_j}\To\ang{j\,i^c}\To0.$$
Since $\ang{j\,i^c}$ has a finite projective dimension (see \cite{Murata}),
        $\Ld_1\Psip(\ang{j\,i^c})\simeq0$ and hence
          we have an exact sequence
          $$0\To\Psip(\ang{j\,i^c}_{z_j})\To[z_j]\Psip(\ang{j\,i^c}_{z_j})
          \To\Psip(\ang{j\,i^c})\To0.$$
          Hence
          $\Psip(\ang{j\,i^c}_{z_j})\in\Aff(\Locp)$ and
          $\Psip(\ang{j\,i^c}_{z_j} )/z_j\Psip(\ang{j\,i^c}_{z_j})\simeq
          \Qtp(\ang{j} )$.

By Lemma~\ref{lem:cusp}, we have
$$\ang{j}_{z_j}\conv[z_j]\ang{i^c}_{z_j}\epiTo \ang{j\,i^{c}}_{z_j}
\monoTo \ang{i^c}_{z_j}\conv[z_j]\ang{j}_{z_j}.$$
