\eq
\Psi_{+-}(\ang{j}_{z_j})\conv[z_j]\Psi_{+-}(\ang{i^c}_{z_j})
\epito \Psi_{+-}(\ang{j\,i^{c}}_{z_j}).\label{eq:epiPsij}
