\simeq \Qtp(\ang{i^c\,j}_{z_j} ) \conv[z_j]\D\Qtp(\ang{i^c}_{z_j})\\
&&\hs{8ex}\To
\Qtp(\ang{j}_{z_j})\conv[z_j]\Qtp(\ang{i^c}_{z_j})
\conv[z_j]\D\Qtp(\ang{i^c}_{z_j})
\To\Qtp(\ang{j}_{z_j})\conv[z_j]\cor[z_j]
