\Prop\label{prop:FF*}
$\F_i$ and $\F^*_i$ are a quasi-inverse to each other.
\enprop
\Proof
In order to see $\F_i\circ\F_i^*\simeq\id_{\Loc_+}$,
it is enough to show that
$\F_i\circ\Psi_{-,+}\simeq\Qt_+$, which follows from
Lemma~\ref{lem:SW}.
Indeed,  
Lemma ~\ref{lem:SW} implies that the functor $\F_i \circ \Psi_{-,+}$ is the restriction of the Schur-Weyl duality functor associated with the duality datum
$$\bl \{\Qtp(\ang{j}_{z_j}) \}_{j\in I_+}, \{\Rre_{\Qtp(\ang{j}_{z_j}),\Qtp(\ang{k}_{z_k})} \}_{j,k\in I_+}\br.$$
Now the claim follows from \cite[Lemma 7.7]{refl} on the uniqueness of Schur-Weyl duality functors. 
\QED

Summarizing, we have the following main result of this paper. 
      \Th\label{th:FLoc}
      The functor
      $\Psi_{\pm,\mp}\cl R_\mp\gmod\to \Loc_\pm$
      factors as
 $$R_-\gmod\to \Loc_-\To[\F_i]\Loc_+\qtq
      R_+\gmod\to \Loc_+\To[\F^*_i]\Loc_-$$ 
      Moreover, $\F_i\cl \Loc_-\to\Loc_+$ and
      $\F^*_i\cl\Loc_+\to\Loc_-$ are a quasi-inverse to each other.
      \enth





\section{Generators of $(R\gMod) {}_i $ } \label{Sec: gen for iRgmod}

Let $R\gMod$ be the subcategory of $\Modg(R)$ consisting of  finitely generated graded $R$-modules. 
Set
\begin{equation} \label{Eq: iR and Ri}
\begin{aligned} 
(R\gMod)_i&\seteq\st{M\in R\gMod\mid \E_iM\simeq0}\qtq\\
{}_i (R\gMod)&\seteq \st{M\in R\gMod\mid \Es_iM\simeq0}.
\end{aligned}
\end{equation}

For $\nu=(\nu_1,\ldots,\nu_n)\in I^n$, we set
$$\dM(\nu)=R u(\nu),$$ where
$u(\nu)$ has the defining relations:
\begin{equation} \label{Eq: Mnu}
\begin{aligned}
&e(\nu)u(\nu)=u(\nu),\\
&\tau_1\cdots\tau_{k-1}u(\nu)=0\qt{if $1\le k\le n$ and
  $\nu_k=i$.}
\end{aligned}
\end{equation}
In particular, if $\nu_1=i$, then $\dM(\nu)=0$. 
\Lemma\label{lem:gen2}
$$\dM(\nu*j)\simeq\bc
\dM(\nu)\conv \ang{j}_{z_j}&\text{if $j\not=i$,}\\
\Coker\bl\ang{i}_z\conv\dM(\nu)\to\dM(\nu)\conv\ang{i}_z\br
&\text{if $j=i$.}
\ec
$$
Here $\nu*j$ is the concatenation of $\nu$ and $j$.
\enlemma

\Proof
By the definition, there exists a surjective $R$-module homomorphism
$$\dM(\nu) \conv\ang{j}_{z_j} \To[g] \dM(\nu *j)\quad \text{given by}\  u(\nu) \tens \ang{j}_z \mapsto u(\nu*j). $$
Moreover, if $j\neq i$, then it is an isomorphism. 

Assume that $j=i$.
Then $\bl\ang{i}_z,\dM(\nu)\br$ is unmixed  and hence
we have a canonical morphism
$\rmat{}\cl\ang{i}_z\conv \dM(\nu)\to\dM(\nu)\conv\ang{i}_z$
of degree $\bl\al_i,\wt(\dM(\nu))\br$  which is given by 
$$\rmat{} (x\tens y) = \tau_1\ldots\tau_n   \;(y\tens x) \quad \text{for} \  x \in \ang{i}_z, \ y \in \dM(\nu).$$
Hence
there is an $R$-module homomorphism
$$\dM(\nu*j) \To[h] \Coker(\rmat{}),\quad  \text{given by} \ u(\nu*j) \mapsto  u(\nu) \tens \ang{ i}_z + \Im(\rmat{}).$$
Since  $g\circ \rmat{}=0$, there is an $R$-module homomorphism $\Coker(\rmat{}) \to \dM(\nu*j)$, which is an inverse of $h$, as desired.
\QED
\Lemma\label{lem:gen1}
For each $\nu \in I^n$, we have $\dM(\nu)\in(R\gMod)_i$,
and we have an isomorphism
$$\HOM_{R\gMod_i}(\dM(\nu),X)\isoto \HOM_{R\gMod}(Re(\nu),X)$$ for any $X\in(R\gMod)_i$, which is functorial in $X$.
In particular $\dM(\nu)$ is a projective object of
$(R\gMod)_i$, and any object of $(R\gMod)_i$ is a quotient of
a direct sum of $\dM(\nu)$'s. 
\enlemma
\Proof
Let $\pi_\n\cl Re(\nu) \epito \dM(\nu)$ be the epimorphism given by $e(\nu) \mapsto u(\nu)$. Then $-\circ \pi_\nu\cl \HOM_{R\gMod_i}(\dM(\nu),X)\monoto \HOM_{R\gMod}(Re(\nu),X)$ is a monomorphism,  which is  functorial in $X \in R\gMod$. 
Let $X\in (R\gMod)_i$. Then $\tau_1\cdots \tau_k e(\nu) X =0$  for $k$ such that  $\nu_k=i$, and hence every homomorphism $Re(\nu) \to X$ factors through $\pi_\nu$. Hence $-\circ \pi_\nu$ is surjective.
The last assertion follows from the analogous properties of  $Re(\nu)$ in $R\gMod$.
\QED


For $M\in R\gmod$, 
let $r\cl e(i,*)M\to \E_iM$
be the natural  $\cor$-linear map so that
\eq
&&x_kr(u)=r(x_{k+1}u)\qtq\tau_lr(u)=r(\tau_{l+1}u)\qt{for $u\in e(i,*)M$.}
\label{eq:r}
\eneq


Recall that, for $M,N\in \Mod(\cor[z],\Mod(R))$, $M\conv[z]N$
denotes the cokernel of $z\conv\id_N-\id_M\conv z\in\END(M\conv N)$. 

The proof of the following theorem is given in Section  \ref{sec:appendixB}.
\Th\label{th:J}
 Let $M$ be an $R(\beta)$-module with $\beta\in\prtl$.
 Set $n=\height(\beta)$.
 \bnum
 \item

Then the $\cor$-linear map
$$J_M\cl M\to(\E_iM)\conv[z]\ang{i}_z$$
