\Lemma\label{lem:DiLa}
For any simple $M\in R\gmod$ such that $\Qtp(M)$ is simple, we have
\eqn
&&\La\bl \Qt_+(M), \Di \br=\La(\ang{i},M),\\
&&\La\bl\Di, \Qt_+(M)\br=-\bl \al_i,\wt(M)\br,\\
&&\de\bl\Di, \Qt_+(M)\br=\tLa(\ang{i},M).
\eneqn
Similarly, we have
$$\La\bl\Qt_-(M),\D^{-1}\Qt_-(\ang{i})\br=-\bl \al_i,\wt(M)\br.$$
\enlemma
\Proof
We have

\eqn
\La\bl \Qt_+(M), \Di \br=
\La\bl\Qtp(\ang{i}),\Qtp(M)\br=
\La(\ang{i},M),
\eneqn
where the last equality follows from $\ang{i}\in\Loc^0_+$.
We have
\eqn
\La\bl\Di, \Qt_+(M)\br&&=
\La\bl\tC_+^{\circ-1}\conv\Qt_+(\ang{i_+}), \Qt_+(M)\br\\
&&=\La\bl\Qtp(\ang{i_+}), \Qt_+(M)\br
=\La\bl\ang{i_+},M\br\\
&&=\la_+\bl-\al_{i_+},\wt(M)\br
=-\bl\al_i,\wt(M)\br.
\eneqn
Note that
$\La\bl\Qtp(\ang{i_+}), \Qt_+(M)\br=\La\bl\ang{i_+},M\br$
by Lemma~\ref{lem:LaQ+2}, and
$\La\bl\ang{i_+},M\br=\la_+\bl-\al_{i_+},\wt(M)\br$
since $(\ang{i_+},M)$ is unmixed.
\QED



\Lemma\label{lem:Dizqiz}
$\HOM_{\Proc(\cor[z,w],\Locp)}\bl\Diz\conv[z]\qiz[w],\cor[z,w]/\bl\cor[z,w](z-w)]\br\simeq0$.
\enlemma
\Proof
If it did not vanish, then $\HOM_{\Loc_+}(\Di\conv\qi,\one)$,
its specialization at $z=w=0$, would not vanish
by \cite[Proposition~3.7 (ii)]{refl} (set $H_0=0$).
It contradicts $\Di\hconv\qi\simeq
\Qt_+(\ang{i_+\;i})\conv\tC_+^{\circ-1}\not\simeq\one$.
\QED

\Lemma
$\De(\Qiz[w],\Diz)\equiv z-w$.
\enlemma
\Proof
Since there is an epimorphism
$\Qiz\convz\Diz\epito\cor[z]$, Proposition  \ref{prop:defactor} 
implies that $z-w$ divides $\De(\Qiz[w],\Diz)$.
Since $\De(\Qiz[w],\Diz)$ has homogeneous degree
$2\de(\Qi,\Di)=2\sfd_i$, we obtain
the desired result.
\QED
\Lemma\label{lem:Dii}
We have an exact sequence in $\Proc(\cor[z,w], \Loc_+)$:
$$
\xymatrix@C=3ex@R=3ex{
 0\ar[r]&\Diz\conv\Qt_+(\ang{i}_w)\ar[r]&
 \Qt_+(\ang{i}_w)\conv \Diz\ar[r]&\dfrac{\cor[z,w]}{\cor[z,w](z-w)}\ar[r]&0\;.}$$
\enlemma
\Proof
Let $f\cl \Diz\conv\Qt_+(\ang{i}_w)\to\Qiz[w]\conv \Diz$ be the R-matrix.
Since $\De(\Diz,\Qiz[w])\equiv z-w$, we have a commutative diagram
$$
\xymatrix@C=4ex@R=3ex{&&\Qt_+(\ang{i}_w)\conv \Diz\ar[ld]\ar[d]^{z-w}\\
 0\ar[r]&\Diz\conv\Qt_+(\ang{i}_w)\ar[r]^f&
 \Qt_+(\ang{i}_w)\conv \Diz\ar[r]&\Coker(f)\ar[r]&0\;.}$$
Hence $\Coker(f)$ belongs to
$\Proc(\cor[z,w]/\cor[z,w](z-w),\Locp)$.
Since the composition
\eqn
\Diz\conv\Qt_+(\ang{i}_w)\To[f]\Qiz[w]\conv \Diz\To&&\Qiz\convz\Diz\\
&&\hs{3ex}\to \cor[z,w]/\cor[z,w](z-w)
\eneqn
vanishes by Lemma~\ref{lem:Dizqiz}, we obtain
$$\Coker(f)\to\cor[z,w]/\cor[z,w](z-w).$$

Applying
$\cor[z,w]/(\cor[z,w]z+\cor[z,w]w)\tens_{\cor[z,w]}\scbul$,
we obtain an exact sequence
$$\Di\conv\Qi\to\Qi\conv\Di\to \Coker(f)/z\Coker(f)\To0.$$
Since we have an exact sequence
$$\Di\conv \Qi\To\Qi\conv\Di\To\one\To0,$$
we obtain
$$\Coker(f)/z\Coker(f)\simeq\cor.$$
Hence $\Coker(f)\to\cor[z]$ is an epimorphism.
Let $N$ be the kernel of $\Coker(f)\to\cor[z]$.

Then applying $(\cor[z]/\cor[z]z)\tens_{\cor[z]}$
to the exact sequence
$0\to N\to\Coker(f)\to\cor[z]\to0$,
we obtain an exact sequence
$0\to N/zN\to\Coker(f)/z\Coker(f)\to \cor\to0$.
Hence $N/zN\simeq0$, which implies that $N\simeq0$.
Thus, we obtain the desired result.
\QED


Recall the choice of $\Rmat_{\sDiz}$ in Lemma~\ref{lem:normR}. 
\Th\label{th:DiEi}
There exists a short exact sequence in $\Proc(\cor[z],\Loc_+)$:
$$0\to\Daf(\Qtp\ang{i}_{z})\conv \Qt_+(M)
\To[{\Rmat_{\sDiz}(M)}]\Qt_+(M)\conv\Daf(\Qtp\ang{i}_{z})
\To[{J'_M}]\Qt_+(\E_iM)\to0.
$$
functorially in $M\in R\gmod$.
 Here $z$ acts on $\E_iM$ by $x_1\in\END\bl e(i,*)M\br$.
 \enth

\Proof
We write $\Rmat(M)$ for
$\Rmat_{\sDiz}(M)$. 
Then $R(M)$ is a monomorphism in $\Proc(\cor[z],\Loc_+)$ since it is a rational isomorphism. 

We have a morphism in $\Proc(\cor[z],\Locp)$
\eqn
J'_M\cl
\Qtp(M)\conv \Diz&&\To[\Qtp(J_M)]
\Qtp(\E_iM)\conv[z]\qiz\conv[z]\Diz\\
&&\hs{5ex}\To[\ev] \Qtp(\E_iM)
\eneqn
with homogeneous degree $\bl\al_i,\wt(M)+\al_i\br$, where $J_M$ is the morphism in Theorem \ref{th:J}.

Let us first show that the composition
\eq
\Diz\conv \Qt_+(M)
\To[\Rmat(M)] \Qt_+(M)\conv\Diz
\To[J'_M]\Qtp(\E_iM)
\label{eq:compM}
\eneq
vanishes.
We have
a commutative diagram

\scalebox{1}{
\parbox{\textwidth}{
\eqn
\xymatrix@C=8ex{
  \Diz\conv \Qtp(M)\ar[dd]^-{\Rmat(M)}\ar[r]^-{\Qtp(J_M)}&
    \Diz\conv[z]\Qtp(\E_i\,M)\conv[z]\qiz\ar[d]^{\Rmat(\E_iM)}\\
    &\Qtp(\E_i\,M)\conv[z]\Diz\conv[z]\qiz\ar[d]^-{\Rmat(\iz)}\ar@/^10pc/[dd]^-g\\
    \Qt_+(M)\conv\Diz\ar[r]^-{\Qtp(J_M)}&    \Qtp(\E_i\,M)\conv[z]\qiz\conv[z]\Diz
    \ar[d]^-{\ev}\\
&\Qtp(\E_iM).
}
\eneqn
}}
Since $\HOM_{\Aff(R_+\gmod)}(\Diz\conv[z]\qiz,\cor[z])\simeq0$
by Lemma~\ref{lem:Dizqiz},
$g$ vanishes: thus so does the composition ~\eqref{eq:compM}.

\smallskip
Let us set
$$\Phi(M)=\Coker\bl\Diz\conv \Qt_+(M)\To[\Rmat(M)] \Qt_+(M)\conv\Diz\br.$$
Note that $\Phi$ is an {\em exact} functor from
$R\gmod$ to $\Proc(\cor[z],\Loc_+)$.
Since
$\Rmat_{\sDiz}(M)$ is a rational isomorphism, $z^n\Phi(M)\simeq0$ for $n\gg0$,
which implies that $\Phi(M)\in\Loc_+$ by  \cite[Proposition 4.8 (iii-b)]{refl}. 
Thus,
$\Phi$ gives an exact functor
$$\Phi\cl R\gmod\to\Mod(\cor[z],\Loc_+).$$
The morphism $J'_M$ gives a morphism
$$I_M\cl \Phi(M)\to \Qtp(\E_i M)$$
in $\Mod(\cor[z],\Loc_+)$ functorial in $M\in R\gmod$.

Let us show that
\eq \text{$I_M$ is an epimorphism for any $M\in R\gmod$.}\label{eq:Iepi}
\eneq
First assume that $M$ is simple.
We may assume that $m\seteq\eps_i(M)>0$ so that $\E_i(M)\neq 0$. 
Hence $\tE_iM=\hd(\E_i M)$ is a simple module.
Then we have
$(\E_iM)\conv[z]\ang{i}_z\epito\tE_iM\conv\ang{i}$.
The composition
$$J_M^0\cl M\To[J_M] (\E_iM)\conv[z]\ang{i}_z\to \tE_iM\conv\ang{i}$$
does not vanish in $R\gmod$, which follows from
the commutative diagram
  $$\xymatrix@C=12ex{
    \E_iM\ar[r]^-{\E_i(J_M)}\ar@/_3pc/[ddr]|(.35){\id_{\E_iM}\akete[.5ex]\ake[-1ex]}&\E_i(\E_iM\convz\ang{i_z})\ar@{->>}[r]\ar[d]&\E_i(\tE_iM\conv\ang{i})\ar[d]\\
    &\E_iM\convz\E_i\ang{i_z}\ar[r]\ar[d]^\bwr
    &\tE_iM\conv\E_i\ang{i}\ar[d]^\bwr\\
    &\E_iM\ar[r]&\tE_iM.}
  $$

  \medskip
  The composition
  $$\Qtp(M)\conv\Di\To[\Qtp(J_M^0)] \Qtp(\tE_iM)\conv\Qtp(\ang{i})\conv \Di\To\Qtp(\tE_iM)$$
  is an epimorphism, since the left and right arrows are non-zero morphisms,
  and $\Qtp(\ang{i})$ is simple. 
By the commutative diagram
  $$\xymatrix{\Qtp(M)\conv\Diz\ar@{->>}[r]\ar@{->>}[d]&\Phi(M)\ar[r]^{I_M}&\Qtp(\E_iM)\ar[d]\\
   \Qtp(M)\conv\Di\ar[r]&\Qtp(\tE_iM)\conv\Qi\conv \Di\ar[r]&\Qtp(\tE_iM),
  }$$
  the composition
  $\Phi(M)\To[I_M]\Qtp(\E_iM)\epito \Qtp(\tE_iM)$ is an epimorphism.
      Since $\Qtp(\E_iM)$ has a simple head $\Qtp(\tE_iM)$ and the composition
  $\Phi(M)\To[I_M]\Qtp(\E_iM)\epito \Qtp(\tE_iM)$ is an epimorphism,
  we obtain that $I_M\cl\Phi(M)\to\Qtp(\E_iM)$ is an epimorphism
  for any simple $M$.
  Since $\Phi$ and $\E_i$ are exact functors, we conclude 
  \eqref{eq:Iepi} by induction on the length of $M$.


  \bigskip


For
$M,N\in R\gmod$,
let us consider a commutative diagram

\scalebox{.8}{\parbox{70ex}{
\eqn
\xymatrix@C=5ex@R=5ex{&&0\ar[d]&0\ar[d]\\
  0\ar[r]&\Diz\conv \Qtp(M)\conv \Qtp(N)\ar[r]^{R(M)}\ar[d]^-\bwr&\Qtp(M)\conv\Diz\conv \Qtp(N)
  \ar[r]\ar[d]_{R(N)}&\Phi(M)\conv \Qtp(N)\ar[r]\ar[d]&0\\
0\ar[r]&\Diz\conv \Qtp(M)\conv \Qtp(N)\ar[r]^{R(M\circ N)}&\Qtp(M)\conv \Qtp(N)\conv\Diz\ar[r]\ar[d]&\Phi(M\conv N)\ar[r]\ar[d]&0\\
&&\Qtp(M)\conv \Phi(N)\ar[r]^\sim\ar[d]&\Qtp(M)\conv \Phi(N)\ar[d]\\
&&0&0
  }
  \eneqn
}}

  Hence we obtain an exact sequence
  \eq
  0\To\Phi(M)\conv \Qtp(N)\To\Phi(M\conv N)\To \Qtp(M)\conv\Phi(N)\To0.\label{eq:exactMN}
  \eneq

  \medskip
  Now we shall show that
  $\Phi(M)\to \Qtp(\E_iM)$ is an isomorphism for any $\beta\in\prtl$ and
any  $M\in R(\beta)\gmod$ by induction on $\height{(\beta)}$.

  For $X\in\Locp$, we denote by $[X]$ the corresponding element in
  the Grothendieck group $K(\Locp)$.

  \snoi
  {\bf Step1}\ First $\Phi(M)\to \Qtp(\E_iM)$ is an isomorphism for $M=\ang{j}$
  with $j\in I$   (see Lemma~\ref{lem:Dii} when $j=i$).  
Hence $\Phi(M)\to \Qtp(\E_iM)$ is an isomorphism
  for any $M\in R(\al_j)\gmod$.

  \snoi
  {\bf Step2}\ Assume that $\height(\beta)>1$.

  Now let $\beta=\gamma+\delta$ with $\gamma,\delta\in\prtl\setminus\st{0}$.
  Let $M\in R(\gamma)$ and $N\in R(\delta)\gmod$.
  Then by the induction hypothesis, we have
  $[\Phi(M)]=[\Qtp(\E_i M)]$ and  $[\Phi(N)]=[\Qtp(\E_i N)]$.
  Hence we have
  \eqn
[\Phi(M\conv N)]&&=[\Phi(M)\conv \Qtp(N)]+[\Qtp(M)\conv\Phi(N)]\\
&&  =[\Qtp(\E_iM)\conv \Qtp(N)]+[\Qtp(M)\conv\Qtp(\E_iN)]=[\Qtp(\E_i(M\conv N))].
  \eneqn
  Therefore,
        $[\Phi(X)]=[\Qtp(\E_iX)]$ if $X\in R\gmod$ is isomorphic to
    $M\conv N$.
Hence $\Phi(X)\to\Qtp(\E_iX)$ is an isomorphism for such an $X$
by \eqref{eq:Iepi}.
Since any $M\in R(\beta)\gmod$ has a resolution
$X_1\to X_0\to M\to 0$ such that $\Phi(X_k)\to\Qtp(\E_iX_k)$ is an isomorphism
for $k=0,1$,
we obtain a desired result: $\Phi(M)\to\Qtp(\E_iM)$ is an isomorphism
for any $M\in R\gmod$.
  \QED




\section{Reflection functor from $\Ri$ to $\iR$} \label{Sec: reflection}

\Th\label{th:FR}
We have  quasi-commutative diagrams:
\eqn
\xymatrix@C=10ex{
  (R\gmod){}_i\ar@{^{(}->}[d]\ar[r]_{\F_i}&{}_i(R\gmod)\ar@{^{(}->}[d]\\
  R_-\gmod\ar[d]_{\Qt_-}\ar[dr]|{\Psi_{+,-}}&R_+\gmod\ar[d]^{\Qt_+}\\
  \Loc_-\ar[r]_{\F_i}& \Loc_+ }&\qquad&
\xymatrix@C=10ex{
  {}_i(R\gmod)\ar@{^{(}->}[d]\ar[r]_{\F_i^*}&(R\gmod)_i\ar@{^{(}->}[d]\\
  R_+\gmod\ar[d]_{\Qt_+}\ar[dr]|{\Psi_{-,+}}&R_-\gmod\ar[d]^{\Qt_-}\\
  \Loc_+\ar[r]_{\F^*_i}&\; \Loc_-\;.}
\eneqn
Moreover, $\F_i\cl(R\gmod){}_i\to{}_i(R\gmod) $ and
$\F_i^*\cl{}_i(R\gmod)\to(R\gmod){}_i$ are a quasi-inverse to each other.
\enth

In order to see Theorem~\ref{th:FR}, it is enough to show the following proposition (and its variant for $\F_i^*$) 
since $\Ri$ and $\iR$ are full subcategories of $\Loc_-$ and $\Loc_+$ via $\Qtm$ and $\Qtp$, respectively. 



\Prop \label{prop:FiQtmRi}
We have $\F_i\bl\Qt_-(\Ri)\br\subset \Qt_+(\iR)$.
\enprop


\Proof
We shall first show that
$$\F_i\bl\Qt_-(\Ri)\br\subset\Qtp(R\gmod).$$
In order to see this it is enough to show the following statement:
%
\eq
\parbox{67ex}{if $M\in \Ri $  satisfies
  $\F_i\bl\Qt_-(M)\br  \in\Qtp(R\gmod)$,
  then
  $\F_i\bl\Qt_-(X)\br\in\Qtp(R\gmod)$, where
  $X=\Coker\bl\ang{i}_z\conv M\to M\conv\ang{i}_z\br$.}
\label{eq:FiR}
\eneq
Indeed  we have $\F_i(\Qt_-(\ang{j}_z)) \simeq \Psi_{+,-}(\ang{j}_z) \in \Qtp(R\gmod)$ for $j\in I$,  $j \neq i$.
Assume \eqref{eq:FiR}.  Then by Lemma~\ref{lem:gen2}, we get $\F_i(\Qt_-(\dM(\nu))) \in \Qtp(R\gMod)$ by induction on length of $\nu$. By Lemma~\ref{lem:gen1},  if $M \in\Ri$,  then $\F_i\bl\Qt_-(M))$ is a subquotient of $\soplus_k\F_i(\Qt_-(\dM(\nu_k)))$ for some $\nu_k$'s. 
Since $R\gmod$ is stable under taking subquotients in $\Loc_+$ by Proposition~\ref{prop:stab subq}, $\F_i\bl\Qt_-(M))$ belongs to $\Qtp(R\gmod)$.


\medskip
Let us prove \eqref{eq:FiR}. 
Let $N\in R\gmod$ be a module such that
$\F_i\bl\Qt_-(M)\br\simeq\Qtp(N)$.
Then, we have
\eqn
\F_i\bl\Qt_-(X)\br
&&\simeq\Coker\bl\Diz\conv \Qtp(N)\to\Qtp(N)\conv\Diz\br\\
&&\simeq\Qtp(\E_i N),
\eneqn
where the last isomorphism follows from Theorem~\ref{th:DiEi}.
Hence we obtain \eqref{eq:FiR}.

\vskip 1em
It remains to show that
\eq
\parbox{67ex}{if a simple $M\in\Ri$ and a simple $N\in R\gmod$ satisfy
  $\F_i\bl\Qt_-(M)\br\simeq\Qtp(N)$,
  then $N$ belongs to $\iR$.}
\label{eq:FiiR}
\eneq

We have
\eqn
\La(N,\ang{i})&&=\La\bl(\Qtp(N),\Qtp(\ang{i})\br
=\La(\Qt_-(M),\D^{-1}(\Qt_-\ang{i})\br
=-\bl\al_i,\wt(M)\br,
\eneqn
where the last equality follows from
Lemma~\ref{lem:DiLa}.
Hence we have
\eqn
2\tLa(N,\ang{i})&&=\La(N,\ang{i})-\bl\al_i,\wt(N)\br\\
&&=-\bl\al_i,\wt(M)\br-\bl\al_i,\;s_i\wt(M)\br=0.
\eneqn
Thus we obtain $N\in \iR$ by \cite[Lemma 2.15]{loc2}.
\QED

\Th\label{th:saito}
The algebra homomorphism
$K((R\gmod)_i)\to K({}_i(R\gmod))$ induced by $\F_i$
coincides with the braid symmetry homomorphism \ro see \cite{ext}\rf. 
\enth
\Proof
We have exact sequences (respecting the gradings)
$$0\to q_i^2\ang{i_+\,i}\to\ang{i}\conv\ang{i_+}\to C_+\to0
\qtq0\to C_+ \to\ang{i_+}\conv\ang{i}\to\ang{i_+\,i}\To0$$
in $R_+\gmod$.
Hence we have
$$[\Qtp\ang{i}]\cdot[\Qtp\ang{i_+}]
-q_i^2[\Qtp\ang{i_+}]\cdot[\Qtp\ang{i}]=(1-q_i^2)[\tC_+],$$
which implies that
\eq
&&[\Qtp\ang{i}]\cdot[\D \Qtp\ang{i}]
-q_i^2[\D\Qtp\ang{i}]\cdot[\Qtp\ang{i}]=1-q_i^2.\label{eq:bos}
\eneq
Since $\la_+(\al_{i_+},j)=(\al_i,\al_j)$ for $j\in I\setminus\st{i}$,
we have
$q^{(\al_i,\al_j)}\ang{i_+}\conv\ang{j}\simeq\ang{j}\conv\ang{i_+}$,
  which implies
  \eq
  [\Qtp\ang{j}]\cdot[\D\Qtp\ang{i}]=q^{(\al_i,\al_j)}  [\D\Qtp\ang{i}]\cdot[\Qtp\ang{j}].
  \label{eq:bos2}
  \eneq

Let  $ \g$ be the Kac-Moody algebra associate with the Cartan matrix $\cartan$ and let $\hcalA$ be the bosonic extension of type $\g$. As a $\Q(q)$-algebra, $\hcalA$ is generated by $\set{f_{j,m}}{j\in I, \ m \in \Z}$.  For the definition and properties of $\hcalA$ we refer \cite{ext}. 
Let us denote by $\B_i$ the $\Qq$-subalgebra of $\hcalA$
generated by $f_{i,1}$ and $\st{f_{j,0}\mid j\in I}$. 
Then \eqref{eq:bos} and \eqref{eq:bos2} imply that
there exists a $\Qq$-algebra homomorphism
$\B_i\to \Qq\tens_{\Zq} K(\Loc_+)$ given by
$$f_{j,0}\mapsto [\Qtp\ang{j}] \quad (j\in I),\quad f_{i,1}\mapsto[\D\Qtp\ang{i}].$$
Then we have a commutative diagram (see \cite[Section 3]{ext})
$$\xymatrix@C=6ex{
\hcalA[0]\ar[d]\ar[r]^{\TT_i}&\B_i\ar[d]\\
\Qq\tens_{\Zq}K(\Loc_-)\ar[r]^{\F_i}&\Qq\tens_{\Zq}K(\Loc_+)}
$$
Since $\TT_i\in\End(\hcalA)$ induces the braid symmetry homomorphism
$${\mathsf S}_i\cl A_{\Zq}(\mathfrak n)[i]\isoto A_{\Zq}(\mathfrak n)[i]^*$$
(for the definitions, see \cite[Section 1]{ext}), 
and $A_{\Zq}(\mathfrak n)[i] \simeq  K((R\gmod)_i)$,  $A_{\Zq}(\mathfrak n)[i]^* \simeq  K(_i(R\gmod))$,
we obtain Theorem~\ref{th:saito}.
\QED

\Conj
If $\g$ is finite type, then
$\F_i$ coincides with the reflection functor constructed in
\cite{refl}.
\enconj



\section{Appendix A: Proof of Proposition~\ref{prop:affD}
} \label{sec:appendixA}
\subsection{The case of the right dual of $\Qi$}
In this subsection, we prove the following lemma.
\Lemma \label{lem:Qiz}
The affine object $\Diz$ has a rational center structure
  $\Rmat_{\sDiz}$.
\enlemma

The following lemma follows from the universal properties of the right duals.
\Lemma
Let $\dM$ be an object of $\Aff(\shc)$ which admits a right dual $\Da(\dM)$ in $\Aff(\shc)$.
Then there is an  isomorphism
$$\HOM_{\Proc(\cor[z],\shc)}(\dM \tens X, Y\tens \dM) \simeq \HOM_{\Proc(\cor[z],\shc)}( X\tens \Da(\dM),\Da(\dM) \tens Y) $$
which is functorial in $X,Y \in \shc$.
\enlemma
Hence $\Rmat_{\Qiz}(X)\cl \Qiz\conv X\to X\conv \Qiz$ induces a morphism
$$\Rmat'_{\sDiz}(X)\cl X\conv\Diz\to \Diz\conv X$$
functorial in $X\in\Loc_+$.
Hence, in order to prove Lemma~\ref{lem:Qiz}, it is enough to show that it is a rational isomorphism.
We may assume that $X=\Qtp(R(\nu))$ for $\nu\in I_+^n$, and then we can reduce to the case
$X=\Qtp(R(\al_j))$ and then $X=\Qi[j]$
for $j\in I_+$.
Hence it suffices to show that a non-zero morphism
$$\Rmat\cl \Qtp(\ang{j})\conv\Diz\to \Diz\conv\Qtp(\ang{j})$$
is a rational isomorphism for any $j\in I_+$.

Since $\Rmat$ does not vanish, replacing $\Rmat$ with $z^{-n}\Rmat$ for some $n$,
we may assume that
$\Rmat\vert_{z=0}\cl \Qi[j]\conv\Di\to \Di\conv \Qi[j]$
does not vanish.
If $j\not=i$, then $\Rmat\vert_{z=0}$ is an isomorphism because
$\Qtp(\ang{j})$ and $\Di$ commute. This implies that $\Rmat$ is an isomorphism.
Hence we may assume that $j=i$.

Thus we can assume that $I=\st{i}$, and hence $R_+$ is of type $A_2$.
Then we can embed $\Loc_+$ into the rigid monoidal category $(R_{A_2}\gmod)\,\widetilde{}$,
the localization of $R_{A_2}\gmod$ by the quasi-centers.
 More precisely, the functor
$\Loc_+\to(R_{A_2}\gmod)\,\widetilde{}$ is exact and fully faithful by \cite[Theorem 8.3]{refl}.
Since Proposition~\ref{prop:rational dual} implies that
the image of $\Rmat$ in $(R_{A_2}\gmod)\,\widetilde{}$ is a monomorphism, 
$\Rmat$  is also a monomorphism, which implies that $\Rmat$ is a rational isomorphism. 





\subsection{The case of the left dual of $\Qtp(\ang{i_+})$}
Let us prove the following lemma.
\Lemma \label{lem:Dizp}
  There exists a rational center
  $(\Dipz,\Rmat_{\sDipz})$.
\enlemma

The morphism
$\Rmat_{\Qipz}(X)^{-1}\cl X\conv\Qipz\to \Qipz\conv X$ induces a morphism
$$\Rmat_{\sDipz}(X)\cl\Diz\conv X\to X\conv\Diz$$
functorial in $X\in\Loc_+$.
It is enough to show that it is a rational isomorphism.
By a similar argument as the one in the preceding subsection, it is enough to show that
a non-zero morphism
$$\Rmat\cl\Dipz\conv \Qtp(\ang{j})\to \Qtp(\ang{j})\conv\Dipz$$
is a rational isomorphism for any $j\in I_+$.
We may assume that
$\Rmat\vert_{z=0}\cl\Dip\conv\Qtp(\ang{j})\to \Qtp(\ang{j})\conv\Dip$
does not vanish.
If $j=i$ it is an isomorphism, since
$\Qi$ and $\Dip$ commute. This implies that $\Rmat$ is an isomorphism.
If $j=i_+$, we can assume that $I=\st{i}$, and hence $R_+$ is of type $A_2$.
Then we can embed $\Loc_+$ into the rigid monoidal category $(R_{A_2}\gmod)\,\widetilde{}$,
the localization of $R_{A_2}\gmod$ by the quasi-centers.
Hence the assertion follows from Proposition~\ref{prop:rational dual}.

Thus we reduce to the case $j\in I\setminus\st{i}$.
If $(\al_i,\al_j)=0$, then $\ang{j}$ and $\D^{-1}\ang{i_+}$ commute and hence
$\Rmat$ is an isomorphism.
Hence we may assume that $(\al_i,\al_j)<0$,

We shall show the following lemma.
\Lemma\label{lem:extf}
For any $j\in I\setminus\st{i}$ such that $(\al_i,\al_j)<0$, there exist $n\in\Z_{\ge0}$
and
 a morphism
\eqn
&&f\cl \Ka\conv \Qtp(\ang{j})
\to \Qtp(\ang{j})\conv\Ka\eneqn
in $\Proc(\cor[z],\Loc_+)$
such that $\Im(f)$ contains
$\Qtp(\ang{j})\conv(z^n\Ka)\subset\Qtp(\ang{j})\conv\Ka$.
Here $\Ka\seteq\Dipz/z^{n+1}\Dipz\in \Proc(\cor[z],\Loc_+)$.
\enlemma

Admitting this lemma for a while, let us complete the proof of
Lemma~\ref{lem:Dizp}.
By \cite[Proposition 3.7]{refl},
$f=cz^k\Rmat\vert_{z^{n+1}=0}$ for some $c\in\cor^\times$ and $k\in[0,n]$.
Hence we have
$\Qi[j]\circ z^n\Dipz\subset\Im(\Rmat)+\Qi[j]\circ z^{n+1}\Dipz$.
Hence we have
$\Qi[j]\circ z^n\Dipz\subset\Im(\Rmat)$, which implies that
$\Rmat$ is a rational isomorphism. Thus we obtain Lemma~\ref{lem:Dizp}.

\bigskip
Finally let us prove Lemma~\ref{lem:extf}.
By the commutative diagram 
\eqn
\xymatrix{
  z^n\Ka\akete\ar[r]^-\sim\ar@{^{(}->}[d]&\tC_+^{\circ(-n-1)}\conv
  \Qtp(C_+^{\circ(n)}\conv\E_{i_+}^*C_+)
  \ar@{^{(}->}[d]\\
\Ka\ar[r]^-\sim&\tC_+^{\circ(-n-1)}\conv\Qtp\bl\Es_{i_+}(C_+^{\circ(n+1)})\br,
}
\eneqn
it is enough to construct a morphism
$$g\cl \Qtp\bl\Es_{i_+}(C_+^{\circ(n+1)})\conv\ang{j}\br
\to\Qtp\bl\ang{j}\conv\Es_{i_+}(C_+^{\circ(n+1)})\br$$
in $\Loc_+$ such that
\eq
\Qtp\bl\ang{j}\conv C_+^{\circ n}\conv (\Es_{i_+}C_+)\br\subset\Im(g).
\label{eq:condg}
\eneq

By the exact sequence
$$0\To\ang{j\,i\,i_+}\To C_+\conv\ang{j}\To\ang{j}\conv C_+\To\ang{j\,i\,i_+}\To0$$
and $\Qtp(\ang{j\,i\,i_+})\simeq0$ (Lemma~\ref{lem:jC+}), the morphism
$$ \Qtp(C_+\conv\ang{j})\To\Qtp(\ang{j}\conv C_+)$$
is an isomorphism in $\Loc_+$.
Hence, their composition
$$\Qtp(C_+^{\circ n}\conv\ang{j})\To\Qtp(\ang{j}\conv C_+^{\circ n})$$
is an isomorphism.
Since the image $C_+^{\circ n}\conv\ang{j}\To\ang{j}\conv C_+^{\circ n}$ is the simple socle
$\ang{j}\sconv C_+^{\circ n}$ of $\ang{j}\conv C_+^{\circ n}$, we obtain
$$\Qtp\bl\ang{j}\conv C_+^{\circ n}\br=\Qtp\bl\ang{j}\sconv C_+^{\circ n}\br.$$
Hence \eqref{eq:condg} is equivalent to
\eq
\Qtp\bl(\ang{j}\sconv C_+^{\circ n})\conv \Es_{i_+}(C_+)\br\subset\Im(g).
\label{eq:condg1}
\eneq
Let
$$h\cl C_+^{\circ(n+1)}\conv\ang{j}\to \ang{j}\conv C_+^{\circ(n+1)}$$
be a non-zero morphism in $R_+\gmod$.
Then $\Im(h)$ coincides with the simple socle of
$\ang{j}\conv C_i^{\circ(n+1)}$.

Now let us take $n\gg0$ such that
$\ang{j}\sconv C_+^{\circ n}$ commutes with $C_+$ (see  \cite[Corollary 3.18]{loc1}).
Then, $(\ang{j}\sconv C_+^{\circ n})\conv C_+$ is a simple submodule of
$\ang{j}\conv C_i^{\circ(n+1)}$.
Hence we obtain
\eq\Im(h)=(\ang{j}\sconv C_+^{\circ n})\conv C_+.
\label{eq:Imh}
\eneq

Taking $\Es_{i_+}$, we obtain a morphism
$$h'\cl  \Es_{i_+}(C_+^{\circ(n+1)})\conv\ang{j}\simeq
\Es_{i_+}\bl C_+^{\circ(n+1)}\conv\ang{j}\br\To[\Es_{i_+}(h)]
\Es_{i_+}\bl\ang{j}\conv C_i^{\circ(n+1)}\br\simeq\ang{j}\conv\Es_{i_+}(C_i^{\circ(n+1)}).$$
By \eqref{eq:Imh}, we obtain
\eq\Im(h')=\Es_{i_+}\bl(\ang{j}\sconv C_+^{\circ n})\conv C_+\br
\supset (\ang{j}\sconv C_+^{\circ n})\conv  \Es_{i_+}(C_+).
\label{eq:Imh'}
\eneq
Thus
$$g=\Qtp(h')\cl  \Qtp\bl\Es_{i_+}(C_i\conv C_i)\conv\ang{j}\br
\to\Qtp\bl\ang{j}\conv\Es_{i_+}(C_i\conv C_i)\br$$
satisfies \eqref{eq:condg1}.
It shows Lemma~\ref{lem:extf}
and completes the proof of Lemma~\ref{lem:Dizp}.



