h_a(x_au)
&&-\sum_{s=1}^{k-1}\delta(\nu_{s}=i)
(\tau_{s}\cdots\tau_{k-2})(\tau_k\cdots \tau_{n-1})
\bl r(\tau_{1}\cdots\tau_{s-1})u)\tens \ang{i}_z\br\\
&&-\sum_{s=k+1}^{n}\delta(\nu_{s}=i)(\tau_{k}\cdots
\tau_{s-2})(\tau_{s}\cdots\tau_{n-1})\bl r(\tau_1\cdots\tau_{k-1}u)\tens \ang{i}_z\br.
\eneqn

%
\snoi
(Bd)\ 
Now, for any $k\in[1,n]$, we have
\eqn
&&x_kJ_M(u)-J_M(x_ku)
=\sum_{\nu_a=i}\bl
x_kh_a(u)-h_a(x_ku)\br\\
&&\hs{2ex}=
\delta(\nu_{k}=i)\sum_{a<k,\; \nu_a=i}
   (\tau_{k}\cdots \tau_{n-1})
  \bl r\bl(\tau_1\cdots\tau_{a-1})(\tau_{a+1}\cdots \tau_{k-1})u\br\tens \ang{i}_z\br\\
&&\hs{5ex}+\delta(\nu_{k}=i)\sum_{a>k,\;\nu_a=i}
\tau_a\cdots\tau_{n-1}\bl r\bl (\tau_1\cdots\tau_{k-1})(\tau_{k+1}\cdots \tau_{a-1})
u\br\tens \ang{i}_z\\
&&\hs{8ex}-\delta(\nu_k=i)\sum_{s<k}\delta(\nu_{s}=i)
(\tau_k\cdots \tau_{n-1})
\bl r\bl\tau_{1}\cdots\tau_{s-1})(\tau_{s+1}\cdots\tau_{k-1})u\br\tens \ang{i}_z\br\\
&&\hs{10ex}-\delta(\nu_k=i)\sum_{s>k}\delta(\nu_{s}=i)
(\tau_{s}\cdots\tau_{n-1})\bl r\bl(\tau_1\cdots\tau_{k-1})(\tau_{k+1}\cdots
\tau_{s-1})u\br\tens \ang{i}_z\br
\\
&&\hs{2ex}=0.
\eneqn

 \snoi
(C)\ Assume that $u \in e(\nu) M$. Let us show 
 \eq  J_M(\tau_ku)=\tau_kJ_M(u)\qt{for $k\in[1,n-1]$.}
 \eneq


 Since $\tau_ku\in e(s_k\nu)M$, we have
 \eqn
 J_M(\tau_ku)=\sum_{a\not=k,k+1,\;\nu_a=i}h_a(\tau_ku)
 +\delta(\nu_k=i)h_{k+1}(\tau_ku)
 +\delta(\nu_{k+1}=i)h_{k}(\tau_ku).
 \eneqn

 First we shall prove
\Sublemma\label{sub:Qq}
   If $\mu\in I^n$ satisfies $\mu_n=i$ and $\mu_s=\nu_{s+1}$
   for $s\in [a,n-1]$ and if
   $A\subset[1,a-1]$, $k\in[1,a-1]$ and $j=\mu_k$, then we have
   \eqn
   &&\tau_a\cdots\tau_{n-1}Q_{i,j}(x_n,\st{x_s}_{s\in A};x_k)e(\mu)
   =\hs{-2ex}\sum_{\sigma\in A_i([a+1,n],\nu)}\hs{-3ex}
   Q_{i,j}(\st{x_s}_{s\in\sigma\cup\st{a}},\st{x_s}_{s\in A};x_k)
(\hs{-2ex}\uprod_{s\in[a+1,n]\setminus\sigma}\hs{-2ex}\tau_{s-1})e(\mu).\eneqn
   \ensublemma
   \Proof
   We have
   \eqn
   \tau_a\cdots\tau_{n-1}Q_{i,j}(x_n,\st{x_s}_{s\in A};x_k)e(\mu)
=\hs{-2ex}\sum_{\gamma\in A_i([a,n-1];\mu)}\hs{-5ex}
   Q_{i,j}(x_a,\st{x_{s+1}}_{s\in\gamma},\st{x_s}_{s\in A};x_k)
   (\hs{-2ex}\uprod_{s\in[a,n-1]\setminus\gamma}\tau_{s})e(\mu).\eneqn
   We have a bijection $A_i([a,n-1];\mu)\isoto A_i([a+1,n];\nu)$ by
   $A_i([a,n-1];\mu)\ni\gamma\mapsto
   \sigma=\st{s+1\mid s\in\gamma}\in A_i([a+1,n];\nu)$.
     Hence, we have
   \eqn
   \tau_a\cdots\tau_{n-1}Q_{i,j}(x_n,\st{x_s}_{s\in A};x_k)e(\mu)
=\hs{-3ex}\sum_{\sigma\in A_i([a+1,n];\nu)}\hs{-5ex}
   Q_{i,j}(x_a,\st{x_{s}}_{s\in\sigma},\st{x_s}_{s\in A};x_k)
   (\hs{-2ex}\uprod_{s\in[a+1,n]\setminus\sigma}\hs{-2ex}\tau_{s-1})e(\mu).\eneqn

   \QED


   For $\sigma\in A_i[1,k-1]$ and $\gamma\in A_i[k+2,n]$, we set
   \eq
   &&\hs{5ex}\ba{l}
   X(\sigma,\gamma)\seteq
   Q_{i,\nu_{k+1}}(x_{k+1},\st{x_{s}}_{s\in\gamma},
\st{x_{s}}_{s\in\sigma},;x_{k})\\[.5ex]
\hs{30ex}\bl\uprod_{s\in[k+2,n]\setminus\gamma}\tau_{s-1}\br 
\Bigl( r\bl
(\uprod_{s\in[1,k-1]\setminus\sigma}\tau_s)u\br\tens\ang{i}_z\Bigr).   
\ea   \label{eq:X}
\eneq

\mnoi
 (Ca)\ Assume first that $a+1\le k\le n-1$ and $\nu_a=i$. Then we have
 \eqn
 h_a(\tau_ku)&&=
 \tau_a\cdots\tau_{n-1}\bl
 r(\tau_1\cdots\tau_{a-1}\tau_ku)\tens\ang{i}_z\br\\
&&= \tau_a\cdots\tau_{n-1}\tau_{k-1}\bl
r(\tau_1\cdots\tau_{a-1}u)\tens\ang{i}_z\br.
\eneqn
Take $\mu\in I^n$ such that
$e(\mu)\bl r(\tau_1\cdots\tau_{a-1} u \tens\ang{i}_z\br 
 =\bl r(\tau_1\cdots\tau_{a-1} u \tens\ang{i}_z\br$. Then, we have
 $\mu_n=i$ and $\mu_s=\nu_{s+1}$ for $s\in[a,n-1]$.

We have
\eqn
&&\tau_a\cdots\tau_{n-1}\tau_{k-1}e(\mu)\\
&&=\tau_k\tau_a\cdots\tau_{n-1}e(\mu)-
\delta(\mu_{k-1}=i)\sum_{\sigma\in A_i([a,k-2];\mu)}
  Q_{i,\mu_{k}}(x_a,\st{x_{s+1}}_{s\in\sigma}, x_{k+1};x_{k})\\
&&\hs{35ex}
\bl\uprod_{s\in ([a,k-2]\setminus\sigma)\cup[k+1,n-1]}\tau_s\br\Bigr)\,e(\mu).
\eneqn
Note that $A_i([a,k-2];\mu)\isoto A_i([a+1,k-1];\nu)$ by
$A_i([a,k-2];\mu)\ni\sigma\mapsto\st{s+1\mid s\in\sigma}\in A_i([a+1,k-1];\nu)$.
Hence we have
\eqn
&&\tau_a\cdots\tau_{n-1}\tau_{k-1}e(\mu)\\
&&=\tau_k(\tau_a\cdots\tau_{n-1})-\delta(\nu_k=i)
\sum_{\sigma\in A_i([a+1,k-1];\nu)}
  Q_{i,\nu_{k+1}}(x_a,\st{x_{s}}_{s\in\sigma}, x_{k+1};x_{k})\\
&&\hs{35ex}
\bl\uprod_{s\in [a+1,k-1]\setminus\sigma}\tau_{s-1}\br\tau_{k+1}\cdots\tau_{n-1}
  e(\mu).
  \eneqn


  Hence we have  
  \eqn
&&h_a(\tau_ku)-\tau_kh_a(u)
=-  \delta(\nu_{k}=i) 
  \sum\limits_{\sigma\in A_i[a+1,k-1]}
Q_{i,\nu_{k+1}}(x_a,\st{x_{s}}_{s\in\sigma}, x_{k+1};x_{k})\\
&&\hs{30ex}
\bl\uprod_{s\in ([a+1,k-1]\setminus\sigma)}\tau_{s-1}\br
\tau_{k+1}\cdots\tau_{n-1}\bl r(\tau_1\cdots\tau_{a-1}u)\tens\ang{i}_z\br\\
&&=-  \delta(\nu_{k}=i) 
  \sum\limits_{\sigma\in A_i[a+1,k-1]}
Q_{i,\nu_{k+1}}(\st{x_{s}}_{s\in\sigma\cup\st{a}}, x_{k+1};x_{k})
\tau_{k+1}\cdots\tau_{n-1}\\
&&\hs{40ex}\Bigl( r\bl(\uprod_{s\in [a+1,k-1]\setminus\sigma}\tau_s)\tau_1\cdots\tau_{a-1}u\br\tens\ang{i}_z\Bigr)\\
&&=-  \delta(\nu_{k}=i) 
  \sum\limits_{\sigma\in A_i[a+1,k-1]}
Q_{i,\nu_{k+1}}(\st{x_{s}}_{s\in\sigma\cup\st{a}}, x_{k+1};x_{k})
\tau_{k+1}\cdots\tau_{n-1}\\
&&\hs{40ex}\Bigl( r\bl(\uprod_{s\in [1,k-1]\setminus(\sigma\cup\st{a})}\tau_s)u)
  \tens\ang{i}_z\Bigr).
 \eneqn

 Hence we obtain
  \eqn
&&h_a(\tau_ku)-\tau_kh_a(u)
=-  \delta(\nu_{k}=i)
\sum_{\sigma\in A_i[a+1,k-1]}X(\sigma\cup\st{a},\emptyset).
\eneqn
 \snoi
 (Cb)\ We have
 \eqn
\delta(\nu_{k+1}=i) h_k(\tau_ku)&&=
 \delta(\nu_{k+1}=i) \tau_k\cdots\tau_{n-1}\bl
 r(\tau_1\cdots\tau_{k-1}\tau_ku)\tens\ang{i}_z\br\\
&&= \delta(\nu_{k+1}=i) \tau_{k}h_{k+1}(u).
\eneqn




  \snoi
 (Cc)\ We have
 \eqn
&&\hs{-3ex} \delta(\nu_{k}=i)h_{k+1}(\tau_ku)=\delta(\nu_{k}=i)
 \tau_{k+1}\cdots\tau_{n-1}\bl
 r(\tau_1\cdots\tau_{k}\tau_{k}u)\tens\ang{i}_z\br\\
 && =\delta(\nu_{k}=i)\hs{-2ex}   \sum\limits_{\sigma\in A_{i}[1,k-1]}
 \hs{-2ex}
\tau_{k+1}\cdots\tau_{n-1}\Bigl( r\bl
 Q_{i,\nu_{k+1}}(x_1,\st{x_{1+s}}_{s\in\sigma},;x_{k+1})
 (\uprod_{s\in[1,k-1]\setminus\sigma}\tau_s)u\br\tens\ang{i}_z\Bigr)\\
 && =\delta(\nu_{k}=i)   \sum\limits_{\sigma\in A_{i}[1,k-1]}
\tau_{k+1}\cdots\tau_{n-1}
  Q_{i,\nu_{k+1}}(x_n,\st{x_{s}}_{s\in\sigma},;x_{k})
\Bigl( r\bl
(\uprod_{s\in[1,k-1]\setminus\sigma}\tau_s)u\br\tens\ang{i}_z\Bigr)\,.
\eneqn
Here the second equality follows from Lemma~\ref{lem:tauQ}.

Take $\mu\in I^n$ such that $e(\mu) r\bl
(\uprod_{s\in[1,k-1]\setminus\sigma}\tau_s)u\br\tens\ang{i}_z\br
 =r\bl
(\uprod_{s\in[1,k-1]\setminus\sigma}\tau_s)u\br\tens\ang{i}_z\br$.
Then, we have
$\mu_n=i$ and $\mu_s=\nu_{s+1}$ for $s\in[k+1,n-1]$.
Hence Sublemma~\ref{sub:Qq} implies that
\eqn
&&\delta(\nu_{k}=i)\tau_{k+1}\cdots\tau_{n-1}
  Q_{i,\nu_{k+1}}(x_n,\st{x_{s}}_{s\in\sigma},;x_{k})e(\mu)\\
&&\hs{10ex}=\delta(\nu_{k}=i)\sum_{\gamma\in A_i[k+2,n]}
  Q_{i,\nu_{k+1}}(x_{k+1},\st{x_{s}}_{s\in\gamma},
  \st{x_{s}}_{s\in\sigma};x_{k})
  \bl\uprod_{s\in[k+2,n]\setminus\gamma}\tau_{s-1}\br  e(\mu).
\eneqn

Thus we obtain
\eqn
&&\delta(\nu_{k}=i)h_{k+1}(\tau_ku)\\
&&\hs{15ex}=\delta(\nu_{k}=i)\hs{-2ex}\sum_{\substack{\gamma\in A_i[k+2,n]\\\sigma\in  A_{i}[1,k-1]}}\hs{-2ex}
Q_{i,\nu_{k+1}}(x_{k+1},\st{x_{s}}_{s\in\gamma},
\st{x_{s}}_{s\in\sigma},;x_{k})\\
&&\hs{30ex}\bl\uprod_{s\in[k+2,n]\setminus\gamma}\tau_{s-1}\br 
\Bigl( r\bl
(\uprod_{s\in[1,k-1]\setminus\sigma}\tau_s)u\br\tens\ang{i}_z\Bigr).
\eneqn
In terms of $X(\sigma,\gamma)$ in \eqref{eq:X},
we have
\eqn
&&\delta(\nu_{k}=i)h_{k+1}(\tau_ku)
=\delta(\nu_{k}=i)\hs{-2ex}\sum_{\substack{\gamma\in A_i[k+2,n]\\\sigma\in  A_{i}[1,k-1]}}X(\sigma,\gamma).
\eneqn

\snoi
(Cd)\ We have
  \eqn
\delta(\nu_{k}=i) \tau_{k}h_k(u)&&=
 \delta(\nu_{k}=i) \tau_k\tau_k\cdots\tau_{n-1}\bl
 r(\tau_1\cdots\tau_{k-1}u)\tens\ang{i}_z\br\\
 &&= \delta(\nu_{k}=i) Q_{i,\nu_{k+1}}(x_{k+1},x_{k})\tau_{k+1}
 \cdots\tau_{n-1}
 \bl r(\tau_1\cdots\tau_{k-1}u)\tens\ang{i}_z\br\\
&& =\delta(\nu_{k}=i)X(\emptyset,\emptyset).
\eneqn


\snoi
(Ce)\ Assume that $1\le k<a-1$, then we have
\eqn
&&\tau_1\cdots\tau_{a-1}\tau_{k}u\\
&&\hs{3ex}=\tau_{k+1}(\tau_1\cdots\tau_{a-1})u
-  \delta(\nu_{k}=i) \hs{-3ex}
  \sum\limits_{\sigma\in A_{i}[1,k-1]}\hs{-3ex}
  Q_{i,\nu_{k+1}}(x_1,\st{x_{s+1}}_{s\in\sigma}, x_{k+2};x_{k+1})
   \\&&\hs{35ex}
  \bl\hs{-3ex}
\uprod_{s\in([1,k-1]\setminus\sigma)\cup[k+2,a-1]}\tau_s\br u.
\eneqn
Hence we have
\eqn
&&r(\tau_1\cdots\tau_{a-1}\tau_{k}u)\tens\ang{i}_z\\
&&=\tau_{k}\bl r(\tau_1\cdots\tau_{a-1})u\tens\ang{i}_z\br
-\delta(\nu_{k}=i) \hs{-3ex}
\sum\limits_{\sigma\in A_{i}[1,k-1]}\hs{-3ex}
Q_{i,\nu_{k+1}}(x_n,\st{x_{s}}_{s\in\sigma}, x_{k+1};x_{k})
\\&&
\hs{30ex}
 \bl r(\hs{-3ex}
  \uprod_{s\in ([1,k-1]\setminus\sigma)\cup[k+2,a-1]}\tau_s u)
  \tens\ang{i}_z\br.
  \eneqn
  Take $\mu\in I^n$ such that
  $e(\mu)r(\hs{-3ex}
  \uprod_{s\in ([1,k-1]\setminus\sigma)\cup[k+2,a-1]}\tau_s u)=r(\hs{-3ex}
  \uprod_{s\in ([1,k-1]\setminus\sigma)\cup[k+2,a-1]}\tau_s u)$.
  Then, we have
  $\mu_{n}=i$, $\mu_s=\nu_{s+1}$ for $s\in[a+1,n-1]$.
  Hence, Lemma~\ref{lem:tauQ} implies that
  \eqn
  &&\delta(\nu_{k}=i)\tau_a\cdots\tau_{n-1}
  Q_{i,\nu_{k+1}}(x_n,\st{x_s}_{s\in\sigma}, x_{k+1};x_k)e(\mu)\\
  &&=\delta(\nu_{k}=i)\sum\limits_{\gamma\in A_{i}[a+1,n]}
  Q_{i,\nu_{k+1}}(x_a,\st{x_{s}}_{s\in\gamma},
\st{x_s}_{s\in\sigma}, x_{k+1};x_k)
\bl\uprod_{s\in[a+1,n]\setminus\gamma}\tau_{s-1}\br e(\mu).
\eneqn
Hence
\eqn
&&h_a(\tau_ku)=\\
&&\hs{5ex}=(\tau_a\cdots\tau_{n-1}\tau_k)r(\tau_1\cdots\tau_{a-1}u)\\
&&\hs{15ex}-\delta(\nu_{k}=i)\sum\limits_{\substack{\gamma\in A_{i}[a+1,n]\\\sigma\in A_i[1,k-1]}}
   Q_{i,\nu_{k+1}}(x_a,\st{x_{s}}_{s\in\gamma},
\st{x_s}_{s\in\sigma}, x_{k+1};x_k)\\
&&\hs{15ex}\bl\uprod_{s\in[a+1,n]\setminus\gamma}\tau_{s-1}\br
\bl r(\hs{-3ex}
  \uprod_{s\in ([1,k-1]\setminus\sigma)\cup[k+2,a-1]}\tau_s u)
  \tens\ang{i}_z\br\\
  &&\hs{5ex}  =\tau_kh_a(u)\\
  &&\hs{15ex}-\delta(\nu_{k}=i)
  \sum\limits_{\substack{\gamma\in A_{i}[a+1,n]\\\sigma\in A_i[1,k-1]}}
   Q_{i,\nu_{k+1}}(\st{x_{s}}_{s\in\gamma\cup\st{a}},
\st{x_s}_{s\in\sigma}, x_{k+1};x_k)\\
&&\hs{25ex}\bl\uprod_{s\in[a+1,n]\setminus\gamma}\tau_{s-1}\br
\bl\uprod_{s\in[k+2,a-1]}\tau_{s-1}\br
\bl r(\hs{-3ex}
  \uprod_{s\in [1,k-1]\setminus\sigma}\tau_s u)
  \tens\ang{i}_z\br\\
    && \hs{5ex} =\tau_kh_a(u)\\
  &&\hs{15ex}-\delta(\nu_{k}=i)\sum\limits_{\substack{\gamma\in A_{i}[a+1,n]\\\sigma\in A_i[1,k-1]}}
   Q_{i,\nu_{k+1}}(\st{x_{s}}_{s\in\gamma\cup\st{a}},
\st{x_s}_{s\in\sigma}, x_{k+1};x_k)\\
&&\hs{25ex}\bl\uprod_{s\in[k+2,n]\setminus(\gamma\cup\st{a})}\tau_{s-1}\br\
\bl r(\hs{-3ex}
  \uprod_{s\in [1,k-1]\setminus\sigma}\tau_s u)
  \tens\ang{i}_z\br.
  \eneqn

  Hence if $1\le k< a-1$, then we obtain
  \eqn
  &&  h_a(\tau_ku)-\tau_kh_a(u)
  =-\delta(\nu_{k}=i)\sum\limits_{\substack{\gamma\in A_{i}[a+1,n]\\\sigma\in A_i[1,k-1]}}X(\sigma,\gamma\cup\st{a}).
  \eneqn

\mnoi
(Cf)\ 
Now, we shall calculate $J_M(\tau_ku)-\tau_kJ_M(u)$.
 \eqn
 &&J_M(\tau_ku)-\tau_kJ_M(u)\\
&&=\sum_{a=1}^{k-1}\delta(\nu_a=i)\bl h_a(\tau_ku)-\tau_kh_a(u)\br\\
&&\hs{3ex}+\delta(\nu_k=i)h_{k+1}(\tau_ku)+\delta(\nu_{k+1}=i)h_k(\tau_ku)
-\delta(\nu_k=i)\tau_kh_k(u)-\delta(\nu_{k+1}=i)\tau_kh_{k+1}(u)\\
&&\hs{10ex}+\sum_{a=k+2}^{n-1}\delta(\tau_a=i)\bl h_a(\tau_ku)-\tau_kh_a(u)\br.
\eneqn
We have
\eqn
\sum_{a=1}^{k-1}\delta(\nu_a=i)\bl h_a(\tau_ku)-\tau_kh_a(u)\br
&&=-  \delta(\nu_{k}=i) 
 \sum_{a=1}^{k-1}\delta(\nu_a=i) \sum\limits_{\sigma\in A_i[a+1,k-1]}
 X(\sigma\cup\st{a},\gamma)\\
&&=-\delta(\nu_k=i)
\sum\limits_{\sigma\in A_i[1,k-1]\setminus\st{\emptyset}}
X(\sigma,\gamma),
\eneqn
and
\eqn
\sum_{a=k+2}^{n-1}\delta(\tau_a=i)\bl h_a(\tau_ku)-\tau_kh_a(u)\br
&&= -\sum_{a=k+2}^{n-1}\delta(\nu_a=i) \sum\limits_{\substack{\gamma\in A_{i}[a+1,n-1]\\\sigma\in A_i[1,k-1]}}
X(\sigma,\gamma\cup\st{a})\\
 &&= -\delta(\nu_{k}=i)\sum\limits_{\substack{\gamma\in A_{i}[k+2,n]\setminus\st{\emptyset}\\\sigma\in A_i[1,k-1]}}
X(\sigma,\gamma).  \eneqn

  Hence, we have
\eqn
&&J_M(\tau_ku)-\tau_kJ_M(u)\\
&&\hs{8ex}=- \delta(\nu_k=i)\hs{-4ex}\sum\limits_{\sigma\in A_i[1,k-1]\setminus\st{\emptyset}}\hs{-4ex}
X(\sigma,\emptyset)
+\delta(\nu_{k}=i)\hs{-2.5ex}\sum_{\substack{\gamma\in A_i[k+2,n]\\\sigma\in  A_{i}[1,k-1]}}\hs{-2.5ex}
X(\sigma,\gamma)\\
&&\hs{30ex}- \delta(\nu_{k}=i)X(\emptyset,\emptyset)
 -\hs{-3ex}\sum\limits_{\substack{\gamma\in A_{i}[k+2,n]\setminus\st{\emptyset}\\\sigma\in A_i[1,k-1]}}\hs{-4ex}
 X(\sigma,\gamma)\\
 &&\hs{8ex}=0.
    \eneqn
\QED
