 \includegraphics[scale=0.5]{BR-a.pdf} \hspace{0.2cm}\includegraphics[scale=0.5]{BR-b.pdf}\\ \vspace{0.2cm}
 \includegraphics[scale=0.5]{BR-c.pdf} \hspace{0.2cm}\includegraphics[scale=0.5]{BR-d.pdf}
 \caption{\em \small Decay branching ratios of the sterile neutrino, as function of its mass, for the four benchmarks: (A) $\mathcal{C}_B=0$, (B) $d_W=d_Z$, (C) $d_Z=0$ and (D) $d_W=0$.}\label{fig:BRs}
