\section{Large rational surgeries on L-space links} \label{sec:rational-surgeries}

A link $\mathbb{L} \subset S^3$ with $n$ components is called an \emph{L-space link} \cite{gorsky-nemethi} if there is some $C=C(\mathbb{L})$ such that for every choice of \emph{integers} $a_1,\dots,a_n \geq C$, the Dehn surgery \[ \mathbb{L}(a_1,\dots,a_n) \] is an L-space.  In fact, this is still true if we allow the $a_i$ to be rational.

\begin{proposition} \label{prop:lspace-rational}
Let $\mathbb{L}$ be an L-space link with $n$ components.  Then there is an integer $C'=C'(\mathbb{L})$ such that \[ \mathbb{L}(a_1,\dots,a_n) \] is an L-space for every choice of \emph{rational} slopes $a_1,\dots,a_n \geq C'$.
\end{proposition}

To set the stage, we let $\ell_{ij}$ be the linking number of the $i$th and $j$th components of $\mathbb{L}$.  We then define
\[ f(x_1,\dots,x_n) = \det\begin{pmatrix}
x_1 & \ell_{12} & \ell_{13} & \dots & \ell_{1n} \\
\ell_{21} & x_2 & \ell_{23} & \dots & \ell_{2n} \\
\ell_{31} & \ell_{32} & x_3 & \dots & \ell_{3n} \\
\vdots & \vdots & \vdots & \ddots & \vdots \\
\ell_{n1} & \ell_{n2} & \ell_{n3} & \dots & x_n
\end{pmatrix}, \]
which has the property that if we write $a_i = \frac{p_i}{q_i}$ in lowest terms, with $q_i > 0$, then
\begin{equation} \label{eq:homology-L-surgery}
\left| H_1(\mathbb{L}(a_1,\dots,a_n); \Z) \right| =  \left| q_1q_2\dots q_n \cdot f(a_1,\dots,a_n) \right|.
\end{equation}
Moreover, expanding by minors along the $i$th row shows that $f$ is an affine function in each of the $x_i$: we can write
\begin{equation} \label{eq:f-det-affine}
f(x_1,\dots,x_n) = g_i(x_1,\dots,\widehat{x_i},\dots,x_n) \cdot x_i + h_i(x_1,\dots,\widehat{x_i},\dots x_n),
\end{equation}
where the notation ``$\widehat{x_i}$'' means that we have omitted $x_i$ from the list of inputs.

\begin{lemma} \label{lem:determinant-positive}
There exists $M = M(\mathbb{L}) > 0$ such that if $x_i \geq M$ for all $i$, then $f(x_1,\dots,x_n) > 0$.
\end{lemma}

\begin{proof}
We let $k = \max_{i\neq j} |\ell_{ij}|+1$, and set $M = n! \cdot k$, which depends only on the linking matrix of $\mathbb{L}$.  Then we can write
\[ f(x_1,\dots,x_n) = x_1x_2\dots x_n + \sum_{\sigma \in \mathcal{S}_n\setminus\{1\}} (-1)^\sigma p_\sigma, \]
where $p_\sigma$ is the product over all $i$ of the $(i,\sigma(i))$-entries of the matrix whose determinant is $f$.  When $\sigma \neq 1$, at least one of these entries is not a diagonal entry, so if the non-diagonal entry is $\ell_{j,\sigma(j)}$ and all of the $x_i$ satisfy $x_i \geq M \geq k$, then we have
\[ \left| \frac{p_\sigma}{x_1x_2\dots x_n}\right| \leq \left| \frac{x_1\dots x_{j-1} \cdot \ell_{j,\sigma(j)} \cdot x_{j+1} \dots x_n}{x_1x_2\dots x_n} \right| = \frac{|\ell_{j,\sigma(j)}|}{x_j} < \frac{k}{M} = \frac{1}{n!}. \]
This works for all $n!-1$ of the summands where $\sigma \neq 1$, so we can now use the above expression to bound $f$ below (assuming again that $x_i \geq M$ for all $i$) by
\[ f(x_1,\dots,x_n) \geq x_1x_2\dots x_n \left(1 - (n!-1)\frac{1}{n!}\right) > 0. \qedhere \]
\end{proof}

\begin{remark}
We do not claim that $M=n!\cdot k$ is anywhere near optimal; it can certainly be improved by using Ostrowski's inequality, as in the proof of Lemma~\ref{lem:L-space}.
\end{remark}

\begin{proof}[Proof of Proposition~\ref{prop:lspace-rational}]
Since $\mathbb{L}$ is an L-space link, there is a constant $C$ such that $\mathbb{L}(a_1,\dots,a_n)$ is an L-space whenever the $a_i$ are integers greater than or equal to $C$.  We take $M$ as provided by Lemma~\ref{lem:determinant-positive}, and let $C' = \max(C,M)$.  Our goal is to show that $\mathbb{L}(a_1,\dots,a_n)$ is an L-space whenever all of the $a_i$ are \emph{rational} and satisfy $a_i \geq C'$.  Certainly this is true when all of the $a_i$ are integers, because $C' \geq C$.

Suppose that we have some rational slopes $a_1,\dots,a_n \geq C'$, written $a_i = \frac{p_i}{q_i}$ in lowest terms with $q_i > 0$, such that the manifold 
\[ Y = \mathbb{L}(a_1,\dots,a_n) \]
is not an L-space.  Then at least one of the $a_i$ must not be an integer; we let $d \in \{1,\dots,n\}$ be the maximal such index, so that $a_d$ is not an integer but $a_{d+1},\dots,a_n \in \Z$.  We suppose that among all such tuples $(a_1,\dots,a_n)$, we have chosen this one to first minimize the value of $d$, and then to minimize the denominator $q_d$ among all such tuples with this value of $d$.  Since $a_d \not\in \Z$ we have $q_d \geq 2$, and then by the proof of \cite[Proposition~4.3]{bs-concordance} (which works equally well in Heegaard Floer homology) there exists a pair of fractions
\begin{align*}
a'_d &= \frac{p'}{q'}, &
a''_d &= \frac{p''}{q''},
\end{align*}
with $q',q'' \geq 1$ and $\lfloor a_d \rfloor \leq a'_d,a''_d \leq \lceil a_d \rceil$, such that 
\begin{enumerate}
\item we have $(p_d,q_d) = (p'+p'', q'+q'')$, and \label{i:mediant}
\item if we let
\begin{align*}
Y' &= \mathbb{L}(a_1,\dots,a_{d-1}, a'_d, a_{d+1},\dots, a_n), \\
Y'' &= \mathbb{L}(a_1,\dots,a_{d-1}, a''_d, a_{d+1},\dots,a_n),
\end{align*}
then there is a surgery exact triangle of the form
\begin{equation} \label{eq:surgery-triad}
\cdots \to \hfhat(Y') \to \hfhat(Y) \to \hfhat(Y'') \to \cdots .
\end{equation}
\end{enumerate}
In particular, item \eqref{i:mediant} says that either $a'_d \in \Z$ or $2 \leq q' < q_d$, so by our assumption of minimality we see that $Y'$ must be an L-space, and likewise for $Y''$.  Therefore \eqref{eq:surgery-triad} tells us that
\begin{equation} \label{eq:hfhat-upper-bound}
\rank \hfhat(Y) \leq \rank \hfhat(Y') + \rank \hfhat(Y'') = |H_1(Y';\Z)| + |H_1(Y'';\Z)|.
\end{equation}

Now if we write $Q = q_1\dots q_n$, then \eqref{eq:homology-L-surgery} and Lemma~\ref{lem:determinant-positive} tell us that
\begin{align*}
|H_1(Y';\Z)| &= \tfrac{Q}{q_d} \cdot q' \cdot f(a_1,\dots,a_{d-1},a'_d,a_{d+1},\dots,a_n) \\
|H_1(Y'';\Z)| &= \tfrac{Q}{q_d} \cdot q'' \cdot f(a_1,\dots,a_{d-1},a''_d,a_{d+1},\dots,a_n),
\end{align*}
in which the right side of each equation is positive because $a'_d, a''_d \geq \lfloor a_d \rfloor \geq C' \geq M$.  Applying \eqref{eq:f-det-affine} to these equations, we have
\begin{align*}
|H_1(Y';\Z)| &= \tfrac{Q}{q_d} \cdot q' \cdot \left( g_d(a_1,\dots,\widehat{a_d},\dots,a_n) \cdot a'_d + h_d(a_1,\dots,\widehat{a_d},\dots a_n)\right) \\
&= \tfrac{Q}{q_d} \left( g_d(a_1,\dots,\widehat{a_d},\dots,a_n) \cdot p' + h_d(a_1,\dots,\widehat{a_d},\dots a_n) \cdot q' \right)
\end{align*}
and likewise
\[ |H_1(Y'';\Z)| = \tfrac{Q}{q_d} \left( g_d(a_1,\dots,\widehat{a_d},\dots,a_n) \cdot p'' + h_d(a_1,\dots,\widehat{a_d},\dots a_n) \cdot q'' \right), \]
and we add these last two equations together to get
\begin{align*}
|H_1(Y';\Z)|+|H_1(Y'';\Z)| &= \tfrac{Q}{q_d} \left( g_d(a_1,\dots,\widehat{a_d},\dots,a_n) (p'+p'') \right. \\
&\qquad\qquad\left. + h_d(a_1,\dots,\widehat{a_d},\dots a_n) (q'+q'') \right) \\
&= \tfrac{Q}{q_d} \left( g_d(a_1,\dots,\widehat{a_d},\dots,a_n) p_d + h_d(a_1,\dots,\widehat{a_d},\dots a_n) q_d \right) \\
&= Q \cdot \left( g_d(a_1,\dots,\widehat{a_d},\dots,a_n) a_d + h_d(a_1,\dots,\widehat{a_d},\dots a_n) \right) \\
&= q_1\dots q_n \cdot f(a_1,\dots,a_n) \\
&= |H_1(Y;\Z)|.
\end{align*}
Now combining this with the upper bound \eqref{eq:hfhat-upper-bound} gives
\[ \rank \hfhat(Y) \leq |H_1(Y;\Z)| = \chi\left( \hfhat(Y) \right), \]
so equality must hold throughout.  In particular this means that $\hfhat(Y)$ has rank $|H_1(Y;\Z)|$, so $Y$ is an L-space as well and we have a contradiction.
\end{proof}


