\subsubsection{Construction of the graph:}
\par Real-world networks often exhibit high average clustering and low average distances between node pairs. Several studies have addressed these properties and proposed solutions for various tasks, such as Exphormer \citep{shirzad2023exphormer}. In this study, both speed and performance are critical considerations. Therefore, a fast graph construction method that preserves these graph characteristics was integrated into the model to enable real-time execution. An efficient approach was also proposed for constructing both lattice and random graphs over the text data.

\begin{algorithm}[!h]
    \caption{Graph generation process}
    \label{alg:gen_graph}
    \begin{algorithmic}[1]
        \State \textbf{Input:} $\mathcal{X}_t, metadata$
        \State \textbf{Output:} $graph\_data$
        \State $R_b, L_b, \textbf{p}_b \gets calculate\_graph(\mathcal{X}_t, metadata)$    
        \State $E \gets create\_edges(R_b, L_b, \textbf{p}_b)$
        \State $E \gets  \text{subsample\_edges}(E, \mathbf{p}_{ss,b})$
        \State $data \gets \text{Data}(x=\mathcal{X}_t, edge\_index=E)$
        \State \textbf{Return:} $data$
    \end{algorithmic}
    \footnotemark[1]{$\textbf{p}_b$: token position over the batch} \newline
    \footnotemark[2]{$L_b$: lattice links over the batch} \newline
    \footnotemark[3]{$R_b$: random links over the batch}
    \footnotemark[3]{$E$: Edge indices}
\end{algorithm}

\begin{algorithm}[!h]
    \caption{Graph metadata calculation}
    \label{alg:calc_graph_metadata}
    \begin{algorithmic}[1]
        \State \textbf{Input:} $\mathcal{X}_t, metadata$
        \State \textbf{Output:} $R_b, L_b, \textbf{p}_b$
        \State Calculate the number of tokens in the batch $|\mathcal{B}_t|$, in each document of the batch $|\mathcal{D}_n|$, the lower bound $l_n$, and upper bound $u_n$ of each document set $\mathcal{D}_n$.
        \State The tokens' positions in the batch $\textbf{p}_b$ and their positions in their documents $\textbf{p}_n$, all starting from $0$:
        \begin{equation} \label{eq:token_batch_pos}
          \textbf{p}_b = \{0, 1, 2, \dots, |batch tokens|-1\}
        \end{equation}
        \begin{equation} \label{eq:token_doc_pos}
          \textbf{p}_n = \left\{i - l_n \mid i \in \textbf{p}_b \wedge t_i \in \mathcal{D}_n\right\}
        \end{equation}
        \State Identify each token's document, its number in the document, and its number in the batch.
        \State Generate a random number for each token concerning the corresponding token's document length $|\mathcal{D}_n|$. Then, select $K_1$ random nodes to create links like Figure \ref{fig:random_graph_nodes} using the following formula:
        \begin{equation} \label{eq:gen_random_number}
          \mathbf{r}_{v_i} = \text{int}((2*|\mathcal{D}_n| + 1) \cdot \text{rand}())
        \end{equation}
        \begin{equation} \label{eq:gen_random_nodes}
          R_b = (((\mathbf{r}_{v_i} \mod |\mathcal{D}_n|) + \textbf{p}_n + 1) \mod |\mathcal{D}_n|) + l_n
        \end{equation}
        \State Generate an array of $K_2$ regular nodes to create lattice links like Figure \ref{fig:lattice_graph_nodes} using the following formula:
        \begin{equation} \label{eq:gen_lattice_nodes}
          \textbf{l}_{v_i} = \{m, m + \text{{s}}, m + 2\cdot\text{{s}}, \ldots, m + k\cdot\text{{s}}\}
        \end{equation}
        \begin{equation} \label{eq:gen_lattice_nodes2}
          L_b = ((\textbf{l}_{v_i} + \textbf{p}_n) \mod |\mathcal{D}_n|) + l_n
        \end{equation}
    \end{algorithmic}
\end{algorithm}

\par To construct the graph, each token is treated as a node. Figures \ref{fig:random_graph_nodes}, \ref{fig:lattice_graph_nodes}, and \ref{fig:node_ids_arrangement} illustrate the final arrangement of random and lattice edges used to establish the graph structure. The random edges are regenerated in each iteration to prevent rapid overfitting and enhance the model's generalizability.

\begin{algorithm}[!h]
    \caption{sub-sampling and clustering edges}
    \label{alg:clustering_edge}
    \begin{algorithmic}[1]
        \State \textbf{Input:} $E$, $\mathbf{p}_{ss,b}$, $p_{keep}$
        \State \textbf{Output:} $E$
        \State $p_E=\text{sum}(\mathbf{p}_{ss,b}[E], axis=0)$
        \State $keep\_count=int(p_{keep} * \frac{edge\_count}{head})$
        \State $top\_k\_indices \gets \text{topk}(p_E, keep\_count, axis=0)$
        \State $E \gets E[top\_k\_indices]$
        \State \textbf{return} $E$
    \end{algorithmic}
    \footnotemark[1]{$P_{keep}$ is the ratio of the edge counts to keep.}
\end{algorithm}
