\begin{abstract}
We offer detailed proofs of some properties of the Rule 60 cellular automaton on a ring with a Mersenne number circumference. We then use these properties to define a propagator, and demonstrate its use to construct all the ground state configurations of the classical Newman-Moore model on a square lattice of the same size. In this particular case, the number of ground states is equal to half of the available spin configurations in any given row of the lattice.  
\end{abstract}

\keywords{Rule 60, Newman-Moore, spin lattice, triangular plaquette, Mersenne number, cellular automaton
}



\section{Introduction}

Both the classical Newman-Moore model (a particular two-dimensional spin lattice model with a specific three-spin interaction) \cite{newman1999_5068} and its quantum counterpart \cite{yoshida2014quantumcriticalityisingmodel} play an important role in studies of systems with glassy dynamics (see, for example,\cite{PhysRevE.72.016103, PhysRevE.62.3404} and references therein). Ground states of this 2D model are related to the time propagation of a 1D Rule 60 cellular automaton \cite{sfairopoulos2023_174107}. In this paper, we  will first recap some standard definitions used throughout the paper, then offer detailed proofs of some number-theoretic properties of the Rule 60 cellular automaton on a ring with Mersenne number circumference. Finally, we will use this knowledge to define a propagator which can be used to infer all ground state configurations of the classical Newman-Moore model on a square lattice of the same size.

\section{Rule 60 cellular automaton}
%
For the binary one-dimensional cellular automaton \cite{martin1984_219}, 
the state of the system at the instant of time $j$ is given by a length $L$ string: %of binary numbers

%
\begin{align}
%
\vec{x}_{j} = [x_{0,j},\,x_{1,j},\,\ldots\,\,x_{i,j},\,\ldots,\,x_{L-1,j}]\,\,,
\label{state_structule}
%
\end{align}
%
where $x_{i,j}$ is the state of the $i$'th bit at time $j$. Each $x_{i,j}$ is either $0$, if the site is unoccupied, or $1$, if the site is occupied. 

Consider a Rule 60 automaton \cite{martin1984_219} on a ring of a circumference $L$. According to the rule, with this periodic boundary condition the state of the automaton at the instance of time $j+1$ is related to its state at time $j$ by 
%
\begin{align}
%
\begin{array}{lcc}
x_{i,j+1} = \text{Xor}(x_{i-1,j},\,x_{i,j}) & \text{ for } & i=1,\,2,\,\ldots,\,L-1
\\
x_{0,j+1}=\text{Xor}(x_{L-1,j},\,x_{0,j}) & \text{ for } & i=0 \qquad \qquad \qquad
\\
j= 0,\,1,\,\ldots \quad.
\end{array}
\label{rule_60}
%
\end{align}
%

%
\subsection{Periodic trajectories}
%
In what follows, we will be interested in periodic trajectories generated by the rule \eqref{rule_60}.  
%
\begin{definition}
%
An initial condition $\vec{x}_{0}$ initiates a \textbf{$\bm{M}$-periodic trajectory} $\left\{\vec{x}_{j}\right\}_{j=0}^{\infty}$
if 
%
\begin{align*}
%
&
\vec{x}_{M} = \vec{x}_{0}
\,\,.
%    
\end{align*}
%
%
\label{def:period}
\end{definition}
%



%
\begin{definition}
%
An initial condition $\vec{x}_{0}$ initiates a \textbf{$\bm{M}$-fundamental-periodic trajectory} $\left\{\vec{x}_{j}\right\}_{j=0}^{M-1}$
if 
%
\begin{align*}
%
&
\vec{x}_{M} = \vec{x}_{0}
\\
&
\text{and}
\\
&
\text{for any } 0<j<M, \quad \vec{x}_{j}\neq \vec{x}_{0}
\,\,.
%    
\end{align*}
%
%
\end{definition}
%

%
\subsection{Configurations and their characterization}
%
%
The state of the system at a given instant of time is called 
a \textbf{configuration}. E.g.\ for the trajectory
%
\begin{align*}
%
\begin{array}{lll}
j=0 &
&
[100]
\\
j=1 &
&
[110]
\\
j=2 &
&
[101]
\\
j=3 &
&
[011]
\\
&\ldots&
\end{array}
\,\,,
%    
\end{align*}
%
$[101]$ is the state of the size $L = 3$ lattice at the instance of time $j=2$, given that the initial condition at $j=0$ was $[100]$.
%
\begin{definition}
%
Let $_{L}N_{\text{occupied}}$-type state indicate a configuration that features $N_{\text{occupied}}$ total occupied sites on a length $L$ lattice. 
%
\end{definition}
%
E.g. $[110]$ will be characterised as a configuration of a $_{3}2$-type.



%==================================
\subsection{Useful lemmas}

In this section we present some lemmas which will be used to prove later statements about the time evolution of the Rule 60 automaton.
%
%
\begin{lemma}
%
For any $L$, there are as many $_{L}(\text{\rm even})$-type as there are $_{L}(\text{\rm odd})$-type states.
\label{lem:total_even=total=odd}
%
\end{lemma}
%
%
\begin{proof}
%
One can establish a one-to-one correspondence between $_{L}(\text{\rm even})$ and $_{L}(\text{\rm odd})$ states simply by controlling the state of the first bit, leaving other bits unchanged. 
%
\end{proof}
%

%
\begin{lemma}
%
For any $L$, the state $[00\ldots 0]$ is a stationary state (a $1$-periodic trajectory). 
\label{lem:all_0s}
%
\end{lemma}
%
%
\begin{proof}
%
This directly follows from the rule \eqref{rule_60}.
%
\end{proof}
%

%
\begin{lemma}
%
For any ring of circumference $L$, both $_{L}(\text{\rm odd})$-type and 
$_{L}(\text{\rm even})$-type states become an $_{L}(\text{\rm even})$-type state after one time step: 
%
\begin{align*}
%
&
_{L}(\text{\rm odd}) \to _{L}(\text{\rm even})
\\
&
_{L}(\text{\rm even}) \to _{L}(\text{\rm even})
\,\,.
%
\end{align*}
% 
\label{lem:odd_and_even_to_even}
%
\end{lemma}
%
%
\begin{proof} One proof is presented in \cite{martin1984_219} as Lemma 3.1. We present an alternative proof here.
%
Assume that the state of the system at an instance $j$ is 
\[
[x_{0,j},\,x_{1,j},\,\ldots\,\,x_{i,j},\,\ldots,\,x_{L-1,j}]
\,\,.\]
According to the rule \eqref{rule_60}, at the next step, $1$'s will be marking points where 
the site state changes from $0$ to $1$ or vice versa, along the lattice. For example, in 
%
\begin{align*}
%
\begin{array}{lll}
\vec{x}_{j} &=&    [011\bm{01}1001]
\\
\vec{x}_{j+1} &=& [1101\bm{1}0101]
\end{array}
\,\,,
%
\end{align*}
%
the boldface ``$1$'' at $j+1$ marks a lateral switch from ``$0$'' to ``$1$'', in bold, at $j$. Likewise in 
%
\begin{align*}
%
\begin{array}{lll}
\vec{x}_{j} &=&    [\bm{0}1101100\bm{1}]
\\
\vec{x}_{j+1} &=& [\bm{1}10110101]
\end{array}
\,\,,
%
\end{align*}
%
the boldface ``$1$'' at $j+1$ marks a lateral switch from ``$1$'' to ``$0$'' (in boldface), as the ring closes. 

Observe now that on a ring, the site state can only change laterally an \emph{even} number of times. This proves the Lemma.
%
\end{proof}
%
%
\begin{corollary}
%
Type $_{L}(\text{\rm odd})$ can not initiate a periodic motion.
\label{cor:no_periods_for_odd}
%
\end{corollary}
%
%
\begin{proof}
%
For an $M$-periodic motion, the state must return to itself after $M$ steps. But according to the 
Lemma \ref{lem:odd_and_even_to_even}, an $_{L}(\text{\rm odd})$-type state can never become 
an $_{L}(\text{\rm odd})$-type state.  
%
\end{proof}
%


%
\begin{lemma}
%
Let $M_{\text{\rm max}}$ be the maximum fundamental period for a given $L$. Let $M_{\mathcal{P}}$ be the period emerging from trajectories generated by the $_L 1$ initial state. Then 
\[M_{\text{\rm max}} = M_{\mathcal{P}} \,\,.\] Other periods divide $M_{\text{\rm max}}$.
\label{lem:maximal_M_and_shorter_periods}
%
\end{lemma}
%
%
\begin{proof}
%
The Lemma \ref{lem:maximal_M_and_shorter_periods} appears in \cite{ehrlich1990_302} as Theorem 1. An alternative formulation related to cyclotomic polynomials is given in \cite{BREUER2007293}, Proposition 3.6.
%
\end{proof}
%
%An explicit form of a propagator, for $L=2^n-1$ ($n=2,\,3,\,\ldots$) is given by equation \ref{explicit_propagator} in Theorem \ref{prop_thrm}.

%
\begin{lemma}
%
%
Let k and n be positive integers. Then, the binomial coefficient $\binom{2^{n}}{k}$ is even for all $0<k<2^{n}$.
%
\label{lem:binimial_2^n}
%
\end{lemma}
%
Several proofs for this property are known, the following is perhaps the simplest one, adapted from \cite{schepler2019_3087725} with minor changes.
%
\begin{proof}
%
According to the binomial theorem, 
\[
(x+1)^{2^{n}} = \sum_{k=0}^{2^{n}} \binom{2^{n}}{k} x^{k}
\,\,.
\]
Therefore the lemma will be established if we prove that for all positive integer $n$ there is some integer $a_k$ for each $0<k<2^{n}$ such that
\begin{align}
(x+1)^{2^{n}} = x^{2^{n}} + 1 + \sum_{k=1}^{2^{n}-1} 2a_k\, x^{k}
\,\,.
\label{induction_identity}
\end{align}
We will prove this by induction on $n$. First we prove the base case where $n=1$, so that 
\[
(x+1)^{2^{n}} = (x+1)^{2} = x^2 + 1 + 2x
\,\,.
\]
which has the form of \eqref{induction_identity} with $a_1 = 1$.

The induction hypothesis is that this property holds for $n = m$, for a given $m \ge  1$, so that 
\[
(x+1)^{2^{m}} =  x^{2^{m}} + 1 + \sum_{k=1}^{2^{m}-1}2 a_k\, x^{k}
\,\,.
\]
We now prove the property holds for $m+1$:
%
\begin{align*}
%
(x+1)^{2^{m+1}} 
&= \left((x+1)^{2^{m}}\right)^2
\end{align*}
By the induction hypothesis this is 
\begin{align*}
\left((x+1)^{2^{m}}\right)^2 &=
\left(x^{2^{m}} + 1 + \sum_{k=1}^{2^{m}-1} 2 a_k\, x^{k}\right)^2
\\
&=
\left\{
\left(x^{2^{m}} + 1\right)^2 
\right\}
+
\left\{
2 \left(x^{2^{m}} + 1\right)\left(2\sum_{k=1}^{2^{m}-1} a_k\, x^{k}\right)
\right\}\\
& \qquad +
\left\{
\left(2\sum_{k=1}^{2^{m}-1} a_k\, x^{k}\right)^2
\right\}
\\
&=
x^{2^{m+1}} + 1 + 2\, x^{2^{m}} 
\\
& \quad 
+ 4 \left\{\left(x^{2^{m}} +1 \right) \sum_{k=1}^{2^{m}-1} a_k\, x^{k} +\left(\sum_{k=1}^{2^{m}-1} a_k\, x^{k}\right)^2\right\}
\end{align*}
% 
The first two terms to the right of the final equality are the first two terms of \eqref{induction_identity} with $n =m+1$. The binomial theorem applied to $(x+1)^{2^{m+1}}$ produces these same two terms, and then a polynomial in $x$ with powers running from $1$ to $2^{m+1}-1$, inclusive. Because all terms in this particular remainder are multiplied either by two or by four, they are all explicitly even, and the resulting polynomial will be sums of even numbers, which must therefore also be even. So it is possible to find numbers $b_k$ such that
\[
(x+1)^{2^{m+1}} =  x^{2^{m+1}} + 1 + \sum_{k=1}^{2^{m+1}-1}2 b_k\, x^{k}
\,\,.
\]
In particular,
\[
 b_{k}=\begin{cases}
        2a_{1}, & \text{for $k=1$;}\\
        2a_{k}+\sum_{m=1}^{k-1}a_{k-m}a_{m}, & \text{for $k=2,\,\ldots,\,2^{m}-1$;}\\
        1+2\sum_{m=1}^{2^{m}-1}a_{2^m-m}a_{m},  & \text{for $k=2^m$;}\\
        2a_{k-2^m}+\sum_{m=k-2^m+1}^{2^m-1}a_{m}a_{k-m}, & \text{for $k=2^m + 1,\,\ldots,\,2^{m+1}-2$; and}\\
        2a_{2^m-1}, & \text{for $k=2^{m+1}-1$.}
       \end{cases}
\]

%
\end{proof}
%

